export const appPoliticsQuestions: AppPoliticsQuestion[] = [
  {"id":"q-mayuan-1","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"辩证唯物主义认识论认为，检验认识真理性的唯一标准是（　　）","options":[{"key":"A","text":"多数人的意见"},{"key":"B","text":"社会实践"},{"key":"C","text":"科学理论"},{"key":"D","text":"逻辑推理"}],"answerKey":"B","explanation":"真理是主观与客观相符合，只有把认识拿到实践中检验，才能判定它是否与客观实际相符。多数人的意见可能错（A 错）；科学理论与逻辑推理都是认识本身，不能自己检验自己（C、D 错）。","tags":["实践","认识论","单选题"]},
  {"id":"q-mayuan-2","type":"material","module":"马克思主义基本原理","difficulty":2,"stem":"结合材料，说明实践与认识的辩证关系。","material":{"title":"材料","paragraphs":["某地在推进乡村产业调整时，最初照搬外地经验引种经济作物，结果因气候与土壤条件不符而减产。当地随后组织技术人员驻村调查，重新测土配方、调整品种，并逐年根据市场行情修正种植结构，收益才逐步稳定下来。"]},"answerPoints":["实践是认识的来源和基础。该地一开始不了解本地条件，只有在实际种植失败后，才通过调查获得对气候、土壤的真实认识。","实践是认识发展的动力。减产暴露了原有认识的不足，推动当地去测土配方、重新选种，使认识不断深化。","实践是检验认识真理性的唯一标准。方案是否可行，最终要靠当年的收成和收益来判定，而不是靠事先的设想。","认识对实践具有反作用。修正后的种植方案指导了后续生产并取得稳定收益，说明正确认识能推动实践发展。"],"explanation":"作答要「材料 + 原理」对应着写：每一条原理后面都要挂上材料中的具体情节（照搬失败 → 驻村调查 → 测土配方 → 收益稳定），不能只背原理而不结合材料。","tags":["实践与认识","材料分析题"]},
  {"id":"q-maozhongte-1","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"我们党的思想路线的核心是（　　）","options":[{"key":"A","text":"一切从实际出发"},{"key":"B","text":"理论联系实际"},{"key":"C","text":"实事求是"},{"key":"D","text":"在实践中检验和发展真理"}],"answerKey":"C","explanation":"党的思想路线可概括为「一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理」，其中**实事求是**是核心与精髓。A、B、D 都是这条路线的一部分，但不是核心。","tags":["实事求是","单选题"]},
  {"id":"q-maozhongte-2","type":"material","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"结合材料，说明为什么必须坚持理论联系实际。","material":{"title":"材料","paragraphs":["某社区在推进数字化便民服务时，起初直接采购了一套通用系统，但老年人使用困难、实际办事率不高。社区随后组织居民座谈，按需求精简功能、保留线下窗口并安排志愿者帮办，服务使用率明显提升。"]},"answerPoints":["理论来自实践，也必须回到实践中去接受检验。通用系统在别处可行，不代表在本社区直接可行。","实际条件决定具体做法。社区的人口结构、办事习惯和资源条件，是制定方案时必须考虑的出发点。","要坚持问题导向，在实践中修正方案。座谈、精简功能、保留线下窗口，都是根据实际反馈作出的调整。","坚持以人民为中心。衡量方案好坏的标准是居民是否真正用得上、办得成，而不是系统本身是否先进。"],"explanation":"这类题容易写成「口号 + 空话」。要抓住材料里的转折点（从「直接采购」到「组织座谈、精简功能」）来说明「一般理论必须结合具体实际」。","tags":["理论联系实际","材料分析题"]},
  {"id":"q-sixiu-1","type":"choice","module":"思想道德与法治","difficulty":1,"stem":"关于法律与道德的关系，下列说法正确的是（　　）","options":[{"key":"A","text":"法律调整的范围比道德更广"},{"key":"B","text":"道德靠国家强制力保证实施"},{"key":"C","text":"法律与道德相互支撑，共同维护社会秩序"},{"key":"D","text":"凡是法律禁止的，道德也一定谴责"}],"answerKey":"C","explanation":"道德调整的范围比法律更广（A 反了）；靠国家强制力保证实施的是法律，道德靠内心信念、社会舆论和传统习惯（B 错）；两者调整范围有交叉但不等同（D 太绝对）。法律与道德相辅相成，C 正确。","tags":["法治意识","单选题"]},
  {"id":"q-sixiu-2","type":"material","module":"思想道德与法治","difficulty":2,"stem":"结合材料，谈谈如何在日常学习生活中把道德要求与法治意识落到实处。","material":{"title":"材料","paragraphs":["在某高校的一个小组作业中，有同学直接复制了网络上的资料却未标注来源，组内对此出现分歧：有人认为「只要结果对就行」，也有人坚持应当注明出处并重新整理。最终小组决定逐条核对来源、补齐引用，并在提交前统一检查。"]},"answerPoints":["道德要求要落在具体行动上。诚实守信不是抽象口号，体现在如实标注来源、不把他人成果当作自己的。","法治意识要求尊重规则与权利。学术规范、著作权规则属于必须遵守的边界，不能以「结果对」为由绕过。","面对分歧要走正当程序。先沟通、再按规则处理，而不是靠多数压服或放任不管。","坚守需要内在支撑。理想信念提供长期方向，让人在「别人都这么做」时仍能做出正确选择。"],"explanation":"材料题答题要「观点 + 材料依据」成对出现。这里每个采分点都能在材料里找到落点（未标注来源、出现分歧、逐条核对、统一检查），不要脱离材料空谈道德与法治的关系。","tags":["理想信念","道德实践","材料分析题"]},
  {"id":"q-maozhongte-3","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"毛泽东思想是在我国新民主主义革命、社会主义革命和社会主义建设的实践过程中,在总结我国革命和建设正反两方面历史经验的基础上,逐步形成和发展起来的。标志着毛泽东思想开始萌芽的是","options":[{"key":"A","text":"关于新民主主义革命基本思想的提出"},{"key":"B","text":"关于农村包围城市、武装夺取政权的思想的提出"},{"key":"C","text":"反对本本主义的提出"},{"key":"D","text":"马克思主义中国化命题的明确提出"}],"answerKey":"A","explanation":"大革命时期，毛泽东在《中国社会各阶级的分析》《湖南农民运动考察报告》等著作中提出\n的关于新民主主义革命的基本思想，标志着毛泽东思想开始萌芽。A正确。毛泽东提出并深人阐\n述的农村包围城市、武装夺取政权的思想，对红军和农村革命根据地的建立、巩固和发展发挥着\n根本指导作用,标志着毛泽东思想的初步形成；《反对本本主义》是毛泽东写于1930年土地革命\n战争时期（不是大革命时期）的著作；1938年在党的六届六中全会上毛泽东明确提出了马克思主\n义中国化的命题。B、C、D错误。\n点拨注意区分：毛泽东思想的开始萌芽/初步形成/走向成熟/继续发展。毛泽东思想在大革命\n时期开始萌芽，在土地革命战争时期初步形成，在抗日战争时期走向成熟，并在解放战争时期\n和中华人民共和国成立后继续发展。中共七大把毛泽东思想确立为党的指导思想并写入党章。","tags":["肖四","第1套","单选题"]},
  {"id":"q-maozhongte-4","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"毛泽东《论十大关系》的报告,初步总结了我国社会主义建设的经验,明确提出要以苏为鉴,独立自主地探索适合中国情况的社会主义建设道路,标志着党探索中国社会主义建设道路的良好开端。毛泽东在《论十大关系》中提出的中国社会主义建设的基本方针是","options":[{"key":"A","text":"不要四面出击"},{"key":"B","text":"积极引导,稳步前进"},{"key":"C","text":"调动一切积极因素为社会主义事业服务"},{"key":"D","text":"实现工业、农业、国防和科学技术的现代化"}],"answerKey":"C","explanation":"《论十大关系》的报告确定了一个基本方针，就是“努力把党内党外、国内国外的一切积极\n的因素，直接的、间接的积极因素全部调动起来”，为社会主义建设服务。调动一切积极因素为社\n会主义事业服务，是党关于社会主义建设的一条极为重要的方针，对于最大限度地团结全国各族\n人民，为建设社会主义现代化国家而奋斗，具有长远的指导意义。C正确。","tags":["肖四","第1套","单选题"]},
  {"id":"q-maozhongte-5","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"高质量发展是新时代我国经济社会发展的鲜明主题，是全面建设社会主义现代化国家的首要仔务。推动高质量发展的战略基点是","options":[{"key":"A","text":"加快实现高水平科技自立自强"},{"key":"B","text":"加快构建新发展格局"},{"key":"C","text":"推进农业现代化"},{"key":"D","text":"更好统筹质的有效提升和量的合理增长"}],"answerKey":"B","explanation":"加快实现高水平科技自立自强，是推动高质量发展的必由之路；加快构建新发展格局，是推\n动高质量发展的战略基点；推进农业现代化是实现高质量发展的必然要求；更好统筹质的有效提\n升和量的合理增长是推动高质量发展的重要举措。B正确，A、C、D错误。","tags":["肖四","第1套","单选题"]},
  {"id":"q-maozhongte-6","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"党的二十届四中全会审议通过的《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》，对“扩大高水平对外开放，开创合作共赢新局面”作了专章部署，强调“稳步扩大制度型开放”“积极扩大自主开放”。其中，扩大市场准人和开放领域的重点是","options":[{"key":"A","text":"新兴产业"},{"key":"B","text":"服务业"},{"key":"C","text":"农业"},{"key":"D","text":"先进制造业"}],"answerKey":"B","explanation":"《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》指出，对接国际高标准\n经贸规则，以服务业为重点，扩大市场准入和开放领域，扩大单边开放领域和区域。B正确。\n点拨2025年3月28日，习近平在会见国际工商界代表时指出，降低市场准入门槛是我们接下来\n扩大开放的重点。2025年，我们将扩大一些方面开放试点，还将加快文化、教育等领域的\n开放。","tags":["肖四","第1套","单选题"]},
  {"id":"q-maozhongte-7","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"党的十八大以来，我们党把宗教工作摆在治国理政的重要位置，鲜明提出坚持我国宗教中国化方向等一系列新理念新举措，完善宗教工作体制机制，提高宗教工作法治化水平，推动新时代宗教工作取得积极成效。正确处理宗教领域各种矛盾和问题的根本途径是","options":[{"key":"A","text":"依法治理宗教事务"},{"key":"B","text":"系统推进我国宗教中国化"},{"key":"C","text":"积极引导宗教与社会主义社会相适应"},{"key":"D","text":"推动我国宗教同中华优秀传统文化相融合"}],"answerKey":"A","explanation":"中共中央政治局于2025年9月29日就系统推进我国宗教中国化进行第二十二次集体学\n习。习近平指出，依法治理宗教事务，是正确处理宗教领域各种矛盾和问题的根本途径。要完善\n相关法规和政策，深人开展法治宣传教育，推动严格执法，切实提高宗教工作法治化水平。A\n正确。","tags":["肖四","第1套","单选题"]},
  {"id":"q-maozhongte-8","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"习近平在《关于<中共中央关于制定国民经济和社会发展第十五个五年规划的建议》的说明》中指出，“十五五”规划建议的着力点是","options":[{"key":"A","text":"推动人的全面发展、全体人民共同富裕迈出坚实步伐"},{"key":"B","text":"推动经济实现质的有效提升和量的合理增长"},{"key":"C","text":"有力有序有效应对世界百年变局的新形势和发展中突出问题"},{"key":"D","text":"为基本实现社会主义现代化目标奠定更加坚实的基础"}],"answerKey":"C","explanation":"习近平在《关于（中共中央关于制定国民经济和社会发展第十五个五年规划的建议》的说\n明》中指出，在《建议》稿起草过程中，我们坚持目标导向和问题导向，立足于夯实基础、全面发力\n的基本定位，以为基本实现社会主义现代化目标奠定更加坚实的基础为着眼点进行系统谋划，\n以有力有序有效应对世界百年变局的新形势和发展中突出问题为着力点补短板、强弱项。C正\n确，D错误。推动经济实现质的有效提升和量的合理增长，推动人的全面发展、全体人民共同富\n裕迈出坚实步伐，是《建议》指导方针的内容。A、B错误。","tags":["肖四","第1套","单选题"]},
  {"id":"q-maozhongte-9","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"马克思主义要在中国发挥跨越时空的思想伟力，必须“穿中国服装”“讲中国话”。1938年，毛泽东在党的六届六中全会上作了《论新阶段》的报告，正式提出了“马克思主义的中国化”这一命题。毛泽东强调","options":[{"key":"A","text":"没有抽象的马克思主义，只有具体的马克思主义"},{"key":"B","text":"马克思主义的中国化就是使中国的每一实践都与马克思主义理论相符合"},{"key":"C","text":"马克思主义的中国化使马克思主义在其每一表现中带着中国的特性"},{"key":"D","text":"马克思主义的中国化即是说按照中国的特点去应用它"}],"answerKeys":["A","C","D"],"explanation":"1938年，毛泽东在党的六届六中全会上作了《论新阶段》的报告，强调：“没有抽象的马克\n思主义,只有具体的马克思主义…马克思主义的中国化，使之在其每一表现中带着中国的特\n性，即是说，按照中国的特点去应用它,成为全党驱待了解并驱须解决的问题。”这标志着“马克\n思主义的中国化”这一命题的正式提出。A、C、D正确。马克思主义强调理论联系实际,而不是\n让实践符合理论。B错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-maozhongte-10","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"党的二十届四中全会通过的“十五五”规划建议，明确要求“高标准建设海南自由贸易港”。高标准建设海南自由贸易港，主要目的是","options":[{"key":"A","text":"促进海南高质量发展"},{"key":"B","text":"助力全国构建新发展格局"},{"key":"C","text":"打造中国式现代化的引领地"},{"key":"D","text":"打造中国新发展格局的战略支点"}],"answerKeys":["A","B"],"explanation":"2025年11月6日，习近平在海南省三亚市听取海南自由贸易港建设工作汇报。在这次汇\n报会上，习近平阐述了背后的深刻考量：“高标准建设海南自由贸易港，主要目的是促进海南高\n质量发展，助力全国构建新发展格局。”A、B正确。11月9日，习近平主席会见来华出席第十五\n届全国运动会开幕式的国际奥委会主席考文垂和终身名誉主席巴赫。习近平强调，全运会是中\n国最大规模、最高水平的综合性运动会，这届全运会由广东、香港、澳门三地合办。粤港澳大湾\n区是中国开放程度最高、经济活力最强的区域之一。推进粤港澳大湾区建设，就是要打造中国\n新发展格局的战略支点、高质量发展的示范地、中国式现代化的引领地。C、D错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-maozhongte-11","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"深化要素市场化改革是构建高水平社会主义市场经济体制的重要举措，是推进全国统一大市场建设的重要内容。深化要素市场化改革，有助于","options":[{"key":"A","text":"推动生产要素畅通流动"},{"key":"B","text":"各类资源高效配置"},{"key":"C","text":"市场潜力充分释放"},{"key":"D","text":"让市场起全部作用"}],"answerKeys":["A","B","C"],"explanation":"A、B、C正确。发挥市场在资源配置中的决定性作用，并不是让市场起全部作用。应当看\n到，市场并不是万能的，在产业布局、公共产品供给、市场秩序维护等领域存在天然失灵。政府\n必须坚持有所为、有所不为，弥补市场失灵和无力涉及的领域。D错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-maozhongte-12","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"几十年来，关于对民营经济在改革开放和社会主义现代化建设事业中地位和作用的认识、党和国家对民营经济发展的方针政策，我们党理论和实践是一脉相承、与时俱进的。党和国家对民营经济发展的基本方针政策，概括起来就是","options":[{"key":"A","text":"非公有制经济是我国社会主义市场经济的重要组成部分，受宪法和法律保护"},{"key":"B","text":"毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展"},{"key":"C","text":"保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到法律保护"},{"key":"D","text":"促进各种所有制经济优势互补、共同发展，促进非公有制经济健康发展和非公有制经济人士健康成长"}],"answerKeys":["A","B","C","D"],"explanation":"几十年来，关于对民营经济在改革开放和社会主义现代化建设事业中地位和作用的认识、\n党和国家对民营经济发展的方针政策，我们党理论和实践是一脉相承、与时俱进的。党和国家\n对民营经济发展的基本方针政策，概括起来就是：中国共产党领导人民发展社会主义市场经济，\n非公有制经济是我国社会主义市场经济的重要组成部分，受宪法和法律保护；党和国家坚持和\n完善社会主义基本经济制度，毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支\n有制经济发展；党和国家保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等\n受到法律保护，促进各种所有制经济优势互补、共同发展，促进非公有制经济健康发展和非公有\n制经济人士健康成长。这些基本方针政策已经纳入中国特色社会主义制度体系，宪法和党章都\n有明确体现，我们将一以贯之坚持和落实，不能变，也不会变。我们谈促进民营经济发展，这是\n一个基本的大前提。A、B、C、D全选。","tags":["肖四","第1套","多选题"]},
  {"id":"q-maozhongte-13","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"作出碳达峰碳中和重大宣示五年来，中国牢固树立和践行绿水青山就是金山银山的理念，采取有力行动、付出艰苦努力，推动绿色低碳转型取得历史性成就。实现碳达峰碳中和是","options":[{"key":"A","text":"中国破解资源环境约束突出问题、实现可持续发展的内在要求"},{"key":"B","text":"中国顺应技术进步趋势、推动经济结构转型升级的必然选择"},{"key":"C","text":"中国满足人民群众日益增长的优美生态环境需求、促进人与自然和谐共生的迫切需要"},{"key":"D","text":"中国担当大国责任、推动构建人类命运共同体的主动作为"}],"answerKeys":["A","B","C","D"],"explanation":"国务院新闻办公室于2025年11月8日发布《碳达峰碳中和的中国行动》白皮书。白皮书\n指出，实现碳达峰碳中和，是中国破解资源环境约束突出问题、实现可持续发展的内在要求；是\n中国顺应技术进步趋势、推动经济结构转型升级的必然选择；是中国满足人民群众日益增长的\n优美生态环境需求、促进人与自然和谐共生的迫切需要；是中国担当大国责任、推动构建人类命\n运共同体的主动作为。中国将碳达峰碳中和作为国家战略，广泛深人开展碳达峰行动，加快经\n济社会发展全面绿色转型，走出了一条生态优先、绿色低碳的发展道路。A、B、C、D全选。","tags":["肖四","第1套","多选题"]},
  {"id":"q-maozhongte-14","type":"material","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":3,"stem":"结合材料回答问题：（1）为什么说唯有将新发展理念“贯穿发展全过程和各领域”，才能“让中国经济在更宏阔的时空维度中实现格局之变”？（2）如何理解中国能够“以高质量发展的确定性应对各种不确定性”？","material":{"title":"材料","paragraphs":["材料 1 过去10年，中国新能源汽车年销量增长约171倍。从受困于“缺芯之痛”，到如今实现“破茧成蝶”，创新驱动加速产业选代升级，新能源汽车不仅成为高质量发展的强劲引擎，也是“中国制造”走向世界的闪亮名片。这场华丽转身，生动诠释了理念变革如何为产业发展注入新动能，为中国经济打开新天地。理念一新天地宽。一辆汽车，可以窥见一个大国发展理念的深层嬉变。回望来路，自党的十八届五中全会提出创新、协调、绿色、开放、共享的新发展理念以来，一场事关中国发展全局的深刻变革悄然开启、纵深推进，引领中国经济实力、科技实力、综合国力不断跃上新台阶，深刻体现出科学思想的真理力量和实践伟力。翻开“十四五”成绩单，新发展理念指引下，实践向前的步履愈发坚实：全球创新指数排名首次硚身前十，大国重器频频亮相；京津冀、长三角、粤港澳大湾区经济体量占全国四成以上；全国地级及以上城市PM2.5浓度持续下降，“常态蓝”不再是奢望；外资准入负面清单持续“瘦身”，开放大门越开越大；居民收入稳步增长，百姓获得感实实在在………这些硬核数据和实践见证中国经济的跨越与蝶变，也让一个共识日益凝聚：唯有将新发展理念贯穿发展全过程和各领域，才能破解难题、厚植优势，让中国经济在更宏阔的时空维度中实现格局之变。","摘编自新华网（2025年11月2日）","材料2 当今世界变乱交织，发展环境动荡不安，确定性日益成为全球的稀缺资源。习近平总书记指出，面对复杂的外部环境，要坚定信心，坚定不移办好自己的事，坚定不移扩大高水平对外开放，着力稳就业、稳企业、稳市场、稳预期，以高质量发展的确定性应对各种不确定性。乱云飞渡仍从容，近年来我国经济运行顶住压力、稳中有进，高质量发展取得新成效，中国式现代化建设稳步推进，成为世界经济增长的主要贡献者和稳定锚。","摘编自《人民日报》（2025年10月4日）"]},"answerPoints":["思路、发展方式、发展着力点的集中体现，从根本上决定着发展成效乃至成败。新发展理念回答了关于发展的目的、动力、方式、路径等一系列理论和实践问题，深化了我们党对中国特色社会主义经济发展规律的认识,开拓了中国特色社会主义政治经济学新境界。","新发展理念，引领我们以推动高质量发展为主题，切实转变发展方式，推动质量变革、效率变革、动力变革，推动中国经济逐步向更高质量、更加平衡、更具可持续性的增长模式转变，实现质的有效提升和量的合理增长,在充满不确定的世界里，展现出强大韧性和活力,实现了历史性的跨越和蝶变。","（2)高质量发展是“十五五”时期我国经济社会发展的主题，是全面建设社会主义现代化国家的首要任务。高质量发展，是能够很好满足人民日益增长的美好生活需要的发展，是体现新发展理念的发展，是经济发展从“有没有”转向“好不好”。","高质量发展为全面建设社会主义现代化国家提供更为坚实的物质基础，是不断满足人民对美好生活需要的重要保证，是维护国家长治久安的必然要求。中国之所以能够“以高质量发展的确定性应对各种不确定性”，原因在于：我国发展战略的确定性，确保了中国经济始终保持既定方向；我国宏观政策的确定性，确保了中国经济有条件平稳运行；","我国市场空间的确定性，确保了中国经济未来成长潜力巨大；我国发展韧性的确定性，确保了中国经济经得住惊涛浪；我国投资环境的确定性，确保了中国经济始终是各类企业投"],"explanation":"思路、发展方式、发展着力点的集中体现，从根本上决定着发展成效乃至成败。新发展理念回答\n了关于发展的目的、动力、方式、路径等一系列理论和实践问题，深化了我们党对中国特色社会\n主义经济发展规律的认识,开拓了中国特色社会主义政治经济学新境界。新发展理念，引领我\n们以推动高质量发展为主题，切实转变发展方式，推动质量变革、效率变革、动力变革，推动中国\n经济逐步向更高质量、更加平衡、更具可持续性的增长模式转变，实现质的有效提升和量的合理\n增长,在充满不确定的世界里，展现出强大韧性和活力,实现了历史性的跨越和蝶变。\n（2)高质量发展是“十五五”时期我国经济社会发展的主题，是全面建设社会主义现代化国\n家的首要任务。高质量发展，是能够很好满足人民日益增长的美好生活需要的发展，是体现新\n发展理念的发展，是经济发展从“有没有”转向“好不好”。高质量发展为全面建设社会主义现代\n化国家提供更为坚实的物质基础，是不断满足人民对美好生活需要的重要保证，是维护国家长\n治久安的必然要求。\n中国之所以能够“以高质量发展的确定性应对各种不确定性”，原因在于：我国发展战略的\n确定性，确保了中国经济始终保持既定方向；我国宏观政策的确定性，确保了中国经济有条件平\n稳运行；我国市场空间的确定性，确保了中国经济未来成长潜力巨大；我国发展韧性的确定性，\n确保了中国经济经得住惊涛浪；我国投资环境的确定性，确保了中国经济始终是各类企业投","tags":["肖四","第1套","材料分析题"]},
  {"id":"q-maozhongte-15","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"认清中国国情，是解决中国革命问题的基本前提。1939年毛泽东在《中国革命和中国共产党》中指出，中国是在许多帝国主义国家的统治或半统治之下，实际上处于长期的不统一状态，再加上土地广大,其结果是","options":[{"key":"A","text":"帝国主义侵略势力日益成为直接统治中国的决定性力量"},{"key":"B","text":"封建经济在社会经济生活中占着显然的优势"},{"key":"C","text":"经济、政治和文化的发展表现出极端的不平衡"},{"key":"D","text":"资产阶级成为资本-帝国主义压迫、奴役中国人民的社会基础"}],"answerKey":"C","explanation":"半统治之下，实际上处于长期的不统一状态,再加上土地广大,其结果是中国的经济、政治和文化\n的发展表现出极端的不平衡。C正确。近代以来,资本-帝国主义侵略势力不但逐步操纵了中国\n的财政和经济命脉,而且逐步控制了中国的政治,日益成为支配中国的决定性力量,但并非直接\n统治。A错误。中国的封建势力日益衰败并同外国侵略势力勾结，成为资本-帝国主义压迫、奴\n役中国人民的社会基础和统治支柱。D错误。B不符合题意。","tags":["肖四","第2套","单选题"]},
  {"id":"q-maozhongte-16","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"我国对资本主义工商业的社会主义改造经历了三个步骤。其中，在实行个别企业的公私合营中，企业利润分配上采取的办法是","options":[{"key":"A","text":"定股定息"},{"key":"B","text":"四马分肥"},{"key":"C","text":"和平买"},{"key":"D","text":"公私兼顾"}],"answerKey":"B","explanation":"我国对资本主义工商业的社会主义改造经历了三个步骤。其中，第一步（初级形式的国家\n资本主义）和第二步（个别企业的公私合营）的企业利润分配都是“四马分肥”。第三步（全行业\n的公私合营）在分配上实行定股定息。B正确。","tags":["肖四","第2套","单选题"]},
  {"id":"q-maozhongte-17","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"实现现代化是近代以来中国人民孜孜以求的宏愿。中国共产党团结带领中国人民追求民族复兴的历史，也是一部不断探索现代化道路的历史。现代化的最终目标是实现","options":[{"key":"A","text":"中华民族伟大复兴"},{"key":"B","text":"物质财富极大丰富"},{"key":"C","text":"社会关系高度和谐"},{"key":"D","text":"人自由而全面的发展"}],"answerKey":"D","explanation":"推动全体人民共同富裕与促进人的全面发展是高度统一的。马克思主义政党的最高目标\n是实现共产主义，并把实现人的自由而全面发展作为共产主义的本质特征。习近平总书记指出，\n现代化的最终目标是实现人自由而全面的发展。D正确。物质财富极大丰富，消费资料按需分\n配；社会关系高度和谐，人们精神境界极大提高；实现每个人自由而全面的发展，人类从必然王国\n向自由王国飞跃，是共产主义社会三大基本特征。A、B、C错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-maozhongte-18","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"教育是国之大计、党之大计，是功在当代、利在千秋的德政工程。教育的根本任务是","options":[{"key":"A","text":"人民满意"},{"key":"B","text":"价值观塑造"},{"key":"C","text":"立德树人"},{"key":"D","text":"为国育才"}],"answerKey":"C","explanation":"我们要建设的教育强国，是中国特色社会主义教育强国，必须以坚持党对教育事业的全面\n领导为根本保证，以立德树人为根本任务，以为党育人、为国育才为根本目标，以服务中华民族伟\n大复兴为重要使命，以教育理念、体系、制度、内容、方法、治理现代化为基本路径，以支撑引领中\n国式现代化为核心功能，最终是办好人民满意的教育。人民满意是发展教育的根本尺度。C\n正确。","tags":["肖四","第2套","单选题"]},
  {"id":"q-maozhongte-19","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"《论人民民主专政》是毛泽东在中国新民主主义革命取得决定性胜利、全国性政权即将建立的时刻，为纪念中国共产党成立28周年而撰写的文章。文章论述了即将成立的中华人民共和国的国家性质，各阶级在国家中的地位及其相互关系，国家对内、对外政策等。《论人民民主专政》这篇文章①奠定了新中国国家政权的理论基础和一定发展阶段上的政策基础②为即将成立的新中国作了政治理论准备③与中共七届二中全会的决议一起构成了《中国人民政治协商会议共同纲领》的基础④是中国共产党人开始探索适合中国国情的社会主义建设道路的标志","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answerKey":"A","explanation":"①②③正确。《论十大关系》是以毛泽东为主要代表的中国共产党人开始探索适合中国国\n情的社会主义建设道路的标志。④错误。因此，本题选A。","tags":["肖四","第2套","单选题"]},
  {"id":"q-maozhongte-20","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"2025年9月，《中国共产党思想政治工作条例》发布。《条例》是我们党历史上第一部关于思想政治工作的统领性、综合性基础主干法规，是做好新时代思想政治工作的基本遵循。《条例》强调，新时代思想政治工作的根本任务是","options":[{"key":"A","text":"巩固马克思主义在意识形态领域的指导地位、巩固全党全国人民团结奋斗的共同思想基础"},{"key":"B","text":"推动用党的创新理论武装头脑、统一思想、凝聚共识、指导实践"},{"key":"C","text":"加强理想信念教育，牢固树立人心是最大的政治的理念"},{"key":"D","text":"调动一切积极因素，完善工作体系，夯实基层基础，创新方式方法，注重实际成效"}],"answerKey":"A","explanation":"《中国共产党思想政治工作条例》强调,思想政治工作坚持马克思列宁主义、毛泽东思想、\n邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思\n想，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，\n牢固树立人心是最大的政治的理念，把巩固马克思主义在意识形态领域的指导地位、巩固全党\n全国人民团结奋斗的共同思想基础作为根本任务，把推动用党的创新理论武装头脑、统一思想、\n凝聚共识、指导实践放在首位，以理想信念教育为核心，以调动一切积极因素为着力点，完善工\n作体系，夯实基层基础，创新方式方法，注重实际实效，促进全体人民紧紧团结在党的周围、凝聚\n在中国特色社会主义伟大旗帜下，为以中国式现代化全面推进强国建设、民族复兴伟业提供坚\n强思想政治保证。A正确,B、C、D不符合题意。","tags":["肖四","第2套","单选题"]},
  {"id":"q-maozhongte-21","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"20多年前，时任浙江省委书记的习近平科学阐释“地瓜经济”理论，深刻指出“必须跳出浙江发展浙江，在大力引进各种要素的同时打到省外去、国外去，利用外部资源、外部市场实现更大的发展”。“地瓜经济”给我们的启示有","options":[{"key":"A","text":"事物发展的动力在外部"},{"key":"B","text":"任何事物都处在普遍联系之中"},{"key":"C","text":"事物之间的联系是多样的"},{"key":"D","text":"事物的发展可以脱离内部条件"}],"answerKeys":["B","C"],"explanation":"世界上的万事万物都处于普遍联系之中。联系具有多样性。世界上的事物是多样的，事\n物之间的联系也是多样的。事物联系的主要方式有直接联系与间接联系、内部联系与外部联\n系、本质联系与非本质联系、必然联系与偶然联系等。“跳出浙江发展浙江”就是要看到浙江与\n省外、国外的联系,这种联系可能是直接联系,也可能是间接联系。B、C正确。对立统一规律揭\n示了事物普遍联系的根本内容和变化发展的内在动力。事物内部矛盾是事物发展的源泉和动\n力，A错误。D显然错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-maozhongte-22","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"社会主义改造基本完成后，我国进人社会主义建设时期。如何建设和巩固社会主义，是党面临的一个新课题。以毛泽东同志为主要代表的中国共产党人对社会主义建设道路的初步探索","options":[{"key":"A","text":"巩固和发展了我国的社会主义制度"},{"key":"B","text":"丰富了科学社会主义的理论和实践"},{"key":"C","text":"彻底摆脱了苏联模式的影响"},{"key":"D","text":"为开创中国特色社会主义提供了宝贵经验、理论准备和物质基础"}],"answerKeys":["A","B","D"],"explanation":"A、B、D正确。在社会主义建设道路初步探索时期，由于中国共产党人对什么是社会主义\n以及怎样建设社会主义的问题并没有完全搞清楚，因此，不能说已经彻底摆脱了苏联模式的影\n响。C错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-maozhongte-23","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"“十五五”时期我国发展环境面临深刻复杂变化。大国关系牵动国际形势，国际形势演变深刻影响国内发展，我国发展处于战略机遇和风险挑战并存、不确定难预料因素增多的时期。但是，我国经济基础稳、优势多、韧性强、潜能大，长期向好的支撑条件和基本趋势没有变。我国发展具有的优势包括","options":[{"key":"A","text":"中国特色社会主义制度优势"},{"key":"B","text":"超大规模市场优势"},{"key":"C","text":"完整产业体系优势"},{"key":"D","text":"丰富人才资源优势"}],"answerKeys":["A","B","C","D"],"explanation":"《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出，我国经济基础\n稳、优势多、韧性强、潜能大，长期向好的支撑条件和基本趋势没有变，中国特色社会主义制度优\n势、超大规模市场优势、完整产业体系优势、丰富人才资源优势更加彰显。党的二十届四中全会\n着眼于发挥这“四大优势”作出战略部署。A、B、C、D全选。\n点拨这“四大优势”相辅相成、有机统一，超大规模市场优势成为重要战略支点。","tags":["肖四","第2套","多选题"]},
  {"id":"q-maozhongte-24","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"《教育强国建设规划纲要（2024一2035年）》提出，要坚定不移走中国特色社会主义教育发展道路，坚持社会主义办学方向，全面把握教育的","options":[{"key":"A","text":"政治属性"},{"key":"B","text":"人民属性"},{"key":"C","text":"战略属性"},{"key":"D","text":"创新属性"}],"answerKeys":["A","B","C"],"explanation":"《教育强国建设规划纲要（2024一2035年）》的总体要求是：坚持以习近平新时代中国特色\n社会主义思想为指导，深人贯彻党的二十大和二十届二中、三中全会精神，全面贯彻习近平总书\n记关于教育的重要论述，深刻领悟“两个确立”的决定性意义，坚决做到“两个维护”，坚持教育优\n先发展，全面贯彻党的教育方针，坚定不移走中国特色社会主义教育发展道路，坚持社会主义办\n学方向，全面把握教育的政治属性、人民属性、战略属性，落实立德树人根本任务，为党育人、为\n国育才，全面服务中国式现代化建设，扎根中国大地办教育，加快建设高质量教育体系，培养德\n智体美劳全面发展的社会主义建设者和接班人，加快建设具有强大思政引领力、人才竞争力、科\n技支撑力、民生保障力、社会协同力、国际影响力的中国特色社会主义教育强国，为建设社会主\n义现代化强国、全面推进中华民族伟大复兴提供有力支撑。A、B、C正确。","tags":["肖四","第2套","多选题"]},
  {"id":"q-maozhongte-25","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"习近平指出：“没有农业农村现代化，就没有整个国家现代化。”党的二十届四中全会通过的《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》,对加快农业农村现代化作出专章部署，明确了“十五五”时期农业农村发展的战略任务和政策举措。以下内容正确的有","options":[{"key":"A","text":"农业农村现代化关系中国式现代化全局和成色"},{"key":"B","text":"农业农村现代化关系强国建设根基"},{"key":"C","text":"农业农村仍然是社会主义现代化建设的突出短板"},{"key":"D","text":"稳住农业基本盘、守好“三农”基础，始终是我们应对各种风险挑战的“压舱石”"}],"answerKeys":["A","B","C","D"],"explanation":"农业农村现代化关系中国式现代化全局和成色，关系强国建设根基，关系亿万农民福证。\n农业农村仍然是社会主义现代化建设的突出短板。农业农村现代化进程，直接关系中国式现代\n化目标的实现进程，关系社会主义现代化国家建设的整体水平。必须加快农业农村现代化，向\n乡村全面振兴聚焦发力，推动农业农村农民与国家同步基本实现现代化。全面建设社会主义现\n代化国家，基础在“三农”。稳住农业基本盘、守好“三农”基础，始终是我们应对各种风险挑战的\n“压舱石”。A、B、C、D全选。","tags":["肖四","第2套","多选题"]},
  {"id":"q-maozhongte-26","type":"material","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":3,"stem":"结合材料回答问题：（1）如何理解外部环境越是严峻复杂，越要加快构建新发展格局，坚持扩大内需这个战略基点？（2）结合纵深推进全国统一大市场建设，分析“坚持有效市场和有为政府相结合，正是做好经济工作的一个重要方法”。（或：加快构建高水平社会主义市场经济体制，为什么要用好“无形之手”和“有形之手”？）","material":{"title":"材料","paragraphs":["材料1 关于做强国内大循环、畅通国内国际双循环。外部环境越是严峻复杂，越要加快构建新发展格局，牢牢把握发展主动权。当前和今后一个时期，要坚持做强国内大循环，加快形成强大国内经济循环体系，以国内循环的稳定性对冲国际循环的不确定性。《建议》稿突出做强国内大循环，对建设强大国内市场、加快构建高水平社会主义市场经济体制作出部署，强调坚持扩大内需这个战略基点，坚持惠民生和促消费、投资于物和投资于人紧密结合，大力提振消费，扩大有效投资，坚决破除阻碍全国统一大市场建设卡点堵点，强调充分激发各类经营主体活力，加快完善要素市场化配置体制机制，提升宏观经济治理效能。同时，提出拓展国际循环，稳步扩大制度型开放，维护多边贸易体制，高质量共建“一带一路”。","摘自习近平《关于《中共中央关于制定国民经济和社会发展第十五个五年规划的建议)的说明》","材料2 纵深推进全国统一大市场建设,基本要求是“五统一、一开放”。“五统一”，就是统一市场基础制度，特别是实现产权保护、公平竞争、质量标准等制度的统一；统一市场基础设施，打通物流、资金流、信息流，健全现代商贸流通体系；统一政府行为尺度，地方在推动经济发展特别是招商引资时，哪些能干哪些不能干有明确规矩，不能各行其是；统一市场监管执法，明确市场监管行政处罚裁量基准，一把尺子量到底；统一要素资源市场，促进自由流动、高效配置，减少资源错配和闲置浪费。“一开放”，就是持续扩大开放，实行对内对外开放联通，不搞封闭运行。落实这些基本要求，当前最急迫的是聚焦重点难点，下决心清除顽痒疾。","摘自习近平《在二十届中央财经委员会第六次会议上的讲话》","材料3 我国经济发展获得巨大成功的一个关键因素，就是我们既发挥了市场经济的长处，又发挥了社会主义制度的优越性。坚持有效市场和有为政府相结合，正是做好经济工作的一个重要方法。市场是最稀缺的资源，超大规模市场是我国的优势所在。如何将这一优势持续放大？把“无形之手”和“有形之手”结合起来是重要途径。近年来，依靠市场提供多样化供给和服务，通过政府引导及“真金白银”支持，大规模设备更新和消费品以旧换新政策拉动内需、惠企利民，成为有效市场和有为政府协同发力的生动注脚。政府行为越规范，市场作用就越有效。从出台《全国统一大市场建设指引（试行）》，到选代发布5版市场准入负面清单；从集中清理妨碍全国统一市场和公平竞争的规定和做法，到开展新出台政策与宏观政策取向一致性评估纵深推进全国统一大市场建设，为我国发展增强了韧性、注入了动力、释放了潜能。","摘编自《人民日报》（2025年10月26日）"]},"answerPoints":["发展阶段、发展环境、条件变化作出的重大决策，是推动高质量发展的战略基点，是关系我国发展全局的重大战略任务。大国经济的特征都是内需为主导、内部可循环。市场是当今世界最稀缺的资源，强大国内市场是中国式现代化的战略依托。","在当前国际形势充满不稳定性不确定性的背景下，立足国内、依托国内大市场优势，充分挖掘内需潜力，有利于化解外部冲击和外需下降带来的影响，也有利于在极端情况下保证我国经济基本正常运行和社会大局总体稳定。","要坚持扩大内需这个战略基点,坚持惠民生和促消费、投资于物和投资于人紧密结合，以新需求引领新供给，以新供给创造新需求，促进消费和投资、供给和需求良性互动，增强国内大循环内生动力和可靠性。(2)高水平社会主义市场经济体制是中国式现代化的重要保障。","构建高水平社会主义市场经济体制,关键是处理好政府和市场的关系,使市场在资源配置中起决定性作用,更好发挥政府作用。市场在资源配置中起决定性作用，就是把市场机制能有效调节的经济活动交给市场，推动资源配置实现效益最大化和效率最优化。更好发挥政府作用，就是要在保证市场发挥决定性作用的前提下,管好那些市场管不了或管不好的事情。","市场不是万能的，让市场更有效，需要政府更有为；政府行为越规范，市场作用就越有效。只有坚持有效市场和有为政府相结合，才能形成既“放得活”又“管得好”的经济秩序。建设全国统一大市场，本质是让资源在更大范围内畅通流动和高效配置，更好发挥市场在资源配置中的决定性作用。","但市场并非万能，存在失灵、无序等风险，这就需要政府发挥作用，通过完善制度规则、维护公平竞争、弥补市场缺陷，为市场有效运行提供保障。只有推动有效市场和有为政府更好结合，让“无形之手”和“有形之手”协同发力，统一大市场建设才能持续纵深推进。（注：综合整治“内卷式”竞争，也彰显了在全国统一大市场建设进程中有为政府与有效市场的有机统一。","回答相关提问，也可以从本题的角度进行作答）"],"explanation":"发展阶段、发展环境、条件变化作出的重大决策，是推动高质量发展的战略基点，是关系我国发\n展全局的重大战略任务。大国经济的特征都是内需为主导、内部可循环。市场是当今世界最稀\n缺的资源，强大国内市场是中国式现代化的战略依托。在当前国际形势充满不稳定性不确定性\n的背景下，立足国内、依托国内大市场优势，充分挖掘内需潜力，有利于化解外部冲击和外需下\n降带来的影响，也有利于在极端情况下保证我国经济基本正常运行和社会大局总体稳定。\n要坚持扩大内需这个战略基点,坚持惠民生和促消费、投资于物和投资于人紧密结合，以新\n需求引领新供给，以新供给创造新需求，促进消费和投资、供给和需求良性互动，增强国内大循\n环内生动力和可靠性。\n(2)高水平社会主义市场经济体制是中国式现代化的重要保障。构建高水平社会主义市场\n经济体制,关键是处理好政府和市场的关系,使市场在资源配置中起决定性作用,更好发挥政府\n作用。市场在资源配置中起决定性作用，就是把市场机制能有效调节的经济活动交给市场，推\n动资源配置实现效益最大化和效率最优化。更好发挥政府作用，就是要在保证市场发挥决定性\n作用的前提下,管好那些市场管不了或管不好的事情。市场不是万能的，让市场更有效，需要政\n府更有为；政府行为越规范，市场作用就越有效。只有坚持有效市场和有为政府相结合，才能形\n成既“放得活”又“管得好”的经济秩序。\n建设全国统一大市场，本质是让资源在更大范围内畅通流动和高效配置，更好发挥市场在\n资源配置中的决定性作用。但市场并非万能，存在失灵、无序等风险，这就需要政府发挥作用，\n通过完善制度规则、维护公平竞争、弥补市场缺陷，为市场有效运行提供保障。只有推动有效市\n场和有为政府更好结合，让“无形之手”和“有形之手”协同发力，统一大市场建设才能持续纵深\n推进。\n（注：综合整治“内卷式”竞争，也彰显了在全国统一大市场建设进程中有为政府与有效\n市场的有机统一。回答相关提问，也可以从本题的角度进行作答）","tags":["肖四","第2套","材料分析题"]},
  {"id":"q-maozhongte-27","type":"material","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":3,"stem":"结合材料回答问题：（1）如何理解“我们今天取得的伟大成就，都是建立在毛泽东等老一辈革命家打下的江山、揽下的家底之上的”？（2）结合从“一五”计划到“十四五”规划的制定实施，说明中国共产党的领导是实现中国式现代化的根本保证。","material":{"title":"材料","paragraphs":["材料 1 我们今天取得的伟大成就，都是建立在毛泽东等老一辈苹命家打下的江山、揽下的家底之上的。","摘自.习近平2025年11月7日在广东考察时的讲话","材料2 中国共产党在领导中国各族人民为新民主主义而斗争的过程中,经历了国共合作的北伐战争，土地革命战争，抗日战争和全国解放战争这四个阶段，其间经受了一九二七年和一九三四年两次严重失败的痛苦考验。经过长期武装斗争和各个方面、各种形式斗争的密切配合，终于在一九四九年取得了革命的胜利。建国三十二年来，我们取得的主要成就是四、建立和发展了社会主义经济，基本上完成了对生产资料私有制的社会主义改造，基本上实现了生产资料公有制和按劳分配。五、在工业建设中取得重大成就，逐步建立了独立的比较完整的工业体系和国民经济体系。我国第一个五年计划的经济建设，依靠我们自己的努力，加上苏联和其他友好国家的支援，同样取得了重大的成就。一批为国家工业化所必需而过去又非常薄弱的基础工业建立了起来。从一九五三年到一九五六年，全国工业总产值平均每年递增百分之十九点六，农业总产值平均每年递增百分之四点八。经济发展比较快，经济效果比较好，重要经济部门之间的比例比较协调。市场繁荣，物价稳定。人民生活显著改善。","摘自《关于建国以来党的若干历史问题的决议》","材料3 坚持和加强党的全面领导是推进中国式现代化的根本保证。《建议》稿着眼提高党领导经济社会发展能力和水平，强调坚持和加强党中央集中统一领导，完善党中央重大决策部署落实机制；持续用党的创新理论统一思想、统一意志、统一行动；坚持正确用人导向，完善千部考核评价机制；统筹推进各领域基层党组织建设；锲而不舍落实中央八项规定精神；完善党和国家监督体系；坚决打好反腐败斗争攻坚战、持久战、总体战。","摘自习近平《关于(中共中央关于制定国民经济和社会发展第十五个五年规划的建议>的说明》"]},"answerPoints":["人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃。毛泽东等老一辈革命家下的家底，主要是指完成社会主义革命和推进社会主义建设。","从新中国成立到改革开放前夕，党领导人民完成社会主义革命，消灭一切剥削制度，实现了中华民族有史以来最为广泛而深刻的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础，也为中国特色社会主义制度的创新和发展提供了重要前提，实现了一穷二白、人口众多的东方大国大步迈进社会主义社会的伟大飞跃。","党在社会主义革命和建设中取得的独创性理论成果和巨大成就，为在新的历史时期开创中国特色社会主义提供了宝贵经验、理论准备、物质基础。","尤其是独立的、比较完整的工业体系和国民经济体系的建立，从根本上解决了工业化中“从无到有”的问题，使中国在赢得政治上的独立后赢得了经济上的独立，为中国以后的发展奠定了牢固的物质技术基础，而且为中国同包括西方发达国家在内的世界各国在平等互利的原则下发展对外贸易和经济往来创建了前提。","（2)制定中长期规划指导经济社会发展，是我们党治国理政的一种重要方式。实现社会主义现代化是一个阶梯式递进、不断发展进步的历史过程，需要不努力、接续奋斗。","从1953年到2025年，我们党围绕把我国建设成为社会主义现代化国家这个主题，制定和实施了十四个五年计划（或规划），将战略目标与发展政策、具体举措有机统一起来，确保党的政治理想和奋斗目标能够转化为实实在在的发展绩效和人民群众满意的美好生活现实，“一张蓝图绘到底”，使我国发展成为世界上第二大经济强国，成功推进和拓展了中国式现代化。","中国共产党领导直接关系中国式现代化的根本方向、前途命运、最终成败。第一，党的领导决定中国式现代化的根本性质。第二，党的领导确保中国式现代化锚定奋斗目标行稳致远。第三，党的领导激发建设中国式现代化的强劲动力。第四，党的领导凝聚建设中国式现代化的磅磷力量。"],"explanation":"人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和\n帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃。\n毛泽东等老一辈革命家下的家底，主要是指完成社会主义革命和推进社会主义建设。从\n新中国成立到改革开放前夕，党领导人民完成社会主义革命，消灭一切剥削制度，实现了中华民\n族有史以来最为广泛而深刻的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度\n基础，也为中国特色社会主义制度的创新和发展提供了重要前提，实现了一穷二白、人口众多的\n东方大国大步迈进社会主义社会的伟大飞跃。党在社会主义革命和建设中取得的独创性理论\n成果和巨大成就，为在新的历史时期开创中国特色社会主义提供了宝贵经验、理论准备、物质\n基础。\n尤其是独立的、比较完整的工业体系和国民经济体系的建立，从根本上解决了工业化中“从\n无到有”的问题，使中国在赢得政治上的独立后赢得了经济上的独立，为中国以后的发展奠定了\n牢固的物质技术基础，而且为中国同包括西方发达国家在内的世界各国在平等互利的原则下发\n展对外贸易和经济往来创建了前提。\n（2)制定中长期规划指导经济社会发展，是我们党治国理政的一种重要方式。实现社会主\n义现代化是一个阶梯式递进、不断发展进步的历史过程，需要不努力、接续奋斗。从1953年到\n2025年，我们党围绕把我国建设成为社会主义现代化国家这个主题，制定和实施了十四个五年\n计划（或规划），将战略目标与发展政策、具体举措有机统一起来，确保党的政治理想和奋斗目标\n能够转化为实实在在的发展绩效和人民群众满意的美好生活现实，“一张蓝图绘到底”，使我国\n发展成为世界上第二大经济强国，成功推进和拓展了中国式现代化。\n中国共产党领导直接关系中国式现代化的根本方向、前途命运、最终成败。第一，党的领导\n决定中国式现代化的根本性质。第二，党的领导确保中国式现代化锚定奋斗目标行稳致远。第\n三，党的领导激发建设中国式现代化的强劲动力。第四，党的领导凝聚建设中国式现代化的磅\n磷力量。","tags":["肖四","第2套","材料分析题"]},
  {"id":"q-maozhongte-28","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"习近平指出：“要顺应人民群众对美好生活的期待，坚持人民主体地位，把人口高质量发展同人民高品质生活紧密结合起来，把‘投资于物'同‘投资于人'紧密结合起来”。“十五五”规划建议也强调“推动人的全面发展”。马克思主义认为，在现实性上，人的本质是","options":[{"key":"A","text":"一切社会关系的总和"},{"key":"B","text":"单个人天生就具有的东西"},{"key":"C","text":"所有人共同属性的概括"},{"key":"D","text":"自然属性和社会属性的综合"}],"answerKey":"A","explanation":"马克思指出，“人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的\n总和”。这就告诉我们，人的本质属性是社会属性，而不是自然属性；人的本质属性表现在各种社\n会关系中；人的本质是变化发展的,而不是永恒不变的。A正确。","tags":["肖四","第3套","单选题"]},
  {"id":"q-maozhongte-29","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"新民主主义文化就是无产阶级领导的人民大众的反帝反封建的文化，即民族的科学的大众的文化。其中“民族的”，就其内容说，是指","options":[{"key":"A","text":"具有鲜明的民族风格、民族形式和民族特色"},{"key":"B","text":"具有中国作风和中国气派"},{"key":"C","text":"反对帝国主义压迫，主张中华民族的尊严和独立"},{"key":"D","text":"反对封建思想和迷信思想"}],"answerKey":"C","explanation":"新民主主义文化是民族的,就其内容说是反对帝国主义压迫，主张中华民族的尊严和独立；\n就其形式说是具有鲜明的民族风格、民族形式和民族特色，要有中国作风和中国气派。同时，要\n大量吸收外国的进步文化,作为自己文化食粮的原料。C正确，A、B错误。新民主主义文化是科\n学的,反对一切封建思想和迷信思想，主张实事求是、客观真理及理论和实践的一致性。D错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-maozhongte-30","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"统一战线是新民主主义革命的三大法宝之一。中国革命建立最广泛的统一战线不仅是必要的，而且是可能的,这种可能是由","options":[{"key":"A","text":"中国半殖民地半封建社会的阶级状况所决定的"},{"key":"B","text":"半殖民地半封建的中国社会的交织在一起的诸多矛盾所决定的"},{"key":"C","text":"中国革命的长期性、残酷性及其发展的不平衡性所决定的"},{"key":"D","text":"战争与革命的时代主题所决定的"}],"answerKey":"B","explanation":"在半殖民地半封建的中国社会，诸多矛盾交织在一起，客观上为无产阶级及其政党利用这\n些矛盾建立和发展统一战线提供了可能性。近代中国社会最大的压迫是民族压迫，决定了无产\n阶级及其政党可以把一切爱国的、不愿受帝国主义奴役的人们团结在自己的周围。民族资产阶\n级深受帝国主义和封建主义的压迫,因而能够在一定时期和一定程度上参加反帝反封建的革命\n斗争。当革命的锋芒主要是反对某一个帝国主义的时候，受别的帝国主义支持的官僚资产阶级\n集团也可能在一定程度上和一定时期内参加统一战线。B正确。A、C是半殖民地半封建的中国\n必须建立最广泛的统一战线的必要性，不是可能性。D不符合题意。","tags":["肖四","第3套","单选题"]},
  {"id":"q-maozhongte-31","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。新质生产力的显著特点是创新，这种创新包括①生产资料所有制和产品分配层面的创新②技术和业态模式层面的创新③管理和制度层面的创新价值观和意识形态层面的创新","options":[{"key":"A","text":"@"},{"key":"B","text":"①③"},{"key":"C","text":"②@"},{"key":"D","text":"@3"}],"answerKey":"D","explanation":"习近平在《发展新质生产力是推动高质量发展的内在要求和重要着力点》一文中指出，新质\n生产力的显著特点是创新,既包括技术和业态模式层面的创新，也包括管理和制度层面的创新。必\n须继续做好创新这篇大文章，推动新质生产力加快发展。②③正确。因此，本题选D。","tags":["肖四","第3套","单选题"]},
  {"id":"q-maozhongte-32","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"构建新发展格局是事关全局的系统性、深层次变革，是立足当前、着眼长远的战略谋划，是适应我国发展新阶段要求、塑造国际合作和竞争新优势的必然选择。构建新发展格局的重要前提和保障是","options":[{"key":"A","text":"充分挖掘内需潜力"},{"key":"B","text":"夯实我国经济发展的根基"},{"key":"C","text":"促进区域协调发展"},{"key":"D","text":"牢牢守住安全发展这条底线"}],"answerKey":"D","explanation":"安安全是发展的前提，发展是安全的保障。牢牢守住安全发展这条底线是构建新发展格局的\n重要前提和保障。以新安全格局保障新发展格局，必须统筹维护国家安全各类要素、各个领域、\n各方资源、各种手段，主动塑造于我有利的外部安全环境，推动发展和安全深度融合，实现高质量\n发展和高水平安全的良性互动。D正确,A、B、C错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-maozhongte-33","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"全面推进依法治国是一个系统工程，是国家治理领域一场广泛而深刻的革命，涉及立法、执法、司法、守法等各个方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手。全面依法治国的总抓手是","options":[{"key":"A","text":"坚持科学立法、严格执法、公正司法、全民守法"},{"key":"B","text":"坚持有法可依、有法必依、执法必严、违法必究"},{"key":"C","text":"建设中国特色社会主义法治体系"},{"key":"D","text":"坚持依法治国和以德治国相结合"}],"answerKey":"C","explanation":"全面推进依法治国涉及很多方面，在实际工作中必须有一个总揽全局、牵引各方的总抓\n手，这个总抓手就是建设中国特色社会主义法治体系。依法治国各项工作都要围绕这个总抓手","tags":["肖四","第3套","单选题"]},
  {"id":"q-maozhongte-34","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"在一个几亿人口的大国中比较顺利地实现了如此复杂、困难和深刻的社会主义改造，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展；不仅没有引起巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民普遍拥护的情况下完成的。这些情况说明，我国社会主义改造的基本完成的确是一个伟大的历史性胜利。我国社会主义改造的成功经验在于","options":[{"key":"A","text":"坚持“一举过渡”"},{"key":"B","text":"坚持社会主义工业化建设与社会主义改造同时并举"},{"key":"C","text":"采取积极引导、逐步过渡的方式"},{"key":"D","text":"用和平方法进行改造"}],"answerKeys":["B","C","D"],"explanation":"B、C、D正确。新中国成立之初，当时的设想是“一举过渡”。随着民主革命遗留任务的彻\n底完成和国内阶级关系、主要矛盾的变化，国民经济的恢复、初步发展和中国社会经济成分的变\n化，中共中央对向社会主义过渡步骤的认识也发生了变化。1952年9月24日，毛泽东在中共中\n央书记处会议上提出，我们要在“十年到十五年基本上完成社会主义，不是十年以后才过渡到社\n会主义”。刘少奇周恩来等也都论述过“从现在逐步过渡到社会主义去”的设想。这是“建设和\n改造同时并举，逐步过渡”的设想。提出过渡时期总路线，就是这一转变的结果。A错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-maozhongte-35","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"2025年4月30日，十四届全国人大常委会第十五次会议表决通过了《中华人民共和国民营经济促进法》，自2025年5月20日起施行。制定出台《民营经济促进法》，是贯彻落实习近平总书记重要指示精神和党中央决策部署的重要举措；是落实宪法规定，坚持和完善社会主义基本经济制度的内在要求；是构建高水平社会主义市场经济体制、促进民营经济高质量发展的客观需要。《民营经济促进法》明确规定，民营经济是","options":[{"key":"A","text":"社会主义市场经济的重要组成部分"},{"key":"B","text":"推进中国式现代化的生力军"},{"key":"C","text":"高质量发展的重要基础"},{"key":"D","text":"推动我国全面建成社会主义现代化强国、实现中华民族伟大复兴的重要力量"}],"answerKeys":["A","B","C","D"],"explanation":"《民营经济促进法》规定：民营经济是社会主义市场经济的重要组成部分，是推进中国式现\n代化的生力军，是高质量发展的重要基础，是推动我国全面建成社会主义现代化强国、实现中华\n民族伟大复兴的重要力量。促进民营经济持续、健康、高质量发展，是国家长期坚持的重大方针\n政策。A、B、C、D全选。","tags":["肖四","第3套","多选题"]},
  {"id":"q-maozhongte-36","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"世界知识产权组织近日发布的《2025年全球创新指数报告》显示，中国排名首次身全球前十，稳居36个中等偏上收人经济体之首，2013年以来累计上升25位，是创新力上升最快的经济体之一。中国创新的“加速度”，离不开坚实的政策支持和丰沃的培育土壤。我国为企业创新提供的有利条件有","options":[{"key":"A","text":"支持企业参与国家重大科研任务"},{"key":"B","text":"持续优化税收优惠政策"},{"key":"C","text":"向企业开放政府应用场景"},{"key":"D","text":"构建政府主导的产学研用协同创新体系"}],"answerKeys":["A","B","C"],"explanation":"[简桁中国创新的\"加速度”,离不开坚实的政策支持和丰沃的培育土壤。中国深人实施创新驱\n动发展战略，锚定科技强国建设目标，加强基础研究和科技攻关，提升国家创新体系整体效能，\n为高水平科技自立自强提供有力支撑。从支持企业参与国家重大科研任务，到持续优化税收优\n惠政策，向企业开放政府应用场景，中国广阔的市场空间、丰富的应用场景，为企业创新提供了\n丰厚土壤。A、B、C正确。企业是科技创新的主体。习近平指出,要推动人工智能科技创新与产\n业创新深度融合，构建企业主导的产学研用协同创新体系，助力传统产业改造升级，开辟战略性\n新兴产业和未来产业发展新赛道。D错误（错在“政府”主导）。","tags":["肖四","第3套","多选题"]},
  {"id":"q-maozhongte-37","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"党的二十届四中全会通过的《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》，深刻把握文化发展规律，提出“激发全民族文化创新创造活力，繁荣发展社会主义文化”的战略任务，体现了新时代中国共产党人高度的文化自觉，为社会主义文化强国建设指明了前进方向。激发创新创造活力是","options":[{"key":"A","text":"建设文化强国的关键"},{"key":"B","text":"推动文化繁荣的必然要求"},{"key":"C","text":"满足人民精神文化需求的必然要求"},{"key":"D","text":"在国际文化竞争中赢得主动的必然要求"}],"answerKeys":["A","B","C","D"],"explanation":"党的二十届四中全会通过的《中共中央关于制定国民经济和社会发展第十五个五年规划\n的建议》，深刻把握文化发展规律，提出“激发全民族文化创新创造活力，繁荣发展社会主义文\n化”的战略任务，体现了新时代中国共产党人高度的文化自觉，为社会主义文化强国建设指明了\n前进方向。激发创新创造活力是建设文化强国的关键。建设社会主义文化强国是我们党作出\n的重大战略决策，事关中国式现代化建设全局，事关中华民族复兴大业，事关提升国际竞争力。\n（1)激发创新创造活力是推动文化繁荣的必然要求。创新创造是文化的生命力。（2）激发创新\n创造活力是满足人民精神文化需求的必然要求。习近平强调，文化强国之“强”最终要体现在人\n民的思想境界、精神状态、文化修养上。（3)激发创新创造活力是在国际文化竞争中赢得主动的\n必然要求。激发文化创新创造活力，目的是繁荣发展社会主义文化，是有方向、有立场、有原则的，\n关键是坚持和加强党的全面领导，坚定不移走中国特色社会主义文化发展道路。A、B、C、D全选。","tags":["肖四","第3套","多选题"]},
  {"id":"q-maozhongte-38","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"党的十八大以来,我们党把宗教工作摆在治国理政的重要位置,鲜明提出坚持我国宗教中国化方向等一系列新理念新举措，完善宗教工作体制机制，提高宗教工作法治化水平，推动新时代宗教工作取得积极成效。我国关于宗教的方针政策有","options":[{"key":"A","text":"积极引导宗教与社会主义社会相适应"},{"key":"B","text":"推动我国宗教同中华优秀传统文化相融合"},{"key":"C","text":"依法治理宗教事务"},{"key":"D","text":"激发宗教界主动作为、自我变革"}],"answerKeys":["A","B","C","D"],"explanation":"中共中央政治局于2025年9月29日就系统推进我国宗教中国化进行第二十二次集体学\n习。习近平在主持学习时强调，我国是中国共产党领导的社会主义国家，积极引导宗教与社会\n主义社会相适应是必然要求。我国各宗教只有始终扎根中华大地、浸润中华文化，才能健康传\n承。要植根中华五千年文明，推动我国宗教同中华优秀传统文化相融合，引导宗教界人士和信\n教群众增强中华文化认同感。激发宗教界主动作为、自我变革，对推进我国宗教中国化至关重\n要。依法治理宗教事务，是正确处理宗教领域各种矛盾和问题的根本途径。A、B、C、D全选。","tags":["肖四","第3套","多选题"]},
  {"id":"q-maozhongte-39","type":"material","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":3,"stem":"结合材料回答问题：（1）结合“十五五”时期全体人民共同富裕迈出坚实步伐的总体性要求，说明为什么要推动区域协调发展。（2）人文经济学对我们追求物质与精神协调发展、以文化赋能经济社会发展有何启示？","material":{"title":"材料","paragraphs":["材料1 关于全体人民共同富裕迈出坚实步伐。中国式现代化是全体人民共同富裕的现代化…《建议》稿在指导思想中突出强调全体人民共同富裕迈出坚实步伐，这是指导“十五五”时期经济社会发展的一个总体性要求。","摘自习近平《关于《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》的说明》","材料2 “前些年，我去了清远、湛江，这次来梅州，广东大部分地区特别是发展需要加快速度的地区就都走到了。我一直要求推动全省的协调发展，很关心这些还需要走得再快一点的地方。”总书记亲切地对乡亲们说。次日，在听取广东省委和省政府工作汇报时，习近平总书记谈到了这次到梅州：“要完善区域协调发展、城乡融合发展体制机制，逐步补齐城乡区域发展差距仍然较大这个短板。你们实施的“百县千镇万村高质量发展工程，，让乡镇面貌有了新的变化，要持续抓下去说到这里，总书记提醒道：“但一定要注意，不能摘成闭门造车式的小城镇，要因地制宜、按需建设。","摘编自《人民日报》（2025年11月11日）","材料3 党的二十届四中全会提出，大力繁荣文化事业，加快发展文化产业，提升中华文明传播力影响力。今日之中国，很古朴也很时尚。中华优秀传统文化引领“新国潮”，消费市场掀起“中国风”，人文与经济交融共生、相得益彰。“文化很发达的地方，经济照样走在前面。可以研究一下这里面的人文经济学。”2023年全国两会期间，习近平总书记在参加江苏代表团审议时提出了“人文经济学”的重大命题。2024年，全国博物馆接待观众14.91亿人次，举办展览4.3万个，文创产品销售收入34.28亿元，广大游客“为一个馆，奔赴一座城”；全国文化产业实现营业收入19.14万亿元，营收规模再创历史新高，文化产业成为经济增长重要引擎；国内居民出游56.2亿人次，总花费5.8万亿元，文旅融合出新出彩，进一步释放消费潜力。悠长壮阔的中华文明，不仅为我们留下了灿若星辰的历史文化遗产和自信包容的基因，更是连接过去与今天的桥梁，为经济社会发展增添了丰厚的文化底色。","摘编自《人民日报》（2025年10月29日）"]},"answerPoints":["代化的显著标志。中国式现代化坚持以人民为中心，突出现代化方向的人民性，把实现人民对美好生活的向往作为现代化建设的出发点和落脚点，在推动高质量发展的同时，解决好地区差距、城乡差距、收入分配差距，着力维护和促进社会公平正义，坚决防止两极分化。推动区域协调发展，是解决发展不平衡不充分问题的重要途径，是推动高质量发展、促进共同富裕的内在要求。","在现代化进程中，推动区域协调发展迈向更高水平，提升各地区居民的收人水平和生活质量，进一步提高发展的平衡性、协调性、包容性，有助于实现发展成果共享。(2)中国式现代化是物质文明和精神文明相协调的现代化。物质富足、精神富有是社会主义现代化的根本要求。","必须坚持两手抓、两手硬，不断厚植现代化的物质基础，不断夯实人民幸福生活的物质条件，同时大力发展社会主义先进文化，加强理想信念教育，传承中华文明，促进物的全面丰富和人的全面发展。人文经济学，打破“重物质轻精神”的传统发展逻辑，追求物质与精神的同频共振、协调发展。推动高质量发展，文化是重要支点。","文化的力量是经济发展的新引擎和助推器，将中华优秀传统文化中蕴含的人文精神融人社会主义市场经济，可以让人文精神为高质量发展创造文化新动能。满足人民日益增长的美好生活需要，文化是重要因素。只有坚持以人民为中心，大力繁荣文化事业，加快发展文化产业，才能提供更多更好的精神食粮，不断提升人民的幸福指数。","在中国式现代化进程中，要继续做好“人文经济学”大文章，以文化赋能经济社会发展，推动人文和经济共生共荣、相得益彰。"],"explanation":"代化的显著标志。中国式现代化坚持以人民为中心，突出现代化方向的人民性，把实现人民对\n美好生活的向往作为现代化建设的出发点和落脚点，在推动高质量发展的同时，解决好地区差\n距、城乡差距、收入分配差距，着力维护和促进社会公平正义，坚决防止两极分化。\n推动区域协调发展，是解决发展不平衡不充分问题的重要途径，是推动高质量发展、促进共\n同富裕的内在要求。在现代化进程中，推动区域协调发展迈向更高水平，提升各地区居民的收\n人水平和生活质量，进一步提高发展的平衡性、协调性、包容性，有助于实现发展成果共享。\n(2)中国式现代化是物质文明和精神文明相协调的现代化。物质富足、精神富有是社会主\n义现代化的根本要求。必须坚持两手抓、两手硬，不断厚植现代化的物质基础，不断夯实人民幸\n福生活的物质条件，同时大力发展社会主义先进文化，加强理想信念教育，传承中华文明，促进\n物的全面丰富和人的全面发展。\n人文经济学，打破“重物质轻精神”的传统发展逻辑，追求物质与精神的同频共振、协调发\n展。推动高质量发展，文化是重要支点。文化的力量是经济发展的新引擎和助推器，将中华优\n秀传统文化中蕴含的人文精神融人社会主义市场经济，可以让人文精神为高质量发展创造文化\n新动能。满足人民日益增长的美好生活需要，文化是重要因素。只有坚持以人民为中心，大力\n繁荣文化事业，加快发展文化产业，才能提供更多更好的精神食粮，不断提升人民的幸福指数。\n在中国式现代化进程中，要继续做好“人文经济学”大文章，以文化赋能经济社会发展，推动人文\n和经济共生共荣、相得益彰。","tags":["肖四","第3套","材料分析题"]},
  {"id":"q-maozhongte-40","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"建国初期，随着全国土地改革的基本完成，国内的主要矛盾是","options":[{"key":"A","text":"人民大众同帝国主义、封建主义和国民党反动派残余势力之间的矛盾"},{"key":"B","text":"工人阶级和资产阶级的矛盾"},{"key":"C","text":"生产力和生产关系、经济基础和上层建筑之间的矛盾"},{"key":"D","text":"人民日益增长的物质文化需要同落后的社会生产之间的矛盾"}],"answerKey":"B","explanation":"B正确。A是新中国成立至全国土地改革基本完成期间国内的主要矛盾；C是社会基本矛\n盾，贯穿人类社会发展过程的始终；D是社会主义改造完成后中国社会的主要矛盾。\n点拨题干问的是土改基本完成（1952年底）之后国内的主要矛盾，不是土改完成之前的主要\n矛盾。","tags":["肖四","第4套","单选题"]},
  {"id":"q-maozhongte-41","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"我国发展最大的不平衡是城乡发展不平衡，最大的不充分是农村发展不充分。必须坚持把解决好“三农”问题作为全党工作重中之重，扎实推进乡村全面振兴。推进乡村全面振兴的基础是","options":[{"key":"A","text":"农业农村现代化"},{"key":"B","text":"发展乡村特色产业"},{"key":"C","text":"持续深化农村科技和改革创新"},{"key":"D","text":"建立健全城乡融合发展体制"}],"answerKey":"B","explanation":"习近平在广东考察时指出，发展乡村特色产业是推进乡村全面振兴的基础，要加强科技应\n用，推动农文旅融合，不断延伸产业链、增加附加值，带动更多农民群众增收致富。B正确。实施\n乡村振兴战略，农业农村现代化是总目标，坚持农业农村优先发展是总方针，产业兴旺、生态宜\n居、乡风文明、治理有效、生活富裕是总要求，建立健全城乡融合发展体制机制和政策体系是制度\n保障。A、D错误。农业农村部印发的《国家乡村振兴示范县创建工作方案》，从五个方面重点部\n署国家乡村振兴示范县创建任务，“持续深化农村科技和改革创新”是其中之一。C错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-maozhongte-42","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"中华民族共同体的形成和发展是人心所向、大势所趋、历史必然。中华民族缔造统一的多民族国家的内生动力是","options":[{"key":"A","text":"各民族血脉相融"},{"key":"B","text":"各民族信念相同"},{"key":"C","text":"各民族文化相通"},{"key":"D","text":"各民族经济相依"}],"answerKey":"B","explanation":"体形成和发展的历史根基；各民族信念相同，是中华民族缔造统一的多民族国家的内生动力；各\n民族文化相通，是中华民族铸就多元一体文明格局的文化基因；各民族经济相依，是中华民族构\n建统一经济体的强大力量；各民族情感相亲，是中华民族一家亲的坚强纽带。B正确，A、C、D\n错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-maozhongte-43","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"党的十八大以来，党中央坚持把就业工作摆在治国理政的突出位置，强化就业优先政策，健全就业促进机制，有效应对各种压力挑战，为民生改善和经济发展提供了重要支撑。新时代新征程就业工作的新定位、新使命是","options":[{"key":"A","text":"着力解决结构性就业矛盾"},{"key":"B","text":"拓展数字经济就业新空间，增加绿色就业新机会"},{"key":"C","text":"推动经济社会发展与就业促进协调联动"},{"key":"D","text":"促进高质量充分就业"}],"answerKey":"D","explanation":"习近平在主持二十届中央政治局第十四次集体学习时强调，促进高质量充分就业，是新时\n代新征程就业工作的新定位、新使命。要坚持以人民为中心的发展思想，全面贯彻劳动者自主就\n业、市场调节就业、政府促进就业和鼓励创业的方针，持续促进就业质的有效提升和量的合理增\n长，不断增强广大劳动者的获得感幸福感安全感，为以中国式现代化全面推进强国建设、民族复\n兴伟业提供有力支撑。D正确，A、B、C错误。\n点拨人力资源供需不匹配，是当前我国就业领域面临的主要矛盾。","tags":["肖四","第4套","单选题"]},
  {"id":"q-maozhongte-44","type":"choice","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":1,"stem":"实现碳达峰碳中和，是中国站在对人类文明负责的高度，基于实现可持续发展的内在要求作出的重大决策部署。实现碳达峰碳中和的关键是","options":[{"key":"A","text":"大力推进循环经济"},{"key":"B","text":"实施节能降碳增效行动"},{"key":"C","text":"能源绿色低碳转型"},{"key":"D","text":"巩固提升碳汇能力"}],"answerKey":"C","explanation":"国务院新闻办公室于2025年11月8日发布《碳达峰碳中和的中国行动》白皮书。白皮书\n指出，能源活动是碳排放的最主要来源，能源绿色低碳转型是实现碳达峰碳中和的关键。节能是\n从源头减少碳排放的重要抓手，循环经济对碳减排具有重要促进作用，生态系统碳汇是实现减排\n固碳的重要途径。中国深人实施节能降碳增效行动、循环经济助力降碳行动、碳汇能力巩固提升\n行动，取得积极成效。C正确。","tags":["肖四","第4套","单选题"]},
  {"id":"q-maozhongte-45","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"党的十一届三中全会以后，以邓小平同志为主要代表的中国共产党人重新确立并丰富发展了实事求是的思想路线,提出了一系列有利于增强党的团结和调动一切积极因素的方针政策。党的思想路线的重新确立，解决了一系列重大理论和实践问题。具体来说就是，坚持解放思想、实事求是","options":[{"key":"A","text":"有力推动和保证了拨乱反正的进行"},{"key":"B","text":"破除了侮化的社会主义模式观念，坚持走自己的路"},{"key":"C","text":"坚持以“三个有利于”作为检验一切工作是非得失的根本标准"},{"key":"D","text":"一切从社会主义初级阶段的实际出发"}],"answerKeys":["A","B","C","D"],"explanation":"安党的思想路线的重新确立，解决了一系列重大理论和实践问题。（1)坚持解放思想、实事\n求是,有力推动和保证了拨乱反正的进行。（2)坚持解放思想、实事求是,破除了僵化的社会主\n义模式观念，坚持走自已的路。（3)坚持解放思想、实事求是，一切从社会主义初级阶段的实际\n出发。（4)坚持解放思想、实事求是，坚持以“三个有利于”作为检验一切工作是非得失的根本标\n准，破除了在改革开放进程中离开发展生产力抽象谈论姓“社”姓“资”的思维定势，把我国的改\n革开放和现代化建设推进到一个新的阶段。A、B、C、D全选。","tags":["肖四","第4套","多选题"]},
  {"id":"q-maozhongte-46","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"党的十一届三中全会以来，我们党实行改革开放，为民营经济快速发展创造了前所未有的历史机遇。现在，我国民营经济已经形成相当的规模、占有很重的分量。当然，我们也要清醒看到，当前民营经济发展确实面临一些困难和挑战。这些困难和挑战","options":[{"key":"A","text":"是制度性的而不是人为的"},{"key":"B","text":"是局部的而不是整体的"},{"key":"C","text":"是暂时的而不是长期的"},{"key":"D","text":"是能够克服的而不是无解的"}],"answerKeys":["B","C","D"],"explanation":"2025年2月17日，习近平在北京出席民营企业座谈会并发表重要讲话。习近平指出，当\n前民营经济发展确实面临一些困难和挑战。这些困难和挑战总体上是在改革发展、产业转型升\n级过程中出现的而不是制度性的,是局部的而不是整体的，是暂时的而不是长期的，是能够克服\n的而不是无解的。B、C、D正确,A错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-maozhongte-47","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"粤港澳大湾区是中国开放程度最高，经济活力最强的区域之一。推进粤港澳大湾区建设，就是要打造","options":[{"key":"A","text":"中国新发展格局的战略支点"},{"key":"B","text":"高质量发展的示范地"},{"key":"C","text":"中国式现代化的引领地"},{"key":"D","text":"引领我国新时代对外开放的重要门户"}],"answerKeys":["A","B","C"],"explanation":"2025年11月9日，习近平在广州白云国际会议中心会见来华出席第十五届全国运动会开\n幕式的国际奥委会主席考文垂和终身名誉主席巴赫。习近平强调，全运会是中国最大规模、最\n高水平的综合性运动会，这届全运会由广东、香港、澳门三地合办。粤港澳大湾区是中国开放程\n度最高、经济活力最强的区域之一。推进粤港澳大湾区建设，就是要打造中国新发展格局的战\n略支点、高质量发展的示范地、中国式现代化的引领地。相信这届全运会不仅将见证新时代中\n国体育事业发展的新成就，也将展现中国式现代化在粤港澳大湾区的万千气象。A、B、C正确。\n11月6日，习近平在海南省三亚市听取海南自由贸易港建设工作汇报时强调，建设海南自由贸\n易港的战略目标，就是要把海南自由贸易港打造成为引领我国新时代对外开放的重要门户。D\n错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-maozhongte-48","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"现代化产业体系是中国式现代化的物质技术基础。构建现代化产业体系，要","options":[{"key":"A","text":"以先进制造业为骨干"},{"key":"B","text":"坚持智能化、绿色化、融合化方向"},{"key":"C","text":"优化提升传统产业，培育壮大新兴产业和未来产业"},{"key":"D","text":"促进服务业优质高效发展，构建现代化基础设施体系"}],"answerKeys":["A","B","C","D"],"explanation":"《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》指出，现代化产业体\n系是中国式现代化的物质技术基础。坚持把发展经济的着力点放在实体经济上，坚持智能化、绿\n色化、融合化方向，加快建设制造强国、质量强国、航天强国、交通强国、网络强国，保持制造业合理\n比重，构建以先进制造业为骨干的现代化产业体系。《建议》强调，要优化提升传统产业，培育壮大\n新兴产业和未来产业，促进服务业优质高效发展，构建现代化基础设施体系。A、B、C","tags":["肖四","第4套","多选题"]},
  {"id":"q-maozhongte-49","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"绿水青山就是金山银山理念是立足自身国情和发展实践形成的中国自主生态文明建设理论，符合人类社会发展规律和生态文明建设规律，在实践中展现出强大的真理力量和独特的思想魅力。绿水青山就是金山银山理念","options":[{"key":"A","text":"创新和突破了现代环境经济理论"},{"key":"B","text":"推进和拓展了中国式现代化道路"},{"key":"C","text":"传承和发展了中华优秀传统生态文化"},{"key":"D","text":"推动和创造了人类文明新形态"}],"answerKeys":["A","B","C","D"],"explanation":"22025年8月10日，新华社国家高端智库与习近平生态文明思想研究中心在北京共同发布\n《绿水青山绘就美丽画卷一一生态文明建设的中国创新与世界意义》智库报告。报告指出，绿水\n青山就是金山银山理念，创新和突破了现代环境经济理论；推进和拓展了中国式现代化道路；传\n承和发展了中华优秀传统生态文化；推动和创造了人类文明新形态。A、B、C、D全选。","tags":["肖四","第4套","多选题"]},
  {"id":"q-maozhongte-50","type":"multi","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":2,"stem":"1957年2月，毛泽东作了《关于正确处理人民内部矛盾的问题》的报告，阐明社会主义社会的重大理论问题,其主要内容有","options":[{"key":"A","text":"提出社会主义社会的基本矛盾仍然是生产力和生产关系、经济基础和上层建筑之间的矛盾"},{"key":"B","text":"提出社会主义社会存在着敌我矛盾和人民内部矛盾这两类不同性质的社会矛盾"},{"key":"C","text":"提出社会主义社会的主要矛盾是人民日益增长的物质文化需要同落后的社会生产之间的矛盾"},{"key":"D","text":"提出把正确处理人民内部矛盾作为国家政治生活的主题"}],"answerKeys":["A","B","D"],"explanation":"A、B、D正确。“在社会主义改造基本完成以后，我国所要解决的主要矛盾，是人民日益增\n长的物质文化需要同落后的社会生产之间的矛盾”，这是1981年党的十一届六中全会通过的\n《关于建国以来党的若干历史问题的决议》对我国社会主要矛盾的规范表述，并不是毛泽东在\n《关于正确处理人民内部矛盾的问题》的报告中提出的，C错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-maozhongte-51","type":"material","module":"毛泽东思想和中国特色社会主义理论体系","difficulty":3,"stem":"结合材料回答问题：（1）如何理解“推动高质量发展，最重要是加快高水平科技自立自强，积极发展新质生产力”？（2）为什么要“坚持统发展和安全”？","material":{"title":"材料","paragraphs":["材料1 推动高质量发展，最重要是加快高水平科技自立自强，积极发展新质生产力，在推动科技创新、加快培育新动能、促进经济结构优化升级上取得实质性、突破性进展。","摘自习近平《关于《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》的说明》","材料2 当今世界变乱交织。未来5年，我国发展面临的各种不确定难预料风险因素将明显增多，统筹发展和安全任务更加艰巨。全会围绕推进国家安全体系和能力现代化，提出健全国家安全体系，加强重点领域国家安全能力建设，提高公共安全治理水平，完善社会治理体系；围绕高质量推进国防和军队现代化，提出加快先进战斗力建设，推进军事治理现代化，巩固提高一体化国家战略体系和能力。认真学习、切实贯彻党的二十届四中全会精神，以历史主动精神克难关、战风险、迎挑战，定能有效防范化解各类风险,增强经济和社会韧性。","摘编自《人民日报》（2025年10月30日）"]},"answerPoints":["族复兴的战略基石，是应对风险挑战和维护国家利益的必然选择，是构建新发展格局、推动高质量发展、满足人民美好生活需要的内在要求。高水平科技自立自强是高质量发展的战略支撑。推动高质量发展，以质量变革、效率变革、动力变革推动现代化经济体系建设，要求以强大科技作支撑，提供新的发展空间、关键着力点和主要支撑体系。","面对复杂严峻的国内外形势，以高水平科技自立自强筑牢高质量发展根基,才能积极应对各种不确定性不稳定性。新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。发展新质生产力，科技创新是核心要素，全要素生产率大幅提升是核心标志。","发展新质生产力是推动高质量发展的内在要求和重要着力点。依靠科技现代化、推动科技创新，因地制宜发展新质生产力，提高全要素生产率，才能为高质量发展提供动力引擎。","统筹发展和安全，是党和国家的一项基础性工作,是我们党治国理政的一个重大原则。第一，发展和安全是两件大事。发展解决的是动力问题，是推动国家和民族续绵延的根本支撑；安全解决的是保障问题，是确保国家和民族行稳致远的坚强柱石。第二，发展具有基础性、根本性，是解决安全问题的总钥匙，发展就是最大的安全。","安全是发展的条件和保障，没有国家安全，发展取得的成果也可能毁于一旦。第三，发展是硬道理，安全也是硬道理，要把发展和安全统一起来，共同谋划、一体部署、相互促进。要在发展中固安全，在安全中谋发展，以新安全格局保障新发展格局，努力实现高质量发展和高水平安全良性互动。"],"explanation":"族复兴的战略基石，是应对风险挑战和维护国家利益的必然选择，是构建新发展格局、推动高质\n量发展、满足人民美好生活需要的内在要求。高水平科技自立自强是高质量发展的战略支撑。\n推动高质量发展，以质量变革、效率变革、动力变革推动现代化经济体系建设，要求以强大科技\n作支撑，提供新的发展空间、关键着力点和主要支撑体系。面对复杂严峻的国内外形势，以高水\n平科技自立自强筑牢高质量发展根基,才能积极应对各种不确定性不稳定性。\n新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高\n效能、高质量特征，符合新发展理念的先进生产力质态。发展新质生产力，科技创新是核心要\n素，全要素生产率大幅提升是核心标志。发展新质生产力是推动高质量发展的内在要求和重要\n着力点。依靠科技现代化、推动科技创新，因地制宜发展新质生产力，提高全要素生产率，才能\n为高质量发展提供动力引擎。\n（2）统筹发展和安全，是党和国家的一项基础性工作,是我们党治国理政的一个重大原则。\n第一，发展和安全是两件大事。发展解决的是动力问题，是推动国家和民族续绵延的根\n本支撑；安全解决的是保障问题，是确保国家和民族行稳致远的坚强柱石。\n第二，发展具有基础性、根本性，是解决安全问题的总钥匙，发展就是最大的安全。安全是\n发展的条件和保障，没有国家安全，发展取得的成果也可能毁于一旦。\n第三，发展是硬道理，安全也是硬道理，要把发展和安全统一起来，共同谋划、一体部署、相\n互促进。要在发展中固安全，在安全中谋发展，以新安全格局保障新发展格局，努力实现高质量\n发展和高水平安全良性互动。","tags":["肖四","第4套","材料分析题"]},
  {"id":"q-mayuan-3","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"1921年中国共产党的成立,是中华民族伟大复兴征程中的一大里程碑。100多年来,不管形势和任务如何变化,不管遇到什么样的惊涛骇浪，我们党都始终把握历史主动、锚定奋斗目标,沿着正确方向坚定前行。历史和实践充分证明,我们党坚定信仰信念、把握历史主动的根本所在是","options":[{"key":"A","text":"拥有马克思主义科学理论指导"},{"key":"B","text":"坚持不懈用党的创新理论凝心铸魂"},{"key":"C","text":"始终把人民放在心中最高位置"},{"key":"D","text":"科学社会主义提供了解决实际问题的正确答案"}],"answerKey":"A","explanation":"马克思主义是引领当代中国实践的行动指南。马克思主义是我们的“看家本领”，掌握了这一本领，就能够以更宽广的视野、更长远的眼光来思考和把握未来发展面临的一系列重大问题，应对重大挑战，抵御重大风险，克服重大阻力，解决重大矛盾。拥有马克思主义科学理论指导是我们党坚定信仰信念、把握历史主动的根本所在。A正确。","tags":["肖四","第1套","单选题"]},
  {"id":"q-mayuan-4","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"中国是农业发达的文明古国,春耕、夏耘、秋收、冬藏是农业社会基本的生产实践活动。发于农耕文明的“二十四节气”,是古人观察时令、气候、物候等现象时总结出的时间知识体系,它能够准确反映自然节律变化，一直沿用至今。现代的人们仍能够通过“二十四节气”指导四时农耕,说明","options":[{"key":"A","text":"真理是永恒不变的"},{"key":"B","text":"自然规律具有重复性和稳定性"},{"key":"C","text":"一切真知都是从间接经验发源的"},{"key":"D","text":"正确的认识具有直接现实性"}],"answerKey":"B","explanation":"规律具有重复性。只要具备一定的条件,某种合乎规律的联系就以一种不可抗拒的趋势重\n复出现，发生作用。规律具有稳定性。世界上的事物和现象总是千差万别、变化不定的，但规律\n却是变化不定的现象中隐含着的相对稳定的东西。正是因为自然规律具有重复性和稳定性，人\n们在掌握了正确反映自然规律的“二十四节气”后,沿用至今,依然能在现实中获得与预想基本一\n致的结果。B正确。割裂真理的绝对性与相对性的辩证关系，就会走向形而上学的真理观,即绝\n对主义和相对主义。绝对主义又称独断论,片面夸大真理的绝对性,否认真理的相对性，认为真\n理是永恒不变的,把人类认识之旅中的“里程碑”当成“终点站”,因而堵塞了人类认识进一步发展\n的道路。A错误。离开实践的认识是不可能产生的。一切真知都是从直接经验发源的。C错误。\n实践具有直接现实性，认识只有通过实践才能变成直接的、实实在在的现实。D错误。","tags":["肖四","第1套","单选题"]},
  {"id":"q-mayuan-5","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"在资本主义条件下,劳动是否是生产性的,取决于","options":[{"key":"A","text":"劳动是生产物质产品还是提供服务"},{"key":"B","text":"具体劳动能否还原为抽象劳动"},{"key":"C","text":"劳动能否为资本家带来剩余价值"},{"key":"D","text":"劳动力是否为社会生产发展所绝对需要"}],"answerKey":"C","explanation":"在资本主义条件下，劳动是否是生产性的，并不取决于劳动是生产物质产品还是提供服务，而\n取决于劳动能否为资本家带来剩余价值，只有创造剩余价值的劳动才是生产性劳动。C正确。","tags":["肖四","第1套","单选题"]},
  {"id":"q-mayuan-6","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"1921年3月，俄共（布）召开十大,毅然决定从战时共产主义政策过渡到新经济政策。新经济政策的主要特征是","options":[{"key":"A","text":"开展农业合作化"},{"key":"B","text":"发展商品经济"},{"key":"C","text":"发展大工业"},{"key":"D","text":"实行国家资本主义"}],"answerKey":"B","explanation":"从1918年夏到1921年春，列宁领导的苏维埃政权实行了以余粮收集制和取润\n系为主要特征的战时共产主义政策。1921年3月，俄共（布)召开十大，毅然决定从战时共产主义\n政策过渡到实行以发展商品经济为主要特征的新经济政策。其主要内容有：用粮食税制取代余\n粮收集制，允许私人自由贸易，恢复商品货币关系，允许私人小工业企业发展，采取一些国家资本\n主义的形式来发展生产。B正确。","tags":["肖四","第1套","单选题"]},
  {"id":"q-mayuan-7","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"习近平指出,人工智能带来前所未有发展机遇,也带来前所未遇风险挑战。要把握人工智能发展趋势和规律，加紧制定完善相关法律法规、政策制度、应用规范、伦理准则，构建技术监测、风险预警、应急响应体系，确保人工智能安全、可靠、可控。这启示我们","options":[{"key":"A","text":"对待人工智能要坚持“两点论”和“重点论”的统一"},{"key":"B","text":"事物的本质有一个逐渐暴露、逐渐展开的过程"},{"key":"C","text":"在人工智能这类新技术的治理中要加强底线思维"},{"key":"D","text":"发展人工智能要坚持真理尺度和价值尺度的统一"}],"answerKeys":["A","B","C","D"],"explanation":"“两点论”是指在分析事物的矛盾时，不仅要看到矛盾双方的对立，而且要看到矛盾双方的\n统一；不仅要看到矛盾体系中存在主要矛盾、矛盾的主要方面，而且要看到次要矛盾、矛盾的次\n要方面。“重点论”是指要着重把握主要矛盾、矛盾的主要方面,并以此作为解决问题的出发点。\n“两点论”和“重点论”的统一要求我们，看问题既要全面地看，又要看主流、大势、发展趋势。对\n待人工智能,既要看到人工智能带来机遇的一面,也要看到人工智能带来风险的一面。A正确。\n事物的现象错综复杂，而且事物的本质有一个逐渐暴露、逐渐展开的过程，所以，人们对事物本\n质的认识不是一次完成的，而是一个不断深化的过程。对于人工智能发展趋势和规律的认识也\n是一个逐渐深化的过程,B正确。底线思维是我们在认识世界和改造世界的过程中,根据我们的\n需要和客观的条件，划清并坚守底线，尽力化解风险，避免最坏结果，同时争取实现最大期望值\n的一种积极的思维。人工智能带来了前所未遇的风险挑战,因此底线思维在人工智能治理领域\n有其特殊重要性。C正确。任何成功的实践都是真理尺度和价值尺度的统一,是合规律性和合\n目的性的统一。D正确。","tags":["肖四","第1套","多选题"]},
  {"id":"q-mayuan-8","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"18.列宁在《唯物主义和经验批判主义》中指出，“当我们不知道自然规律的时候，自然规律是在我们的认识之外独立地存在着并起着作用,使我们成为“盲目的必然性”的奴隶。一经我们认识了这种不依赖于我们的意志和我们的意识而起着作用的（如马克思千百次反复说过的那样）规律，我们就成为自然界的主人。”以下说法正确的有","options":[{"key":"A","text":"认识必然和争取自由是一个历史性的过程"},{"key":"B","text":"人类可以打破对自然界的依赖关系而获得绝对的自由"},{"key":"C","text":"人对一定问题的判断越是自由，这个判断的内容所具有的必然性就越大"},{"key":"D","text":"只有充分发挥主观能动性,才能实现超越社会发展阶段的自由"}],"answerKeys":["A","C"],"explanation":"认识必然和争取自由，是人类认识世界和改造世界的根本目标，是一个历史性的过程。A\n正确。自由不在于幻想中摆脱自然规律而独立，而在于认识这些规律，从而能够有计划地使自\n然规律为一定的目的服务。因此,人对一定问题的判断越是自由，这个判断的内容所具有的必\n然性就越大。C正确。自由是相对的,不是绝对的。彻底的、绝对的自由是根本不存在的，人所\n享有的自由总是相对的。B错误。自由是具体的、历史的。任何实践都是一定历史阶段的具体\n实践，因而由主客观条件制约的自由也必然是具体的、历史的，超越社会发展阶段、超越实践能\n力与实践发展水平的自由是不可能实现的。D错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-mayuan-9","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"当前,世界之变、时代之变、历史之变正以前所未有的方式展开。面对动荡多变的国际形势，只有站在历史正确的一边，拿出智慧、勇气和担当，才能作出正确选择。从唯物史观的角度分析，要“站在历史正确的一边”是因为","options":[{"key":"A","text":"历史发展有其自身的客观规律"},{"key":"B","text":"任何历史人物都不能决定和改变历史发展的总进程和总方向"},{"key":"C","text":"正确认识历史发展方向是社会历史存在和发展的前提"},{"key":"D","text":"历史规律不以任何个人、阶级的意志为转移"}],"answerKeys":["A","B","D"],"explanation":"自然规律和社会规律都具有不以人的意志为转移的客观性。历史规律不以任何个人、阶\n级以至整个人类的意志为转移。A、D正确。不管什么样的历史人物，在历史上发挥什么样的作\n用，都要受到社会发展客观规律的制约，而不能决定和改变历史发展的总进程和总方向。B正\n确。唯物史观认为，人不是抽象的而是现实的,现实的人及其活动是社会历史存在和发展的前\n提。C错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-mayuan-10","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"经济危机实际上是资本主义条件下以强制的方式解决社会再生产的实现问题的途径，这种解决方式虽然最终也能够使社会再生产由失衡慢慢转变为平衡，却是以社会经济生活的严重混乱甚至瘫以及社会资源和财富的极大浪费为代价的。以下关于经济危机的认识，正确的有","options":[{"key":"A","text":"只要存在资本主义制度，经济危机就是不可避免的"},{"key":"B","text":"资本主义经济危机具有周期性，这是由社会资本再生产的周期性决定的"},{"key":"C","text":"生产过剩是资本主义经济危机的本质特征"},{"key":"D","text":"经济危机的抽象的一般的可能性，首先是由货币作为流通手段和支付手段引起的"}],"answerKeys":["A","C","D"],"explanation":"资本主义发展到一定阶段，就会发生以生产过剩为基本特征的经济危机。当经济危机发\n生时，大量商品积压，大批生产企业减产或停工，许多金融机构倒闭，整个社会经济生活一片混\n乱。生产过剩是资本主义经济危机的本质特征，但是这种过剩是相对过剩，即相对于劳动人民\n有支付能力的需求来说社会生产的商品显得过剩，而不是与劳动人民的实际\n这仅仅是危机在形式上的可能性。资本主义经济危机爆发的根本原因是资本主义的基本矛盾。\n只要存在资本主义制度，经济危机就是不可避免的。A、C、D正确。资本主义经济危机具有周期\n性,这是由资本主义基本矛盾运动的阶段性决定的。B错误。\n点拨注意另一个提法：资本主义经济危机周期性爆发的特点，使社会资本再生产也呈现出周\n期性的特点。","tags":["肖四","第1套","多选题"]},
  {"id":"q-mayuan-11","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"资本主义生产的目的是获得利润。不同生产部门的资本家之间为了得到尽可能多的利润必然展开激烈的竞争从而导致利润平均化。平均利润形成后","options":[{"key":"A","text":"商品价值就转化为生产价格"},{"key":"B","text":"价值规律的实现形式发生了变化"},{"key":"C","text":"生产价格不再随着商品价值的变化而变动"},{"key":"D","text":"每一个部门获得的利润都等于该部门生产的剩余价值"}],"answerKeys":["A","B"],"explanation":"利润转化为平均利润，价值也就转化为生产价格。生产价格是商品价值的转化形式，是生\n产成本与平均利润之和。A正确。生产价格是价值的转化形式，商品按照生产价格而不是价值\n出售并不违背价值规律，而是价值规律的实现形式发生了变化。虽然从个别部门来看，资本家\n获得的平均利润与本部门工人创造的剩余价值可能不一致，但从全社会来看，整个资本家阶级\n获得的利润总额与雇佣工人所创造的剩余价值总额是相等的。B正确,D错误。生产价格随着\n商品价值的变化而变动，生产商品的社会必要劳动时间减少，生产价格就会降低；反之，生产价\n格就会提高。C错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-mayuan-12","type":"material","module":"马克思主义基本原理","difficulty":3,"stem":"结合材料回答问题：（1）如何理解“向善惠民，始终是科技创新的价值取向”？（2）为什么在鼓励创新的同时也要宽容失败？","material":{"title":"材料","paragraphs":["材料 1 习近平总书记强调：“要把满足人民对美好生活的向往作为科技创新的落脚点，把惠民、利民、富民、改善民生作为科技创新的重要方向。”向善惠民，始终是科技创新的价值取向。在乡村沃野，智能高效稻麦联合收割机1分钟收割600公斤作物，大幅提高夏收秋收效率；在医院手术室，国产骨科手术机器人、腔镜手术机器人投入应用；在养老机构，智能腕表和智能拐杖等装备优化养老服务…·……“十四五”期间，一个个“小而美”的科技创新成果与百姓生活深度融合，更好满足人民群众对美好生活的向往。恩格斯曾说，“社会一旦有技术上的需要，则这种需要就会比十所大学更能把科学推向前进。”我国有14亿多人口，中等收入群体规模超4亿人，拥有超大规模市场和丰富的技术应用场景。民生日用的现实需求与日俱增，各行业对新技术、新产品翘首以盼。当供给侧“贴合”需求侧，当生产与消费深度互动，创新的“星星之火”就能以“燎原之势”形成新的产业蓝海。往深层看，坚持科技向善惠民，不仅关乎民生改善，更关乎科技创新的未来。当今时代，人工智能、生物医药、基因编辑等新技术在激发发展新动能的同时，也对社会治理、法律规则等各方面带来新的冲击。比如，大语言模型处理、生成数据时，可能侵犯个人隐私；换脸、拟声等技术可能被用来诈骗、制造虚假信息。因此，科技创新已经不只是一个技术课题，而是具有了更鲜明的价值属性、治理属性、伦理属性。只有坚持科技向善惠民，并在这样的价值基准上完善社会治理、法律规则，才能在防范社会风险的同时让科技创新的正向效应最大化。中国式现代化，民生为大。科技创新最终要落到“人”上。新征程上，抓住一切有利时机，利用一切有利条件，推动更多好技术变成新应用，定能以科技创新的累累硕果惠及广大群众，创造更加美好的生活。","摘编自《人民日报》（2025年10月15日）","材料2 前不久，到宇树科技参观，负责人特意介绍起脚下的一段楼梯：低处的台阶边缘多处破损，越往上，破损痕迹越少。原来，这是训练机器人时留下的。一开始，机器人可能走不了几步就会摔倒;经过不断调试改良，越走越顺利，爬楼已经不在话下。这段意义独特的楼梯，镌刻成长之路，照见创新之路。创新是一个不断试错的过程，望而却步不行，盲目蛮千也不行。在我国航天领域,有一套独特的工作方法一一归零。哪方面出现问题时，就从技术和管理两个层面，对问题进行定位、分析、复现、纠正、举一反三，确保从根本上消除问题。正因为不怕试错、善于纠错，才成就了探月工程六战六捷的佳绩。有位科研人员说得好：“做科研最不怕的就是“问题’，有“问题’的地方正是科研可挖的“并，。”大胆假设、认真求证，在总结经验教训中再出发，才能通往成功彼岸。不断试错的创新，需要更多包容与支持。在2025年世界人形机器人运动会上，一些机器人“选手”摔倒等情况引发讨论。事实上，创新就有可能跌跌撞撞。新兴产业与未来产业在孕育早期,也很难做到“零失误”“零瑕疵”。从稚嫩到成熟,从跟跑到奔跑,这是事物发展的必经阶段。过去，新能源汽车续航短是个困扰，但今天“里程焦虑”正在技术的升级下不断得到缓解，新能源汽车越来越受欢迎。近来，多地出台科技创新“容错”新规，更多耐心资本充当企业“长跑搭档”。营造好鼓励创新、宽容失败的环境，给予创新创业“十年不鸣”的底气，才能浇灌出“一鸣惊人”的硕果。","摘编自《人民日报》（2025年10月9日）"]},"answerPoints":["起生产方式、生活方式和思维方式的深刻变化和社会的巨大进步。科学技术能够通过促进经济和社会发展以造福于人类，同时也可能在一定条件下对人类的生存和发展带来消极后果。科学技术的作用既受到一定客观条件如社会制度、利益关系的影响，也受到一定主观条件如人们的观念和认识水平的影响。","正确认识和运用科学技术，首要的就是有合理的社会制度保障科学技术的正确运用，始终坚持使科学技术为人类的健康发展服务，让科技为人类造福。人们的实践活动总是受着真理尺度和价值尺度的制约。任何成功的实践都是真理尺度和价值尺度的统一，是合规律性和合目的性的统一。","在实践中人们都是按照自己的尺度和需要去认识世界和改造世界，只有推动科技创新向善惠民，才能符合价值尺度，从而达到真理尺度和价值尺度的统一。(2)真理与谬误、成功与失败在一定条件下能够相互转化。在认识探索的过程中，“错误往往是正确的先导”，失败常常是成功之母，总结失败的教训，是获得真理、消除谬误的重要途径和方法。","由于认识的复杂性和曲折性以及各种条件的限制，任何人都有可能犯错误，但吃一堑、长一智，勇于正视错误、反省错误、修正错误，终能取得对客观事物及其规律的正确认识，从而让错误转化为正确，谬误转化为真理。在批判谬误中发展真理，是谬误向真理转化的一种形式。事物的发展是前进性与曲折性的统一。","新事物在发展中遇到一些困难和问题是难以避免的，但社会历史不断发展前进的总趋势是不变的。任何时候我们都不能失去开拓前进的信心和勇气，同时又要高度重视和认真对待前进中的曲折，在应对挑战和解决矛盾中推动社会发展。"],"explanation":"起生产方式、生活方式和思维方式的深刻变化和社会的巨大进步。科学技术能够通过促进经济\n和社会发展以造福于人类，同时也可能在一定条件下对人类的生存和发展带来消极后果。科学\n技术的作用既受到一定客观条件如社会制度、利益关系的影响，也受到一定主观条件如人们的\n观念和认识水平的影响。正确认识和运用科学技术，首要的就是有合理的社会制度保障科学技\n术的正确运用，始终坚持使科学技术为人类的健康发展服务，让科技为人类造福。\n人们的实践活动总是受着真理尺度和价值尺度的制约。任何成功的实践都是真理尺度和\n价值尺度的统一，是合规律性和合目的性的统一。在实践中人们都是按照自己的尺度和需要去\n认识世界和改造世界，只有推动科技创新向善惠民，才能符合价值尺度，从而达到真理尺度和价\n值尺度的统一。\n(2)真理与谬误、成功与失败在一定条件下能够相互转化。在认识探索的过程中，“错误往\n往是正确的先导”，失败常常是成功之母，总结失败的教训，是获得真理、消除谬误的重要途径和\n方法。由于认识的复杂性和曲折性以及各种条件的限制，任何人都有可能犯错误，但吃一堑、长\n一智，勇于正视错误、反省错误、修正错误，终能取得对客观事物及其规律的正确认识，从而让错\n误转化为正确，谬误转化为真理。在批判谬误中发展真理，是谬误向真理转化的一种形式。\n事物的发展是前进性与曲折性的统一。新事物在发展中遇到一些困难和问题是难以避免\n的，但社会历史不断发展前进的总趋势是不变的。任何时候我们都不能失去开拓前进的信心和\n勇气，同时又要高度重视和认真对待前进中的曲折，在应对挑战和解决矛盾中推动社会发展。","tags":["肖四","第1套","材料分析题"]},
  {"id":"q-mayuan-13","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"“中华民族伟大复兴势不可挡！”习近平总书记在天安门城楼上的庄严宣示，是历史昭示的真理，是团结奋进的强音。今天，在全面推进中国式现代化的新征程上，我们比历史上任何时期都更接近、更有信心和能力实现中华民族伟大复兴的目标，同时必须准备付出更为艰巨、更为艰苦的努力。推进中华民族伟大复兴历史进程，要求我们增强历史主动、发扬实干精神，这是因为","options":[{"key":"A","text":"每一个人都是历史的创造者"},{"key":"B","text":"人能够按照自己的需要去认识规律和改造规律"},{"key":"C","text":"历史规律只有通过人的有目的、有意识的活动才能实现"},{"key":"D","text":"人们在自已选定的条件下创造历史"}],"answerKey":"C","explanation":"自自然规律通过盲目的、不自觉的力量在起作用并实现出来。历史规律则不同。人的活动是\n历史规律得以存在并发生作用的前提、基础和途径，历史规律只有通过人的有目的、有意识的活\n动才能实现。中华民族伟大复兴势不可挡,但也必须通过人的实践奋斗才能实现。C正确。规律\n是客观的，人们可以认识规律但不能改造规律。B错误。人民群众是历史的创造者。就每一个人\n而言，他在一定意义上“创造”了自己的“历史”即通过自己的人生谱写了自身个体的“历史”，但\n这并不能与创造社会历史画等号。A错误。马克思指出：“人们自已创造自己的历史，但是他们\n并不是随心所欲地创造，并不是在他们自已选定的条件下创造，而是在直接碰到的、既定的、从过\n去承继下来的条件下创造。D错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-mayuan-14","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"20世纪初,物理学家卡尔·史瓦西解出了爱因斯坦广义相对论的一个精确解,这个数学结果预言：如果一个天体的质量被压缩到某个临界半径内，它周围的时空将变得极度弯曲,形成一个连光也无法逃逸的区域。这个区域就是黑洞。然而，黑洞的存在曾一度饱受质疑，就连爱因斯坦也认为它只是数学上的假想产物,并非真实存在。直到1971年，天文观测显示,天鹅座X一1双星系统中伴随蓝超巨星的不可见天体极有可能是一个黑洞。之后越来越多的观测证据显示，黑洞广泛存在于星系中心和大质量恒星残中。2019年，M87星系中心超大质量黑洞的照片发布，我们得以“看见”黑洞。黑洞从一个预言中的概念到最终被人们观测到，说明人的认识","options":[{"key":"A","text":"可以超前于直接的实践"},{"key":"B","text":"是自己头脑里固有的"},{"key":"C","text":"是对客观世界的直观反映"},{"key":"D","text":"先于人的实践经验"}],"answerKey":"A","explanation":"具体的认识过程可以与一定的实践不完全同步进行，预测、假说、规划等就超前于直接的实\n践。A正确。唯物主义认识路线坚持反映论的立场,认为认识是主体对客体的反映，人的一切知\n识都是从后天接触实际中得来的。唯心主义认识路线否认认识是人脑对客观世界的反映，认为\n认识先于人的实践经验。其中,主观唯心主义认为人的认识是主观自生的，是生而知之的。客观\n唯心主义认为人的认识是上帝的启示或某种客观精神的产物。B、D错误。旧唯物主义只是物化\n性理解现实世界的存在,把人与外部世界的关系理解为直观反映关系。C错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-mayuan-15","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"社会生产是连续不断地进行的，这种连续不断重复的生产就是再生产。社会再生产的核心问题是","options":[{"key":"A","text":"两大部类在总量上的比例问题"},{"key":"B","text":"工资与剩余价值的分配问题"},{"key":"C","text":"社会总产品的实现问题"},{"key":"D","text":"劳动过程和价值增殖过程的统一问题"}],"answerKey":"C","explanation":"社会再生产的核心问题是社会总产品的实现问题，即社会总产品的价值补偿和实物补偿问\n题。C正确。","tags":["肖四","第2套","单选题"]},
  {"id":"q-mayuan-16","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"第二次世界大战后，由于多种社会因素的影响，资本主义发生了一系列变化。正确认识这些变化的原因和实质,对于在新的历史条件下深刻把握资本主义的本质和规律，具有十分重要的意义。导致第二次世界大战后资本主义发生变化的根本推动力量是","options":[{"key":"A","text":"改良主义政党对资本主义制度的改革"},{"key":"B","text":"工人阶级争取自身权利和利益的斗争"},{"key":"C","text":"社会主义制度的优越性对资本主义的影响"},{"key":"D","text":"科学技术革命和生产力的发展"}],"answerKey":"D","explanation":"第二次世界大战后，资本主义发生变化的原因主要有以下几个方面：（1)科学技术革命和生\n产力的发展,是资本主义发生变化的根本推动力量。（2)工人阶级争取自身权利和利益的斗争，\n是推动资本主义发生变化的重要力量。（3)社会主义制度初步显示的优越性对资本主义产生了\n重要影响。（4)主张改良主义的政党对资本主义制度的改革，也对资本主义发生变化起到了重要\n作用。D正确。","tags":["肖四","第2套","单选题"]},
  {"id":"q-mayuan-17","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"信息技术迅猛发展，催生了一个信息爆炸、思想奔涌的时代。海量信息以前所未有的速度与密度涌人社会认知领域，深度浸润青年一代。如何在纷繁复杂的信息海洋中保持清醒？人们需要批判性思维。辩证唯物主义揭示了“实践、认识、再实践、再认识”的螺旋式上升规律，而批判性思维正是实现这一认识飞跃的关键枢纽。它要求以实践为标准，不断检验、止思想化。具备批判性思维的青年，就如同拥有穿透迷雾的“理性之眼”，能够洞察事物本质与发展规律，在复杂社会现象前保持头脑冷静，作出明智判断与理性决策。在认识和实践活动中，批判性思维体现在","options":[{"key":"A","text":"对感性材料加以去粗取精、去伪存真"},{"key":"B","text":"在认识活动中避免任何非理性因素的作用"},{"key":"C","text":"在对现存事物的肯定的理解中同时包含对现存事物的否定的理解"},{"key":"D","text":"在实践中不断推翻以往的真理并建立新的真理"}],"answerKeys":["A","C"],"explanation":"只有对感性材料进行去粗取精、去伪存真、由此及彼、由表及里的改造，才能获得对于事物\n的本质和规律的认识。A正确。认识活动是一个复杂的运动过程，表现为无论在感性认识中还\n是在理性认识中,都有非理性因素的作用。非理性因素对于人的认识能力和认识活动具有激\n活、驱动作用。B错误。唯物辩证法本质上是批判的和革命的。马克思指出：“辩证法在对现存\n事物的肯定的理解中同时包含对现存事物的否定的理解，即对现存事物的必然灭亡的理解；辩\n证法对每一种既成的形式都是从不断的运动中，因而也是从它的暂时性方面去理解；辩证法不\n崇拜任何东西，按其本质来说，它是批判的和革命的。”正确。真理只能发展，而不可能被推\n翻。任何真理都标志着主观同客观的符合，都包含着不依赖于任何人的客观内容，都同谬误有\n原则的界限，都不可能被推翻。否则，就不是真理。这一点是绝对的、无条件的。相对主义片面\n夸大真理的相对性，否认真理的绝对性，从而导致错误做法，即借口真理是发展的而否认真理内\n容的客观性，认为原来的真理已经不是真理而将它丢弃或推翻。这就把真理的相对性歪曲成了\n主观随意性，由此走向主观真理论，陷人了不可知论和诡辩论。D错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-mayuan-18","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"国家垄断资本主义是国家政权和私人垄断资本融合在一起的垄断资本主义。第二次世界大战后，在所有发达资本主义国家，国家垄断资本主义无论在广度上还是深度上都有了更迅速、更普遍的发展。国家通过多种形式参与私人垄断资本的再生产过程是国家垄断资本主义的主要形式之一。国家通过多种形式参与私人垄断资本的再生产过程,其方式主要包括","options":[{"key":"A","text":"国家运用财政政策、货币政策等经济手段，对社会总供给和总需求进行调节"},{"key":"B","text":"国家向私人垄断企业大量订货，为私人垄断企业提供有保证的国家市场"},{"key":"C","text":"国家通过各种形式的津贴和补助，直接、间接地资助私人垄断企业"},{"key":"D","text":"国家通过社会福利开支扩大消费需求，为私人断企业创造市场条件"}],"answerKeys":["B","C","D"],"explanation":"国国家垄断资本主义的主要形式有五种。第一种是国家所有并直接经营企业。第二种是国\n家与私人共有、合营企业。第三种是国家通过多种形式参与私人垄断资本的再生产过程，包括\n国家作为商品和劳务的采购者，向私人垒断企业大量订货，为私人断企业提供有保证的国家\n市场；国家通过各种形式的津贴和补助，直接、间接地资助私人垄断企业；国家通过社会福利开\n支，提高社会购买力，扩大消费需求，为私人垄断企业创造市场条件。第四种是宏观调节，主要\n是国家运用财政政策、货币政策等经济手段，对社会总供给和总需求进行调节，以实现经济快速\n增长、充分就业、物价稳定和国际收支平衡的基本目标。第五种是微观规制。A项是宏观调节的\n内容，不属于题目所问的“国家通过多种形式参与私人垄断资本的再生产过程”的方式。正确答\n案是B、C、D。","tags":["肖四","第2套","多选题"]},
  {"id":"q-mayuan-19","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"第二次世界大战后，资本主义生产资料所有制发生了新的变化，法人资本所有制崛起并成为居主导地位的资本所有制形式。法人资本所有制","options":[{"key":"A","text":"主要存在于当代资本主义经济生活中居支配地位的巨型公司中"},{"key":"B","text":"主要特点是资本占有主体多元化，公司资本的所有权与控制权不再统一"},{"key":"C","text":"在性质上是一种基于资本雇佣劳动的垄断资本集体所有制"},{"key":"D","text":"体现了资本剥削雇佣劳动的关系"}],"answerKeys":["A","C","D"],"explanation":"A、C、D正确。法人资本所有制是法人股东化的产物，其主要特点是各类法人（企业法人\n和机构法人）取代个人或家族股东成为企业的主要出资人，企业的股票高度集中于少数法人股\n东之手，法人股东凭借手中集中化的控股权干预甚至直接参与公司治理，监督和制约管理阶层\n的经营行为，使公司资本的所有权与控制权重新趋于合一。B项描述的是私人股份资本所有制\n的特点,不选。","tags":["肖四","第2套","多选题"]},
  {"id":"q-mayuan-20","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到新经济政策。这一决定表明，列宁的社会主义建设思想发生了重大转变，对俄国这样一个小农经济占优势的国家如何走向社会主义又有了新的认识。新经济政策的主要内容有","options":[{"key":"A","text":"取消粮食税制以调动农民的积极性"},{"key":"B","text":"恢复商品货币关系，允许私人自由贸易"},{"key":"C","text":"允许私人小工业企业发展"},{"key":"D","text":"采取一些国家资本主义的形式来发展生产"}],"answerKeys":["B","C","D"],"explanation":"1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到实行以发展商品\n经济为主要特征的新经济政策。其主要内容有：用粮食税制取代余粮收集制，允许私人自由贸\n易，恢复商品货币关系，允许私人小工业企业发展，采取一些国家资本主义的形式来发展生产。\nB、C、D正确,A错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-mayuan-21","type":"material","module":"马克思主义基本原理","difficulty":3,"stem":"结合材料回答问题：（1）运用矛盾分析方法，说明“学习借鉴并非简单复制”。","material":{"title":"材料","paragraphs":["材料 1 今年以来，浙江杭州因为诞生了深度求索、游戏科学、宇树科技等“六小龙”走红网络，由此引发其他城市“怎样才能培养出‘六小龙””等追问。这样的追问很有现实意义。新质生产力本质是先进生产力，不争先就难领先，以其他城市的成绩为标尺找差距、补短板，激发“不输于人”的闯劲、“比学赶超”的拼劲，有利于激活创新创造的一池春水，积蓄高质量发展的后劲。学习借鉴并非简单复制。各地资源赋不同、基础条件各异，也不必纠结为何没在热门领域孵化竞争力强的企业。重要的是，学习借鉴优化政务服务、促进产业发展的先进经验，把握自身特色和优势，争取在更多细分领域锻造自己的长板。作为我国经济最活跃、开放程度最高、创新能力最强的区域之一，长三角发挥经济增长极和动力源作用，一个主要抓手就是一体化里协同联动，以错位发展发挥各地区比较优势，以合理分工提高资源配置效率。一体化不是同质化，须立足自身资源票赋，找准定位。比如，近年来江苏苏州以生物医药产业为战略重点，打造涵盖创新药、高端医疗器械、生物技术的生物医药集群，目前已集聚近4200家相关企业。又如，南京围绕传统优势钢铁产业做文章，打造高性能特种钢板生产基地，不断向价值链高处攀登，当地钢铁业100多个产品达到国际先进水平。无论处在传统产业还是置身新兴产业，只要找准自己的舞台、做大自已的优势，就有希望发展成为明星企业、打造明星产品。","摘编自《人民日报》（2025年","材料2 一个周末中午，到一家网红餐厅吃饭。还没走进饭馆，就看到门口全是等候就餐的人。一看排在200号以外，心想这次铁定吃不上了。没想到店员告知，也可以点个隔壁餐厅的菜，在隔壁店入座后再点本店的菜，这样不用排队。果然隔壁店员也欢迎这种“吃法”。“在一家餐厅吃两家饭”，由彼此“争抢客源”到互相“分享客源”，变直接竞争关系为合作共赢关系，成就“三赢”局面，引人思考。市场欢迎竞争，但竞争不能被窄化为“你取代我、我取代你”。当人们聚焦“能一起得到什么”而非“你会抢走我什么”时，竞争的攻防模式也就切换到了探索模式。重庆大足区与四川安岳县地理相连、气候相近，过去一段时间，两地稻虾、中药材等产业陷入同质化无序竞争。两地携手成立大安粮药合作园后，变对手为队友，变“抱团打架”为“抱团使劲”，产业规模扩大了、产值提高了、品牌擦亮了。从斗而俱损到合而两利，证明搭好平台、建好机制，能够促进共赢之路越走越宽。当前一些地方、行业和企业，之所以出现“内卷”现象，原因之一是固于思维局限，没有跳出自家的“一亩三分地”。在狭窄的视野里，“发展的蛋糕就那么大”、市场的需求有限，别人多吃一块，自然会担心自己少吃一块甚至吃不上，由此走上自我封闭、拒绝合作的歧路，导致封上别人的门、堵住自己的路。实际上，中国市场足够大，容得下亿万经营主体共生共赢、共同壮大；世界经济的海洋足够宽广，可任中外品牌千帆竞秀、百争流，关键在于思维和视野。","摘编自《人民日报》（2025年8月15日）"]},"answerPoints":["事物的矛盾、每一个矛盾的各个方面在发展的不同阶段上各有其特点。矛盾的特殊性决定了事物的不同性质。只有具体分析矛盾的特殊性，才能认清事物的本质和发展规律，并采取正确的方法和措施去解决矛盾，推动事物的发展。矛盾分析方法的核心要求是善于分析矛盾的特殊性，做到具体矛盾具体分析，对具体情况、具体问题作具体分析。","任何事物都是共性和个性的统一，在学习借鉴其他城市经验的同时也要充分考虑各地、各产业的实际情况和特殊性，做到因地制宜。(2)对立统一规律是唯物辩证法的实质和核心,它揭示了事物普遍联系的根本内容和变化发展的内在动力。经营主体之间存在着既相对立又相统一的关系。矛盾的同一性和斗争性相互联结、相辅相成，构成了事物的矛盾运动，推动着事物的变化发展。","矛盾的同一性在事物发展中具有重要作用,矛盾双方可以相互吸取有利于自身的因素，在相互作用中各自得到发展。辩证思维要求我们用联系、发展、全面的观点看问题，从对立中把握统一，从统一中把握对立。事物的发展不仅表现为“相反相成”，而且表现为“相辅相成”，经营主体之间可以互相吸取对方的优点，在竞争中合作，在合作中竞争，以“共赢\"取代“内卷”。"],"explanation":"事物的矛盾、每一个矛盾的各个方面在发展的不同阶段上各有其特点。矛盾的特殊性决定了事\n物的不同性质。只有具体分析矛盾的特殊性，才能认清事物的本质和发展规律，并采取正确的\n方法和措施去解决矛盾，推动事物的发展。\n矛盾分析方法的核心要求是善于分析矛盾的特殊性，做到具体矛盾具体分析，对具体情况、\n具体问题作具体分析。任何事物都是共性和个性的统一，在学习借鉴其他城市经验的同时也要\n充分考虑各地、各产业的实际情况和特殊性，做到因地制宜。\n(2)对立统一规律是唯物辩证法的实质和核心,它揭示了事物普遍联系的根本内容和变化\n发展的内在动力。经营主体之间存在着既相对立又相统一的关系。矛盾的同一性和斗争性相\n互联结、相辅相成，构成了事物的矛盾运动，推动着事物的变化发展。矛盾的同一性在事物发展\n中具有重要作用,矛盾双方可以相互吸取有利于自身的因素，在相互作用中各自得到发展。\n辩证思维要求我们用联系、发展、全面的观点看问题，从对立中把握统一，从统一中把握对\n立。事物的发展不仅表现为“相反相成”，而且表现为“相辅相成”，经营主体之间可以互相吸取\n对方的优点，在竞争中合作，在合作中竞争，以“共赢\"取代“内卷”。","tags":["肖四","第2套","材料分析题"]},
  {"id":"q-mayuan-22","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"马克思、恩格斯以前的中外哲学都使用过实践的概念。一些思想家对实践也有过不少论述，但他们都没有真正理解人类实践的本质，没有看到实践在社会生活和认识活动中的决定意义。马克思在他的著作中系统论述了实践的观点，揭示了科学实践观的基本内容。这个被称为“包含新世界观天才萌芽的第一个文件”的著作是","options":[{"key":"A","text":"《德意志意识形态》"},{"key":"B","text":"《反杜林论》"},{"key":"C","text":"《关于费尔巴哈的提纲》"},{"key":"D","text":"《路德维希·费尔巴哈和德国古典哲学的终结》"}],"answerKey":"C","explanation":"在《关于费尔巴哈的提纲》这个包含新世界观天才萌芽的第一个文件中,马克思系统论述了\n实践的观点,揭示了科学实践观的基本内容。正确。马克思、恩格斯合写了《德意志意识形\n态》，首次系统阐述了历史唯物主义的基本观点。1876—1878年，恩格斯写出了《反杜林论》，全面\n阐述了马克思主义理论体系。马克思逝世后，恩格斯承担起指导国际工人运动的重任，并整理出\n版了《资本论》第二、三卷，写出了《家庭、私有制和国家的起源》《路德维希·费尔巴哈和德国古典\n哲学的终结》等著作,进一步发展了马克思主义理论。A、B、D错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-mayuan-23","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"马克思主义政治经济学的理论十分丰富，其中“理解政治经济学的枢纽”的理论是","options":[{"key":"A","text":"资本有机构成理论"},{"key":"B","text":"商品二因素理论"},{"key":"C","text":"劳动二重性理论"},{"key":"D","text":"剩余价值理论"}],"answerKey":"C","explanation":"马克思在继承英国古典政治经济学劳动创造价值理论的同时，创立了劳动二重性理论，第\n一次确定了什么样的劳动形成价值、为什么形成价值以及怎样形成价值，阐明了具体劳动和抽象\n劳动在商品价值形成中的不同作用，从而为揭示剩余价值的真正来源、创立剩余价值理论奠定了\n基础。此外，马克思的资本有机构成理论、资本积累理论、社会资本再生产理论等政治经济学的\n一系列重要理论的创立也都同劳动二重性理论有关。因此，劳动二重性理论成为“理解政治经济\n学的枢纽”。C正确。","tags":["肖四","第3套","单选题"]},
  {"id":"q-mayuan-24","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"第二次世界大战以后，资本主义国家经历了第三次科学技术革命，电子计算机、数控机床等自动化装置在生产中得到比较普遍的应用，机器大工业发展到自动化阶段。工业机器人的开发和利用，代替了工人大量的体力劳动和部分脑力劳动。它的普遍采用大幅提高了劳动生产率，使直接从事生产操作的工人大大减少。这意味着率先使用工业机器人的个别企业","options":[{"key":"A","text":"获得更多的社会平均利润"},{"key":"B","text":"对可变资本投人的增加"},{"key":"C","text":"所生产商品价值的提高"},{"key":"D","text":"资本技术构成的提高"}],"answerKey":"D","explanation":"在生产资料和劳动力之间,存在着一定比例，这个比例取决于生产技术的发展水平。生产\n技术水平越高，每个劳动力所推动的生产资料的数量就越多；生产技术水平越低，每个劳动力所\n推动的生产资料的数量就越少。这种由生产的技术水平所决定的生产资料和劳动力之间的比\n例，叫作资本的技术构成。使用工业机器人意味着工人数量（也就是劳动力）的减少，会导致生产\n资料与劳动力之间的比例提高，即资本技术构成提高。D正确。可变资本是用来购买劳动力的那\n部分资本,工人数量的减少意味着可变资本的减少。B错误。率先提高劳动生产率的企业,其生\n产的商品的个别劳动时间少于社会必要劳动时间，个别价值低于社会价值,从而获得超额剩余价\n值。C错误。率先提高劳动生产率的企业可获得更多的超额利润，而不是社会平均利润。A错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-mayuan-25","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"如何发掘、研究化石，是古生物学研究的重要课题。一块块化石诉说着地球的演变，承载着远古的奥秘。过去，挖化石如同“拆盲盒”。如今，在新技术的助力下，古生物学研究正加速破解更多生命密码。你能想象吗？一块大小不到4平方厘米的琥珀，能揭示一个热带海岸森林的滨海环境。研究人员利用CT扫描技术，重建白垩纪中期一块缅甸克钦琥珀中各类化石的三维图像。他们发现，这枚琥珀保存了异常丰富的化石类群，包括1个菊石、4个螺类、4个等足虫、23个螨虫、1个蜘蛛、1个马陆和至少12个昆虫，以及一些砂粒、植物碎屑。这为揭示周围4平方公里乃至40平方公里的森林生态提供了重要证据。借助新技术，从一块琥珀，可以“看见”一片热带森林，这说明人的认识能力","options":[{"key":"A","text":"以人的感觉器官生理阅限为界限"},{"key":"B","text":"是无限性和有限性的统一"},{"key":"C","text":"可以通过实践得到锻炼和提高"},{"key":"D","text":"随着时代的发展而发展"}],"answerKeys":["B","C","D"],"explanation":"人类的思维按其本性、使命、可能和历史的终极目的来说，是能够认识无限发展着的物质\n世界的,思维是无限的和绝对的。但是,具体到每一个人乃至每一代人，由于受到客观事物及其\n本质的显露程度、社会历史的实践水平、主观的条件以及生命的有限性等各方面的限制甘且维\nB、D正确。实践是认识发展的动力。实践为认识的发展提供了手段和条件，如经验资料、实验\n仪器和工具等。实践改造了人的主观世界，锻炼和提高了人的认识能力。人们正是在实践的推\n动下，不断打破认识上的旧框框，突破头脑中的旧思想，实现认识上的新飞跃，从而不断有所发\n现、有所前进。正确。人可以利用认识工具来延长和放大自已的感官，从而突破人的感官的选\n择阈限。因此，人的感觉器官的生理阈限并不是人的认识能力的界限。A错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-mayuan-26","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"资本是在运动中增殖的，必须不断地、周而复始地循环，才能不断地带来剩余价值。这种周而复始、不断反复着的资本循环,就叫作资本的周转。影响资本周转快慢的因素有许多,关键的因素有","options":[{"key":"A","text":"资本周转的时间"},{"key":"B","text":"所用资本和所费资本之间的差额"},{"key":"C","text":"生产资本的固定资本和流动资本的构成"},{"key":"D","text":"资本家预付资本的大小"}],"answerKeys":["A","C"],"explanation":"影响资本周转快慢的因素有许多,关键的因素有两个：一是资本周转的时间,二是生产资\n本的固定资本和流动资本的构成。要加快资本周转速度，获得更多剩余价值，就要缩短资本周\n转时间，加快流动资本的周转速度。A、C正确。资本积累规模的大小取决于资本家对工人的剥\n前程度、劳动生产率的高低、所用资本和所费资本之间的差额以及资本家预付资本的大小。B、D\n不符合题意。","tags":["肖四","第3套","多选题"]},
  {"id":"q-mayuan-27","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"进入21世纪以来,资本主义呈现出一些新变化、新特征。国际金融垄断资本主义影响日益显现，国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征，这表现在","options":[{"key":"A","text":"金融垄断寡头化"},{"key":"B","text":"金融垄断国际化"},{"key":"C","text":"金融垄断政治化"},{"key":"D","text":"经济虚拟化、产业空心化"}],"answerKeys":["A","B","D"],"explanation":"国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征。一是金融断寡\n头化。二是金融垄断国际化。三是经济虚拟化、产业空心化。A、B、D正确。","tags":["肖四","第3套","多选题"]},
  {"id":"q-mayuan-28","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"马克思、恩格斯关于未来社会的预测,是在科学地批判和剖析资本主义社会的过程中作出的。马克思、恩格斯对资本主义批判的高明之处在于","options":[{"key":"A","text":"不是只看到资本主义社会的弊端，而是进一步揭示出弊端的根源和资本主义发展中自我否定的力量"},{"key":"B","text":"发现资本主义的矛盾运动中孕育着的新社会因素，并以此对未来社会特点作出预见"},{"key":"C","text":"既从资本主义社会中寻找灵感，更从社会主义社会的建设与发展中寻找启示"},{"key":"D","text":"先指出未来社会的一般特征，再对各种细节作具体描绘"}],"answerKeys":["A","B"],"explanation":"从历史上看，人们对未来社会的设想，往往源于对现实问题的思考与批判。马克思、恩格\n斯对资本主义批判的高明之处在于，他们不是只看到资本主义社会的弊端，而是进一步揭示出\n弊端的根源，揭示出资本主义发展中自我否定的力量，发现资本主义的矛盾运动中孕育着的新\n社会因素,并以此对未来社会特点作出预见。A、B正确。列宁领导了十月革命，建立起世界上\n第一个社会主义国家并探索了在俄国建设社会主义的道路，取得了预见未来社会的实践经验。\n他将社会主义社会与共产主义社会作了区分，这本身就是对共产主义社会的新认识。马克思、\n恩格斯的时代还没有出现社会主义社会，C错误。马克思主义经典作家立足于揭示未来社会的\n一般特征，而不对各种细节作具体描绘。马克思、恩格斯在展望未来社会时，总是只限于指出未\n来社会发展的方向、原则和基本特征，而把具体情形留给后来的实践去回答。D错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-mayuan-29","type":"material","module":"马克思主义基本原理","difficulty":3,"stem":"结合材料回答问题：（1）通过种养结合的“借收”模式可以将草畜矛盾和秸秆处置两个难题一起解决，分析其中所蕴含的唯物辩证法原理。（2）“借牧”模式对我们用创新思维处理人与自然的关系有何启示？","material":{"title":"材料","paragraphs":["近期，随着天气回暖，位于甘肃、青海交界处的祁连山草原迎来一场盛大的“返乡潮”。这些年，每到10月，这一带的牧民就将牛羊赶到周边农区，租借收完作物的秸秆地用于接羔育肥，第二年3月再返回高山草原。看上去颇费周折，其实这是一笔多赢的买卖。牧民为冬季的牛羊找到了稳定的饲料供应地；农户挣了笔租地款，还节省了秸秆处理费。草原上的植被也获得休养生息的机会，生态效益显著。草畜矛盾，秸秆处置，放到一时一地，可能都是不太容易解决的问题。但通过“借牧”这一经营模式的创新，实现种养结合，两方面的问题都迎刃而解。这启示我们，更好解决农业农村发展面临的各种矛盾和问题，要放宽视野，大胆创新，促进要素资源在更大范围内顺畅流动和高效配置，不断提高农业创新力、竞争力、全要素生产率。","摘编自《人民日报》（2025年4月30日）"]},"answerPoints":["体事物存在,又作为联系中的事物存在。联系具有普遍性。任何事物都不能孤立存在，都同其他事物处于一定的联系之中。整个世界是相互联系的统一整体。联系具有条件性。在尊重客观规律的前提下，人可以改变和创造条件，推动事物向着有利的方向发展。","创新思维能力是对常规思维的突破，是破除迷信，超越陈规，善于因时制宜、知难而进、开拓创新的能力。创新思维能力意味着不墨守成规，在求新、求变中创造性地提出问题和解决问题。“借牧”模式的创新之处就在于，人们能够敏锐地发现事物固有的联系，并能动地建立新的联系，进而利用这种联系来促进事物的良性发展。","自然地理环境是人类社会生存和发展永恒的、必要的条件，是人们生活和生产的自然基础。自然生态平衡对社会生活起着重要作用。合理地利用自然资源，保护生态平衡，是社会得以正常发展的必要条件。人类在实践活动中按照自己的意愿改造世界的同时必须遵循自然规律，否则将会导致人与自然关系的失衡。","马克思认为，应当合理地调节人与自然之间的物质变换，在最无愧于和最适合人类本性的条件下进行这种物质变换。"],"explanation":"体事物存在,又作为联系中的事物存在。联系具有普遍性。任何事物都不能孤立存在，都同其\n他事物处于一定的联系之中。整个世界是相互联系的统一整体。联系具有条件性。在尊重客\n观规律的前提下，人可以改变和创造条件，推动事物向着有利的方向发展。\n（2）创新思维能力是对常规思维的突破，是破除迷信，超越陈规，善于因时制宜、知难而进、\n开拓创新的能力。创新思维能力意味着不墨守成规，在求新、求变中创造性地提出问题和解决\n问题。“借牧”模式的创新之处就在于，人们能够敏锐地发现事物固有的联系，并能动地建立新\n的联系，进而利用这种联系来促进事物的良性发展。\n自然地理环境是人类社会生存和发展永恒的、必要的条件，是人们生活和生产的自然基础。\n自然生态平衡对社会生活起着重要作用。合理地利用自然资源，保护生态平衡，是社会得以正\n常发展的必要条件。人类在实践活动中按照自己的意愿改造世界的同时必须遵循自然规律，否\n则将会导致人与自然关系的失衡。马克思认为，应当合理地调节人与自然之间的物质变换，在\n最无愧于和最适合人类本性的条件下进行这种物质变换。","tags":["肖四","第3套","材料分析题"]},
  {"id":"q-mayuan-30","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"“10万个小时成就一个好医生”，这句医学领域被广泛认同的话，在人工智能强大的学习能力面前已经不再绝对。在影像科室，基于深度学习算法，人工智能阅片技术通过大量医学图像数据训练,已具备识别、分析、诊断病灶的能力,大大提升了诊断效率。比如，上海瑞金医院“胸部肺结节CT辅助诊断应用”已广泛覆盖超过80%的病例，将原本7分钟的诊断时间缩短至2分钟；冠状动脉CT血管成像辅助诊断的应用将诊断时间从25分钟缩短至3分钟。人工智能在医疗等领域取得的突破性成就说明","options":[{"key":"A","text":"人工智能作为一种新的实践主体，能够独立推动认识发展"},{"key":"B","text":"人类意识中的所有内容都可以被化约为数字信号"},{"key":"C","text":"人工智能已经超越人类智能的层级，可以代替人们做出决策"},{"key":"D","text":"人工智能不仅可以模拟，而且能够扩展人脑的某些活动"}],"answerKey":"D","explanation":"人工智能可以模拟和扩展人脑的某些活动，甚至在计算速度和准确度、程序化任务的执行\n能力等方面的表现超出人类所能。D正确。实践的主体只能是人，人工智能是人类创造和使用的\n工具。认识的深化和发展，归根结底依赖于人类的实践活动。A错误。人工智能能够获得人类意\n识中可以化约为数字信号的内容，但人脑中总有许多东西是无法被化约的。B错误。尽管人工智\n能可以模拟和扩展人脑的某些活动，但即使是计算能力最强大、最先进的智能机器，也达不到人\n类智能的层级，无法真正具有人的意识，不可能取代或超越人类智能。人工智能可以辅助人们决\n策，但无法代替人们以知情意统一为基础的整体决策。C错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-mayuan-31","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"商品经济的发展经历了简单商品经济与发达商品经济两个阶段，资本主义商品经济是商品经济的高级或发达形态。简单商品生产发展到资本主义商品生产的新阶段的标志是","options":[{"key":"A","text":"劳动力成为商品"},{"key":"B","text":"社会分工的出现"},{"key":"C","text":"生产资料和劳动产品属于不同的所有者"},{"key":"D","text":"机器大工业代替工场手工业"}],"answerKey":"A","explanation":"劳动力成为商品,标志着简单商品生产发展到资本主义商品生产的新阶段。在这一阶段，\n资本家与工人的关系,形式上是“自由”“平等”的买卖关系,而实质上是资本家支配和剥削工人的\n雇佣劳动关系。A正确。","tags":["肖四","第4套","单选题"]},
  {"id":"q-mayuan-32","type":"choice","module":"马克思主义基本原理","difficulty":1,"stem":"进人21世纪以来，随着经济全球化的深人发展，新一轮科技革命和产业变革进人空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义呈现出一些新变化、新特征。当代资本主义最突出、最鲜明、最主要的特征是","options":[{"key":"A","text":"社会阶级层级结构呈现复杂性、多样化"},{"key":"B","text":"科技创新加速资本主义生产方式变化"},{"key":"C","text":"国际金融资本的垒断"},{"key":"D","text":"发达资本主义国家在世界范围内推行权主义和强权政治"}],"answerKey":"C","explanation":"资本主义生产方式新变化在有效降低信息获取、资源匹配和商品交换成本，有力推动物质\n财富的创造和积累的同时，也推动资本积累方式从一般产业资本积累向国际金融垄断资本积累\n转变，国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征。C工","tags":["肖四","第4套","单选题"]},
  {"id":"q-mayuan-33","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"习近平强调，“有所为是发展,有所不为也是发展”。在上海闵行区,有一片“城市荒野”。与小区花坛、公园绿地、街巷林荫道的整齐划一不同，这里1.7万平方米空间自然错落，300多种植物、80多种鸟类、超过500种昆虫自然生长。如果说，过去开发土地、改造环境是一种积极的“有为”，那么如今注重城市留白、重建“荒野”则是充分尊重和顺应自然规律，依靠自然的力量恢复生态系统平衡，这是一种主动的“不为”。城市发展逻辑中“有为”与“不为”的辩证理念带给我们的哲学启示有","options":[{"key":"A","text":"保护生态平衡是社会得以正常发展的必要条件"},{"key":"B","text":"人类只能适应自然环境变化而不能改变自然环境"},{"key":"C","text":"人类已经成为自然界的自觉的和真正的主人"},{"key":"D","text":"保护自然生态与满足人的发展需要不是根本对立的"}],"answerKeys":["A","D"],"explanation":"合理地利用自然资源，保护生态平衡，是社会得以正常发展的必要条件。A正确。人与自\n然可以和谐共生，保护自然生态与满足人的发展需要不是根本对立的。绿水青山就是金山银山\n理念摒弃了经济发展与生态环境保护非此即彼的形而上学思维方式，深刻揭示了二者内在统一\n的辩证关系，打破了经济发展与生态环境保护相对立的思维定势，确立了人与自然和谐共生的\n发展观。D正确。人在自然面前不是被动的、无能为力的,而是能动的、积极的。B.错误。共产\n主义社会实现了人类解放，人类将最终从支配他们生活和命运的异已力量中解放出来，实现从\n必然王国向自由王国的飞跃，开始自觉地创造自己的历史。只有到那个时候，人们才第一次成\n为自然界的自觉的和真正的主人。C错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-mayuan-34","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"曾经有人问，为什么要花大代价发展航天事业？一个绝佳的回答是，航天看似在引领我们远离地球,实际上却将地球变得更加美好,不仅仅因为前沿技术的发展能够反哺生活,还因为我们对地球、对生命、对自身的理解在不断深化。广衰的宇宙不会让勇敢的探索者失望，答案或许就在下一次发射、下一串信号中。以上材料说明","options":[{"key":"A","text":"探索活动就是不断发现和解决矛盾的过程"},{"key":"B","text":"探索的每一次突破都是对无限发展着的物质世界的接近"},{"key":"C","text":"对于探索活动的评价结果没有正确与错误之分"},{"key":"D","text":"探索未知世界的科学实验是人类最基本的实践活动"}],"answerKeys":["A","B"],"explanation":"矛盾无处不在，矛盾无时不有。人们就是在应对挑战和解决矛盾中推动社会发展的。A\n正确。人类认识按其本性来说，能够正确认识无限发展着的物质世界，认识每前进一步，都是对\n无限发展着的物质世界的接近，这一点是绝对的、无条件的。B正确。评价结果有正确与错误之\n分，价值评价也有科学与非科学之别。科学的评价是客观公正、全面有效的评价。相反，非科学\n的评价是歪曲、遮蔽客观的价值关系的评价。C错误。物质生产实践是人类最基本的实践活动。\nD错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-mayuan-35","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"使用价值不同的商品之所以能按一定比例相交换，是因为它们都具有价值。商品的价值在质上是相同的，因而可以相互比较。商品的价值是劳动创造的，其实质是凝结在商品中的无差别的一般人类劳动。由此可见","options":[{"key":"A","text":"劳动是一切社会财富的唯一源泉"},{"key":"B","text":"使用价值寓于价值之中并通过价值表现出来"},{"key":"C","text":"商品交换实际上是商品生产者之间相互交换劳动的关系"},{"key":"D","text":"商品的价值在本质上体现了生产者之间一定的社会关系"}],"answerKeys":["C","D"],"explanation":"C、D正确。劳动是财富的源泉之一，但不是唯一源泉。财富或者说使用价值的生产，除了\n劳动者外，还必须有劳动对象和劳动资料。A错误。使用价值是价值的物质承担者，价值寓于使\n用价值之中。价值是交换价值的基础，交换价值是价值的表现形式。B错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-mayuan-36","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"垒断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。垄断资本向世界范围扩展的主要经济动因是","options":[{"key":"A","text":"将国内过剩的资本输出，以便在国外谋求高额利润"},{"key":"B","text":"输出资本主义的意识形态，以颠覆或控制发展中国家的政权"},{"key":"C","text":"争夺商品销售市场，确保原材料和能源的可靠来源"},{"key":"D","text":"将部分非要害的技术转移到国外，以取得在别国的断优势"}],"answerKeys":["A","C","D"],"explanation":"垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统\n治。垄断资本向世界范围扩展的主要经济动因包括：（1)将国内过剩的资本输出，以便在国外谋\n求高额利润；(2)将部分非要害的技术转移到国外，以取得在别国的垒断优势，取高额垒断利\n润；（3）争夺商品销售市场；（4)确保原材料和能源的可靠来源。这些经济上的动因与垄断资本\n主义在政治上、文化上、外交上的利益紧密联系在一起，交织发挥作用，共同促进了断资本向\n世界范围的扩展。A、C、D正确。B错误。\n2026米考研政治终极预测4套卷（四）答案及解析","tags":["肖四","第4套","多选题"]},
  {"id":"q-mayuan-37","type":"multi","module":"马克思主义基本原理","difficulty":2,"stem":"100多年前的1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到实行以发展商品经济为主要特征的新经济政策。俄共（布）十大决定实行新经济政策，是因为","options":[{"key":"A","text":"国家从战争转人和平经济建设时期，战时共产主义政策无法调动生产者尤其是"},{"key":"B","text":"国民经济已濒临崩溃，国内发生严重的经济和政治危机"},{"key":"C","text":"如不改变政策，执政党将会失去广大群众，丢掉阶级基础"},{"key":"D","text":"需要为实行农业集体化摸索经验"}],"answerKeys":["A","B","C"],"explanation":"1920年底，苏维埃俄国击退外国武装干涉者，取得了国内战争的胜利，1921年初转人和平\n经济建设时期。这时，国民经济已濒临崩溃，国内发生严重的经济和政治危机，再实行以余粮收\n集制和取消商品货币关系为主要特征的战时共产主义政策，无法调动生产者尤其是农民的积极\n性。在这种形势下,列宁深感如不改变政策将会失去广大群众,丢掉阶级基础。A、B、C正确。\n实行以发展商品经济为主要特征的新经济政策，与后来实行农业集体化没有关系，更谈不上摸\n索经验。D错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-mayuan-38","type":"material","module":"马克思主义基本原理","difficulty":3,"stem":"结合材料回答问题：（1）分析“不唯上、不唯书、只唯实”这一论断所蕴含的哲学原理。（2）“地瓜经济”理论启示我们“跳出自身、着眼全局、从更大视野谋划发展思路”“突破思维局限，从更高的维度、更长的周期来看自身、看当下”，这体现了怎样的思维能力？","material":{"title":"材料","paragraphs":["材料1 我们要学习陈云同志的科学思想方法和工作方法。坚持实事求是，是陈云同志的鲜明特点。他指出：“要把我们的党和国家领导好，最要紧的，是要使领导干部的思想方法搞对头。”他提炼出“不唯上、不唯书、只唯实，交换、比较、反复”这一充满唯物辩证法的“十五字诀”。他善于从战略上思考问题，强调：“应该站得高一点，看得远一点，要上屋顶，不要老呆在地下室。”“要拿出一定时间跛方步，，考虑战略性的问题。”他把调查研究作为决策的重要前提，强调：“领导机关制定政策，要用百分之九十以上的时间作调查研究工作。”","摘自习近平《在纪念陈云同志诞辰120周年座谈会上的讲话》","材料2 正值炎热署期，吉林长白山的山地旅游成功“破圈”，与冰雪季拥有同样的热度。再细细观察，今天很多滑雪场转变思路，摆脱了季节“魔咒”。同一片山坡，冬日可以滑雪，夏日则能观景；同一架缆车，雪季运送滑雪者，暖季变身观光线。当发展的视野不再局限于单一冰雪资源，而是顺应消费需求，创新供给，那么资源“闲置期”就转化为了发展“机遇期”。从“一季养四季”到“四季皆旺季”，正是以认知升维实现资源再利用、打开发展新思路的一个生动体现。换一个看待事物的方式，就可能会发现资源排列组合的新形式、生产要素之间的新配置，从而产生新的发展思路、找到新的发展路径。习近平总书记在浙江工作时科学阐释“地瓜经济”理论，深刻指出“必须跳出浙江发展浙江，在大力引进各种要素的同时打到省外去、国外去，利用外部资源、外部市场实现更大的发展”。以认知升维打开发展思路，正是一个跳出自身、着眼全局、从更大视野谋划发展思路的过程。比如，风光电让西北戈壁滩成了优质发电场所，数字经济发展让西南山区变身数据中心，战略思维、大局意识让我们可以重新认识自己的长板与短板，进而实现由短变长的蝶变。局限我们发展的，不只是客观条件，更是主观思维。突破思维局限，从更高的维度、更长的周期来看自身、看当下，从而更迅速地捕捉变化、更敏锐地发现趋势，我们定能在时代浪潮中找到破局之道、发展良方，为中国经济高质量发展打开新空间。","摘编自《人民日报》（2025年8月18日）"]},"answerPoints":["一切从实际出发是马克思主义认识论的根本要求和具体体现。从实际出发，就是要从变化发展着的客观实际出发，从特定的社会历史条件出发，按照客观世界的本来面目认识世界而不附加任何外来的主观成分。从根本上说，就是要从客观事物存在和发展的规律出发，在实践中按照客观规律办事。实践决定认识，实践是认识的来源、动力、目的和检验认识真理性的唯一标准。","真理只能通过实践来检验和发展。任何真理都是绝对性和相对性的统一。如果片面夸大真理的绝对性，否认真理的相对性，认为真理是永恒不变的，把书本上的知识当作一成不变的公式，到处生搬硬套，在实际工作中就会犯教条主义、思想侮化的错误。（注：还可以从实践与认识的辩证运动角度进行分析，客观实践是具体的、历史的，客观实践变化了，主观认识也应当随之转变）","“跳出自身、着眼全局”“从更高的维度、更长的周期来看自身、看当下”体现了辩证思维能力、系统思维能力和战略思维能力。辩证思维是在分析和解决问题时贯彻运用唯物辩证法的基本观点和方法。提高辩证思维能力，要求我们联系地而不是孤立地、发展地而不是静止地、全面地而不是片面地、系统地而不是零散地观察事物。系统思维能力是全面系统地分析和处理问题的能力。","坚持系统观念，提高系统思维能力，要把握好全局与局部、当前与长远的关系，加强前瞻性思考、全局性谋划、战略性布局和整体性推进。战略思维能力强调思维的整体性、全局性、长期性，是高瞻远瞩、统揽全局、善于把握事物发展总体趋势和方向的能力。培养和提高战略思维能力，要求我们不断开阔视野，学会站在战略和全局的高度观察和处理问题。"],"explanation":"一切从实际出发是马克思主义认识论的根本要求和具体体现。从实际出发，就是要从变化发展\n着的客观实际出发，从特定的社会历史条件出发，按照客观世界的本来面目认识世界而不附加\n任何外来的主观成分。从根本上说，就是要从客观事物存在和发展的规律出发，在实践中按照\n客观规律办事。\n实践决定认识，实践是认识的来源、动力、目的和检验认识真理性的唯一标准。真理只能通\n过实践来检验和发展。任何真理都是绝对性和相对性的统一。如果片面夸大真理的绝对性，否\n认真理的相对性，认为真理是永恒不变的，把书本上的知识当作一成不变的公式，到处生搬硬\n套，在实际工作中就会犯教条主义、思想侮化的错误。\n（注：还可以从实践与认识的辩证运动角度进行分析，客观实践是具体的、历史的，客观\n实践变化了，主观认识也应当随之转变）\n（2）“跳出自身、着眼全局”“从更高的维度、更长的周期来看自身、看当下”体现了辩证思维\n能力、系统思维能力和战略思维能力。辩证思维是在分析和解决问题时贯彻运用唯物辩证法的\n基本观点和方法。提高辩证思维能力，要求我们联系地而不是孤立地、发展地而不是静止地、全\n面地而不是片面地、系统地而不是零散地观察事物。系统思维能力是全面系统地分析和处理问\n题的能力。坚持系统观念，提高系统思维能力，要把握好全局与局部、当前与长远的关系，加强\n前瞻性思考、全局性谋划、战略性布局和整体性推进。战略思维能力强调思维的整体性、全局\n性、长期性，是高瞻远瞩、统揽全局、善于把握事物发展总体趋势和方向的能力。培养和提高战\n略思维能力，要求我们不断开阔视野，学会站在战略和全局的高度观察和处理问题。","tags":["肖四","第4套","材料分析题"]},
  {"id":"q-mayuan-39","type":"material","module":"马克思主义基本原理","difficulty":3,"stem":"结合材料回答问题：（1）为什么既要坚定弘扬全人类共同价值，又要尊重文明多样性？（2）为什么说“中国堪称当今世界推动贸易和投资自由化便利化的最大旗手”？","material":{"title":"材料","paragraphs":["材料1 第八十届联合国大会一般性辩论正在纽约联合国总部举行。本届联大以“携手共进：促和平、发展、人权八十载，继往开来，再谱新篇”为主题，在联合国成立80周年的历史节点，再次凸显各国人民对和平发展的般切期盼、对公平正义的强烈呼声和对民主自由的坚定追求。“和平、发展、公平、正义、民主、自由，是全人类的共同价值，也是联合国的崇高目标。”2015年9月28日，习近平主席出席第七十届联合国大会一般性辩论并发表重要讲话，首次提出全人类共同价值并阐释其基本内涵。此后，习近平主席多次强调要弘扬全人类共同价值，并国绕全人类共同价值提出一系列新理念、新主张，为推动构建人类命运共同体、创造人类更加美好的未来提供了强大思想引领。10年来，这一源自中国的重要理念，以其跨越国界、超越分歧的强大感召力，凝聚了世界各国人民普遍认同的价值理念的最大公约数。立天下之正位，行天下之大道。中国始终以人类前途为怀、以人民福让为念，愿同各方一道，坚定弘扬全人类共同价值，共同朝着构建人类命运共同体的崇高目标勇毅前行。","摘编自《人民日报》（2025","材料2 在各国命运休成与共的“地球村”时代，不同文明之间平等交流、互学互鉴，才能为人类破解时代难题、实现共同发展提供强大的精神指引。近年来，世界中文大会、世界中国学大会、世界汉学家大会等对话平台的吸引力、影响力不断扩大，日益成为中外语言互通之桥、理解互信之桥、文明互鉴之桥。展望未来，中国将一如既往践行平等、互鉴、对话、包容的文明观，为不同文明交流互鉴搭建平台、注入动能。溯历史的源头才能理解现实的世界，循文化的根基才能辨识当今的中国，有文明的互鉴才能实现共同的进步。期待更多国际学者与汉学结伴、和中国同行，践行全球文明倡侣议，推动各国相互理解、相互尊重、相互信任，携手促进人类文明进步。","摘编自《人民日报》（2025年11月14日）","材料3 5月12日，中美日内瓦经贸会谈联合声明发布，双方承诺在采取相关举措后，将建立机制，继续就经贸关系进行协商。5月14日，美方取消了共计91%的加征关税，中方相应取消了91%的反制关税；美方暂停实施24%的“对等关税”，中方也相应暂停实施24%的反制关税。“坦诚、深入、具有建设性”“取得实质性进展”，中美日内瓦经贸会谈达成重要共识，国际社会高度关注。世界贸易组织总千事伊维拉发表声明称，在当前全球紧张的局势下，这一进展不仅对中美两国非常重要，而且对世界其他国家，包括最脆弱的经济体，也至关重要。习近平总书记指出，“要坚定不移办好自己的事，坚定不移扩大高水平对外开放”。国际社会认为，中国堪称当今世界推动贸易和投资自由化便利化的最大旗手，是动荡世界中的稳定力量。外国政要表示：“在单边主义引发世界局势动荡、多边贸易体系受到冲击的形势下，中国发挥了领导作用，为世界提供了宝贵的稳定性。”","摘编自《人民日报》（2025年5月16日）"]},"answerPoints":["发展水平不尽相同，但和平发展是共同事业，公平正义是共同理想，民主自由是共同追求。当前，世界进入新的动荡变革期，全球性挑战层出不穷。化解人类面临的全球性矛盾和问题，既需要物质力量的根本作用，又需要价值力量的精神引领。","和平与发展是打破冲突对抗、走出安全困境的唯一出路，公平与正义是弥合发展鸿沟、维护全球南方权益的必然要求，民主与自由是推动文明互鉴、保障平等发展的价值前提。只有坚定弘扬全人类共同价值，才能为破解人类社会的现实困境提供坚强有力的价值支撑，更好汇聚应对全球挑战的磅力量，共同朝着构建人类命运共同体的崇高目标勇毅前行。","坚定弘扬全人类共同价值，与尊重文明多样性是并行不悖的。文明多样性是人类社会发展的客观现实，也是人类进步的不竭动力。文明因多样而交流，因交流而互鉴，因互鉴而发展。不同文明之间平等交流、互学互鉴，才能为人类破解时代难题、实现共同发展提供强大的精神指引。（2)历史和现实表明，自由贸易是推动经济全球化和全球发展的重要动力，是大势所趋、人心所向。","坚定践行自由贸易理念，坚决维护多边贸易体制，才能为全球发展注入确定性和稳定性。第一，中国坚定维护多边贸易体制。在单边主义引发世界局势动荡、多边贸易体系受到冲击的形势下，中国发挥了领导作用，坚定支持以世界贸易组织为核心的多边贸易体系，坚决反对贸易保护主义或贸易战，为世界提供了宝贵的稳定性。第二，中国坚定维护全球产业链供应链稳定。","坚持“拉手”而不是“松手”、“延链”而不是“断链”，积极寻找更多利益契合点，支持供应链开放发展。第三，中国坚定维护开放合作的国际环境。加快推进自由贸易试验区、海南自由贸易港建设，实行更加积极主动的开放战略，稳步扩大制度型开放，建设更高水平开放型经济新体制，以实际行动支持多边贸易体制、推动发展自由贸易。20266考研政治终极预测4套卷"],"explanation":"发展水平不尽相同，但和平发展是共同事业，公平正义是共同理想，民主自由是共同追求。当\n前，世界进入新的动荡变革期，全球性挑战层出不穷。化解人类面临的全球性矛盾和问题，既需\n要物质力量的根本作用，又需要价值力量的精神引领。和平与发展是打破冲突对抗、走出安全\n困境的唯一出路，公平与正义是弥合发展鸿沟、维护全球南方权益的必然要求，民主与自由是推\n动文明互鉴、保障平等发展的价值前提。只有坚定弘扬全人类共同价值，才能为破解人类社会\n的现实困境提供坚强有力的价值支撑，更好汇聚应对全球挑战的磅力量，共同朝着构建人类\n命运共同体的崇高目标勇毅前行。\n坚定弘扬全人类共同价值，与尊重文明多样性是并行不悖的。文明多样性是人类社会发展\n的客观现实，也是人类进步的不竭动力。文明因多样而交流，因交流而互鉴，因互鉴而发展。不\n同文明之间平等交流、互学互鉴，才能为人类破解时代难题、实现共同发展提供强大的精神\n指引。\n（2)历史和现实表明，自由贸易是推动经济全球化和全球发展的重要动力，是大势所趋、人\n心所向。坚定践行自由贸易理念，坚决维护多边贸易体制，才能为全球发展注入确定性和稳\n定性。\n第一，中国坚定维护多边贸易体制。在单边主义引发世界局势动荡、多边贸易体系受到冲\n击的形势下，中国发挥了领导作用，坚定支持以世界贸易组织为核心的多边贸易体系，坚决反对\n贸易保护主义或贸易战，为世界提供了宝贵的稳定性。\n第二，中国坚定维护全球产业链供应链稳定。坚持“拉手”而不是“松手”、“延链”而不是\n“断链”，积极寻找更多利益契合点，支持供应链开放发展。\n第三，中国坚定维护开放合作的国际环境。加快推进自由贸易试验区、海南自由贸易港建\n设，实行更加积极主动的开放战略，稳步扩大制度型开放，建设更高水平开放型经济新体制，以\n实际行动支持多边贸易体制、推动发展自由贸易。\n20266考研政治\n终极预测4套卷","tags":["肖四","第4套","材料分析题"]},
  {"id":"q-shigang-1","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"从1840年至1919年的80年间，中国人民对外来侵略进行了英勇顽强的反抗。但是，历次的反侵略战争,都是以中国失败、中国政府被迫签订丧权辱国的条约而告结束的。近代中国反侵略战争屡遭失败的最重要的原因是","options":[{"key":"A","text":"经济技术的落后"},{"key":"B","text":"思想观念的保守"},{"key":"C","text":"作战能力的不足"},{"key":"D","text":"社会制度的腐败"}],"answerKey":"D","explanation":"历次的反侵略战争，都是以中国失败、中国政府被迫签订丧权辱国的条约而告结束的。其\n原因，从中国内部因素来分析，主要有以下两个方面：一是社会制度的腐败，二是\n后。而前者则是更根本的原因。正是社会制度的腐败，才使得经济技术落后的状况长期得不到\n改变。腐败的中国半殖民地半封建的社会制度，阻碍了中国人民群众的广泛动员和抵抗，这是\n近代中国反侵略战争屡遭失败的最重要的原因。D正确。近代中国反侵略战争失败的另一个\n重要原因,是国家综合实力特别是经济技术和作战能力的落后。A、B、C错误。","tags":["肖四","第1套","单选题"]},
  {"id":"q-shigang-2","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"新文化运动的倡导者以进化论观点和个性解放思想为主要武器，猛烈秤击以孔子为代表的“往圣先贤”，大力提倡新道德、反对旧道德，提倡新文学、反对旧文学，包括提倡白话文、反对文言文。新文化运动的倡导者批判孔学,是为了","options":[{"key":"A","text":"否定中国的全部传统文化"},{"key":"B","text":"促进马克思主义在中国的传播及其同中国工人运动的结合"},{"key":"C","text":"给中国发展资本主义扫清障碍"},{"key":"D","text":"推翻清政府这个“洋人的朝廷”"}],"answerKey":"C","explanation":"新文化运动的倡导者通过批判孔学,动摇了封建正统思想的统治地位，在中国社会掀起一\n股思想解放的潮流。新文化运动的倡导者批判孔学，是为了给中国发展资本主义扫清障碍。C\n正确。新文化运动提倡民主和科学，搞新文化运动,并不是要否定中国的全部传统文化。A错\n误。五四运动促进了马克思主义在中国的传播及其同中国工人运动的结合。B错误。新文化运\n动是在1915年开始的,清政府这个“洋人的朝廷”早已被推翻。D错误。","tags":["肖四","第1套","单选题"]},
  {"id":"q-shigang-3","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"中国人民的抗日战争从1931年开始，到1945年结束，前后经历了14年的浴血奋战。在世界反法西斯战争的进程中，中国人民的抗日战争被称为“最早的抗争，最后的胜利”。成为抗日战争取得完全胜利的重要标志的是","options":[{"key":"A","text":"中国参加联合国制宪会议，成为联合国的创始国和五个常任理事国之一"},{"key":"B","text":"日本天皇裕仁发布《终战诏书》，日本无条件投降"},{"key":"C","text":"日本代表在东京湾美军军舰密苏里号上签署向同盟国的投降书"},{"key":"D","text":"台湾以及澎湖列岛重归中国主权管辖"}],"answerKey":"D","explanation":"1945年10月25日，中国政府在台湾举行受降仪式。被日本占领50年之久的台湾以及澎\n湖列岛,重归中国主权管辖。这是抗日战争取得完全胜利的重要标志。D正确。联合国制宪会\n议于1945年4月至6月在美国旧金山举行，包括中国解放区代表董必武在内的中国代表团出席\n了会议,会议签署了《联合国宪章》，中国成为联合国的创始国和五个常任理事国之一。7月26\n日，中、美、英三国发表《波茨坦公告》，敦促日本投降。8月15日，日本天皇裕仁发布《终战诏\n书》，日本无条件投降。9月2日，日本天皇和政府以及日本大本营的代表在东京湾美军军舰密\n苏里号上签署向同盟国的投降书，侵华日军128万人向中国投降。至此，中国人民的14年抗日\n战争胜利结束,世界反法西斯战争也胜利结束。9月3日成为中国人民抗日战争胜利纪念日。\nA、B、C都不符合题意。","tags":["肖四","第1套","单选题"]},
  {"id":"q-shigang-4","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"经过艰苦卓绝的战斗，中朝军队战胜武装到牙齿的强敌，打破了美军不可战胜的神话，迫使不可一世的侵略者于1953年7月27日在停战协定上签字。抗美援朝战争的伟大胜利","options":[{"key":"A","text":"是中华民族从近代以来陷人深重危机走向伟大复兴的历史转折点"},{"key":"B","text":"是近代以来中国人民反抗外敌人侵第一次取得完全胜利的民族解放斗争"},{"key":"C","text":"彻底结束了旧中国一盘散沙的局面"},{"key":"D","text":"是中国人民站起来后屹立于世界东方的宣言书"}],"answerKey":"D","explanation":"抗美援朝战争的伟大胜利，是中国人民站起来后屹立于世界东方的宣言书，是中华民族走\n向伟大复兴的重要里程碑。D正确。中国人民抗日战争是20世纪中国和人类历史上的重大事\n件。这一伟大胜利，是近代以来中国人民反抗外敌人侵第一次取得完全胜利的民族解放斗争，是\n中华民族从近代以来陷人深重危机走向伟大复兴的历史转折点。A、B错误。新民主主义革命的胜\n利，中华人民共和国的成立，彻底结束了旧中国一盘散沙的局面。C错误。","tags":["肖四","第1套","单选题"]},
  {"id":"q-shigang-5","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"130多年前爆发的中日甲午战争是中国近代史上的一个重要时间节点。甲午战争中国战败的影响有","options":[{"key":"A","text":"中国开始陷人“边疆危机”"},{"key":"B","text":"中国人开始有了普遍的民族意识的觉醒"},{"key":"C","text":"帝国主义列强对中国的争夺和瓜分达到高潮"},{"key":"D","text":"标志着以“自强”“求富”为目标的洋务运动的失败"}],"answerKeys":["B","C","D"],"explanation":"B、C、D正确。中国在中日甲午战争前已经陷入“边疆危机”。19世纪70至80年代,列强\n从侵占中国周边邻国发展到蚕食中国边疆地区，使中国陷人“边疆危机”。英国从印度侵人西\n藏，又从缅甸入侵云南。法国则从越南侵犯广西。俄国从中亚人侵新疆。日本吞并琉球，侵犯\n中国台湾。A错误。\n点拨帝国主义列强对中国的争夺和瓜分的图谋，在1894年中日甲午战争爆发后达到高潮，表\n现在列强竞相租借港湾和划分势力范围，中国陷入“瓜分危机”。注意区分“边疆危机”和\n“瓜分危机”。","tags":["肖四","第1套","多选题"]},
  {"id":"q-shigang-6","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"1935年12月，中共中央在陕北瓦窑堡召开政治局扩大会议，讨论全国政治形势和党的策略路线问题、军事战略问题。会议批评并克服了党内长期存在的“左”倾冒险主义、关门主义错误倾向，明确提出党的基本策略任务是建立广泛的抗日民族统一战线。瓦窑堡会议是从第五次反“围剿”失败到全民族抗战兴起过程中召开的一次重要会议，它表明","options":[{"key":"A","text":"党在新的历史时期将要到来时掌握了政治上的主动权"},{"key":"B","text":"党开始努力解决政治路线问题"},{"key":"C","text":"党正在从中国的实际情况出发，创造性地开展工作"},{"key":"D","text":"实事求是的思想路线在全党范围确立起来"}],"answerKeys":["A","B","C"],"explanation":"1935年12月，中共中央在陕北瓦窑堡召开政治局扩大会议，提出党的基本策略任务是建\n立广泛的抗日民族统一战线，批评了党内长期存在的“左”倾冒险主义、关门主义错误倾向。瓦\n窑堡会议是从第五次反“围剿”失败到全民族抗战兴起过程中召开的一次重要会议，它表明党已\n经克服“左”倾冒险主义和关门主义，制定出抗日民族统一战线的新策略，使党在新的历史时期\n将要到来时掌握了政治上的主动权；表明党在遵义会议着重解决军事路线问题和组织问题之\n后，开始努力解决政治路线问题；表明党在总结经验教训的基础上，正在从中国的实际情况出\n发，创造性地开展工作。A、B、C正确。延安整风运动是一次深刻的马克思主义思想教育运动，\n也是一场思想解放运动。它坚持马克思主义同中国实际相结合的正确方向，使实事求是的思想\n路线在全党范围确立起来。D错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-shigang-7","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"中国人民抗日战争暨世界反法西斯战争胜利80周年纪念活动，是一次庄严隆重、大气磅、震撼人心、激励奋进的抗战纪念盛典。纪念活动","options":[{"key":"A","text":"进一步弘扬了伟大抗战精神"},{"key":"B","text":"进一步强化了与原同盟国的军事合作"},{"key":"C","text":"进一步坚定了全面推进强国建设、民族复兴伟业的信念信心"},{"key":"D","text":"进一步展示了推动构建人类命运共同体的责任担当"}],"answerKeys":["A","C","D"],"explanation":"习近平强调,纪念中国人民抗日战争暨世界反法西斯战争胜利80周年活动，是一次庄严\n隆重、大气磅、震撼人心、激励奋进的抗战纪念盛典，进一步弘扬了伟大抗战精神，进一步坚定\n了全面推进强国建设、民族复兴伟业的信念信心，进一步展示了推动构建人类命运共同体的责\n任担当。A、C、D正确,B错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-shigang-8","type":"material","module":"中国近现代史纲要","difficulty":3,"stem":"结合材料回答问题：（1）如何理解“中国人民抗日战争，从一开始就具有拯救人类文明、保卫世界和平的重大意义”？（或：如何理解伟大的中国抗战“不但是中国的事，东方的事，也是世界的事”“不但求一国的和平，而且求世界的和平”？）（2）结合党带领人民实现民族独立、人民解放的历史和当前的发展环境，说明为什么要建设世界一流军队。","material":{"title":"材料","paragraphs":["材料 1 我们的战争是神圣的、正义的,是进步的、求和平的。不但求一国的和平,而且求世界的和平,不但求一时的和平,而且求永久的和平。欲达此目的,便须决一死战,便须准备着一切牺牲,坚持到底,不达目的,绝不停止。牺牲虽大，时间虽长,但是永久和平和永久光明的新世界,已经鲜明地摆在我们的前面。我们从事战争的信念，便建立在这个争取永久和平和永久光明的新中国和新世界的上面。","摘自毛泽东《论持久战》","1939年1月，毛泽东同志在为《论持久战》英译本所作序言中指出，“伟大的中国抗战,不但是中国的事,东方的事,也是世界的事”。与军国主义侵略分子血战到底的中国人民,不仅在为中华民族的前途命运而战，也在为整个人类的前途命运而战。","摘编自《人民日报》（2025年9月4日）","材料2 习近平总书记深刻指出，“中国人民抗日战争，从一开始就具有拯救人类文明、保卫世界和平的重大意义”。","摘自《求是》（2025年第17期）","材料3 纪念中国人民抗日战争暨世界反法西斯战争胜利80周年盛大阅兵,在展示综合国力、振奋民心士气的同时，让全世界看到中国维护和平的坚定意志和强大能力。中华民族自古热爱和平,和平性是中华文明的突出特性。但历史告诉我们,仅仅热爱和平是不够的,只有具备强大的国防实力,才能维护和平。历史教训说明：能战方能止战，准备打才可能不必打,越不能打越可能换打。从战争与和平的辩证法出发，“以武止戈”思想的时代价值需要进一步彰显。","摘编自《人民日报》（2025年9月28日）"]},"answerPoints":["地，日本法西斯侵略者既是中国人民的敌人，也是世界人民的敌人。中国人民抗日战争，从一开始就是为国家生存而战、为民族复兴而战、为人类正义而战。1931年，日本策动九一八事变，点燃了法西斯侵略扩张的第一把战火。中国人民在白山黑水间的奋起抵抗，揭开了世界反法西斯战争的序幕。1937年7月7日，日本制造卢沟桥事变，发动了全面侵华战争。","中国的全民族抗战，开辟了世界第一个大规模反法西斯战场。中国抵抗了日军的最主要力量，成为彻底消灭日本法西斯的决定性力量，为欧洲战场和太平洋战场提供缓冲时间和空间。中国参与创建联合国和建立战后国际新秩序，为巩固战争胜利成果注入了东方智慧。世界反法西斯战争是一个整体，中国人民抗日战争是其中的重要组成部分。","中国人民抗日战争，从一开始就具有拯救人类文明、保卫世界和平的重大意义，并且为拯救人类文明、保卫世界和平，作出了彪炳史册的贡献。（“四最”：开始时间最早、持续时间最长、抗击和消灭日军最多、付出代价最大）(2)过去，中华民族走出苦难、中国人民实现解放，有赖于一支英雄的人民军队。","大革命从兴起到失败的经验教训表明，要取得革命胜利，必须坚持武装斗争，组建由党直接统率和指挥的军队。1927年南昌起义打响了武装反抗国民党反动派的第一枪，标志着中国共产党独立领导革命战争、创建人民军队和武装夺取政权的开端。","从那时起，人民军队在党的领导下，夺取了土地革命战争、抗日战争、解放战争的伟大胜利，彻底扭转了中华民族近代以来落后挨打的被动局面。新中国建立之初，人民军队又取得了抗美援朝战争的伟大胜利，为巩固新生人民政权、形成中国大国地位、维护中华民族尊严提供了坚强后盾。当今世界，和平与发展仍然是时代主题，但并不太平。","巩固国防和强大人民军队是新时代坚持和发展中国特色社会主义、实现中华民族伟大复兴的战略支撑。只有以强大军事实力为后盾，国家的总体安全和人民的幸福生活才有保障,实现国家繁荣富强的主动权才能牢牢掌握在自已手中。能战方能止战，必须加快把人民军队建设成为世界一流军队，以更强大的能力、更可靠的手段捍卫国家主权、安全、发展利益。"],"explanation":"地，日本法西斯侵略者既是中国人民的敌人，也是世界人民的敌人。中国人民抗日战争，从一开\n始就是为国家生存而战、为民族复兴而战、为人类正义而战。\n1931年，日本策动九一八事变，点燃了法西斯侵略扩张的第一把战火。中国人民在白山黑\n水间的奋起抵抗，揭开了世界反法西斯战争的序幕。1937年7月7日，日本制造卢沟桥事变，发\n动了全面侵华战争。中国的全民族抗战，开辟了世界第一个大规模反法西斯战场。中国抵抗了\n日军的最主要力量，成为彻底消灭日本法西斯的决定性力量，为欧洲战场和太平洋战场提供缓\n冲时间和空间。中国参与创建联合国和建立战后国际新秩序，为巩固战争胜利成果注入了东方\n智慧。\n世界反法西斯战争是一个整体，中国人民抗日战争是其中的重要组成部分。中国人民抗日\n战争，从一开始就具有拯救人类文明、保卫世界和平的重大意义，并且为拯救人类文明、保卫世\n界和平，作出了彪炳史册的贡献。\n（“四最”：开始时间最早、持续时间最长、抗击和消灭日军最多、付出代价最大）\n(2)过去，中华民族走出苦难、中国人民实现解放，有赖于一支英雄的人民军队。大革命从\n兴起到失败的经验教训表明，要取得革命胜利，必须坚持武装斗争，组建由党直接统率和指挥的\n军队。1927年南昌起义打响了武装反抗国民党反动派的第一枪，标志着中国共产党独立领导革\n命战争、创建人民军队和武装夺取政权的开端。从那时起，人民军队在党的领导下，夺取了土地\n革命战争、抗日战争、解放战争的伟大胜利，彻底扭转了中华民族近代以来落后挨打的被动局\n面。新中国建立之初，人民军队又取得了抗美援朝战争的伟大胜利，为巩固新生人民政权、形成\n中国大国地位、维护中华民族尊严提供了坚强后盾。\n当今世界，和平与发展仍然是时代主题，但并不太平。巩固国防和强大人民军队是新时代\n坚持和发展中国特色社会主义、实现中华民族伟大复兴的战略支撑。只有以强大军事实力为后\n盾，国家的总体安全和人民的幸福生活才有保障,实现国家繁荣富强的主动权才能牢牢掌握在\n自已手中。能战方能止战，必须加快把人民军队建设成为世界一流军队，以更强大的能力、更可\n靠的手段捍卫国家主权、安全、发展利益。","tags":["肖四","第1套","材料分析题"]},
  {"id":"q-shigang-9","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"近代中国资产阶级思想与封建主义思想的第一次正面交锋是","options":[{"key":"A","text":"“师夷长技以制夷”主张的提出"},{"key":"B","text":"洋务派与顽固派的论战"},{"key":"C","text":"维新派与守旧派的论战"},{"key":"D","text":"新文化运动倡导者对以孔子为代表的“往圣先贤”的猛烈秤击"}],"answerKey":"C","explanation":"维新派与守旧派的论战，实质上是资产阶级思想与封建主义思想在中国的第一次正面交\n锋。通过论战，西方资产阶级社会政治学说在中国得到进一步的传播，戊戌变法运动的惟幕随\n之拉开。C正确,A、B、D错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-shigang-10","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1924年1月，中国国民党第一次全国代表大会在广州召开，大会通过的宣言对三民主义作出了新的解释。新三民主义成为第一次国共合作的政治基础,究其原因,是由于新三民主义的政纲","options":[{"key":"A","text":"把民生主义概括为“平均地权”"},{"key":"B","text":"把斗争的矛头直接指向北洋军阀"},{"key":"C","text":"体现了联俄、联共、扶助农工三大革命政策"},{"key":"D","text":"同中国共产党在民主革命阶段的纲领基本一致"}],"answerKey":"D","explanation":"孙中山的新三民主义的政纲同中国共产党在民主革命阶段的纲领基本一致，因而成为第\n一次国共合作的政治基础。D正确。","tags":["肖四","第2套","单选题"]},
  {"id":"q-shigang-11","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"全民族抗战伊始，中共中央就提出必须在统一战线中坚持独立自主原则。为此，共产党必须保持在思想上、政治上和组织上的独立性，放手发动群众，壮大人民力量；必须坚持对人民军队的绝对领导，努力发展人民武装和抗日根据地；必须对国民党采取又团结又斗争、以斗争求团结的方针。这样做的目的,就是","options":[{"key":"A","text":"巩固和发展抗日民族统一战线"},{"key":"B","text":"发展进步势力、争取中间势力、孤立顽固势力"},{"key":"C","text":"发展和扩大抗日根据地，推动大后方的抗日运动"},{"key":"D","text":"力争中国共产党对抗日战争的领导权，使自已成为团结全民族抗战的中坚力量"}],"answerKey":"D","explanation":"全全民族抗战伊始，中共中央就提出必须在统一战线中坚持独立自主原则。为此，共产党必\n须保持在思想上、政治上和组织上的独立性，放手发动群众，壮大人民力量；必须坚持对人民军\n队的绝对领导，努力发展人民武装和抗日根据地；必须对国民党采取又团结又斗争、以斗争求团\n结的方针。这样做的目的，就是力争中国共产党对抗日战争的领导权，使自己成为团结全民族\n抗战的中坚力量。这是把抗日战争引向胜利的中心一环。D正确。A、B、C错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-shigang-12","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"1898年的“百日维新”如同县花一现，只经历了103天就天折了。除京师大学堂（北京大学的前身)被保留下来以外，其余新政措施大都被废除。戊戌维新运动失败的原因主要是","options":[{"key":"A","text":"维新派惧怕人民群众，把改革的全部希望寄托在一个没有实权的皇帝身上"},{"key":"B","text":"维新派触及了封建主义的经济基础一一封建土地所有制，导致守旧派强烈反扑"},{"key":"C","text":"维新派没有突破“中体西用”思想的局限，不敢触动君主专制制度"},{"key":"D","text":"维新派虽然大声疾呼救亡图存，却又幻想西方列强能帮助自已变法维新"}],"answerKeys":["A","D"],"explanation":"戊戌维新运动的失败，主要是由于维新派自身的局限和以慈禧太后为首的强大的守旧势\n力的反对。当时民族资本主义经济力量还十分微弱，民族资产阶级的社会基础相当狭窄。维新\n派的势力非常弱小，他们既没有严密的组织，也不掌握实权和军队，更没有去发动群众。这样，\n他们就只能把自已实行改革的全部希望寄托在一个没有实权的光绪皇帝身上。维新派本身的\n局限性突出地表现在三个方面：首先，不敢否定封建主义。他们在政治上不敢根本否定封建君\n主制度;在经济上,未触及封建主义的经济基础一一封建土地所有制；在思想上，他们虽然提倡\n学习西学，却仍要打着孔子的旗号，借古代圣贤之名“托古改制”。其次,对帝国主义抱有幻想。\n他们虽然大声疾呼救亡图存，却又幻想西方列强能帮助自已变法维新。最后，惧怕人民群众。\nA、D正确,B错误。维新派突破洋务派“中体西用”思想的局限，主张改革君主专制制度。他们\n鼓吹民权并提出开议院的主张，也就是要用君主立宪制取代君主专制制度。C错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-shigang-13","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"大革命是在国共合作的条件下进行的,没有国共合作,不会在短时间内掀起这样一场革命。在这场革命中，中国共产党起着独特的、不可代替的作用。没有中国共产党，不会有这场大革命。中国共产党在大革命中的独特的、不可代替的作用表现在","options":[{"key":"A","text":"中国共产党是大革命的政治口号一一反对帝国主义、反对军阀一一的提出者"},{"key":"B","text":"中国共产党是人民群众的主要发动者和组织者"},{"key":"C","text":"中国共产党是国共合作的倡导者和统一战线的领导者"},{"key":"D","text":"中国共产党帮助和推动了国民革命军的建立"}],"answerKeys":["A","B","D"],"explanation":"A、B、D正确。中国共产党是国共合作的倡导者和统一战线的组织者，但不是统一战线的\n领导者。中国共产党的中央领导机关在大革命的后期犯了以陈独秀为代表的右倾机会主义的\n错误，放弃了无产阶级对于农民群众、城市小资产阶级和民族资产阶级的领导权，尤其是武装力\n量的领导权,这是大革命失败的重要原因之一。C错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-shigang-14","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"1945年8月25日，中共中央发表《对目前时局的宣言》,明确提出和平、民主、团结的口号。中共中央之所以提出这个口号，是因为","options":[{"key":"A","text":"希望通过和平途径对中国进行政治社会的改革"},{"key":"B","text":"中国人民在经历了长期战争后有和平建国的强烈要求"},{"key":"C","text":"需要时间来争取外援以进行经济建设"},{"key":"D","text":"人民力量的强大,加上其他条件，有可能造成和平发展的新阶段"}],"answerKeys":["A","B","D"],"explanation":"抗日战争胜利后，中国广大人民热切希望实现和平、民主，为建设新中国而奋斗。中国共\n标迈进。因为，中国人民在经历了长期战争后，有和平建国的强烈要求，中国共产党应当充分考\n虑人民群众的这种愿望。同时，由于人民力量强大，加上其他条件，中国共产党估计，造成国共\n两党合作（加上民主同盟等）、和平发展新阶段的可能性是存在的。中国共产党应当努力争取中\n国出现这种局面。基于对和平的真诚愿望和对局势的清醒认识，中共中央认为，同国民党进行\n和平谈判是必要的；即使是暂时的和平局面，也应该积极争取。1945年8月25日，中共中央发\n表《对目前时局的宣言》,明确提出和平、民主、团结的口号。A、B、D正确,C错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-shigang-15","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"2025年10月24日，全国人大常委会通过决定，将10月25日设立为台湾光复纪念日。之所以设立这个纪念日，是为","options":[{"key":"A","text":"维护世界反法西斯战争胜利成果和战后国际秩序"},{"key":"B","text":"展现坚持一个中国原则和捍卫国家主权、统一、领土完整的坚定意志"},{"key":"C","text":"强化两岸同胞共同民族历史记忆，弘扬爱国主义精神"},{"key":"D","text":"激励两岸同胞在新时代新征程中为国家统一、民族复兴作出新的贡献"}],"answerKeys":["A","B","C","D"],"explanation":"为维护世界反法西斯战争胜利成果和战后国际秩序，展现坚持一个中国原则和捍卫国家\n主权、统一、领土完整的坚定意志，强化两岸同胞共同民族历史记忆，弘扬爱国主义精神，激励两\n岸同胞在新时代新征程中为国家统一、民族复兴作出新的贡献，根据《中华人民共和国宪法》，十\n四届全国人大常委会第十八次会议作出设立台湾光复纪念日的决定。A、B、C、D全选。","tags":["肖四","第2套","多选题"]},
  {"id":"q-shigang-16","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"在中国大地上率先举起马克思主义旗帜的是李大钊。李大钊是从爱国的立场出发，从民主主义者转变为共产主义者的。从1918年7月起，他先后发表《法俄革命之比较观》《庶民的胜利》《Bolshevism的胜利》等文章,热情讴歌十月革命的胜利,指出十月革命是“二十世纪中世界革命的先声”，确信“将来的环球，必是赤旗的世界”。五四运动后，他更加致力于马克思主义的宣传。1919年9月、11月，李大钊发表《我的马克思主义观》一文，在当时思想界产生了重大影响，标志着","options":[{"key":"A","text":"马克思主义开始与中国工人运动相结合"},{"key":"B","text":"马克思主义在中国进人比较系统的传播阶段"},{"key":"C","text":"马克思主义成为中国共产党的指导思想"},{"key":"D","text":"中国先进分子把目光从资产阶级民主主义转向社会主义"}],"answerKey":"B","explanation":"1919年9月、11月，李大钊发表《我的马克思主义观》一文，比较系统地介绍了马克思主义理\n论，在当时思想界产生重大影响，标志着马克思主义在中国进入比较系统的传播阶","tags":["肖四","第3套","单选题"]},
  {"id":"q-shigang-17","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1927年9月9日，毛泽东等领导的湘赣边界秋收起义爆发。起义军公开打出了“工农革命军”的旗帜，在攻打中心城市长沙受挫后，毛泽东果断改变计划，决定向敌人控制比较薄弱的农村转移。9月29日，毛泽东领导起义军在江西永新县三湾村进行了著名的三湾改编，确立了","options":[{"key":"A","text":"土地革命的方针"},{"key":"B","text":"支部建在连上的原则"},{"key":"C","text":"民主集中制原则"},{"key":"D","text":"思想建党、政治建军原则"}],"answerKey":"B","explanation":"1927年9月至10月，毛泽东领导秋收起义的部队在江西省永新县三湾村完成“三湾改\n编”，创造性地将支部建在连上，成立各级士兵委员会，实行民主制度，在政治上官兵平等。由此\n开始改变了起义军中旧军队的习气和不良作风，从组织上确立了党对军队的领导，是建设无产\n阶级领导的新型人民军队的重要开端。B正确。1927年8月7日，中共中央在汉口秘密召开紧\n急会议（即八七会议），会议确定了土地革命和武装起义的方针。A错误。中共五大正式提出民\n主集中制的组织原则。C错误。1929年12月，红四军党的第九次代表大会（史称古田会议）在\n福建上杭县古田村召开。大会根据中央九月来信精神，通过了毛泽东起草的古田会议决议，其\n中最重要的是关于纠正党内错误思想的决议案，确立了思想建党、政治建军原则。古田会议决\n议是中国共产党和红军建设的纲领性文献，是党和人民军队建设史上的重要里程碑。D错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-shigang-18","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1956年9月15日至27日，中国共产党第八次全国代表大会在北京举行。八大正确分析了国内形势和主要矛盾的变化，明确提出新形势下党和人民的主要任务。八大坚持党中央提出的既反保守又反冒进，即在综合平衡中稳步前进的经济建设方针。大会肯定“三个主体，三个补充”思想，即以国家经营和集体经营、计划生产、国家市场三者为主体，以个体经营、自由生产、自由市场三者为补充。这","options":[{"key":"A","text":"在理论上完全突破了苏联计划经济模式"},{"key":"B","text":"为克服苏联模式弊端提供了重要启示"},{"key":"C","text":"初步形成了社会主义市场经济体制"},{"key":"D","text":"对过渡时期总路线的提出具有重要意义"}],"answerKey":"B","explanation":"中共八大坚持党中央提出的既反保守又反冒进，即在综合平衡中稳步前进的经济建设方\n针。大会肯定“三个主体，三个补充”思想，即以国家经营和集体经营、计划生产、国家市场三者\n为主体,以个体经营、自由生产、自由市场三者为补充。这是在理论上突破苏联计划经济模式，\n探索经济体制改革的重要尝试。习近平在纪念陈云同志诞辰120周年座谈会上的讲话中指出，\n社会主义改造基本完成后，陈云同志积极探索适应我国生产力发展的社会主义经济制度和经济\n体制，提出“三个主体、三个补充”的思想，为克服苏联模式端提供了重要启示。B正确。对于\n苏联计划经济模式，“三个主体，三个补充”思想在理论上没有完全突破，在实践上也只是探索尝\n试。A、C错误。中共中央在1952年底开始酝酿并于1953年正式提出党在过渡时期的总路线。\nD错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-shigang-19","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1978年5月10日，中央党校内部刊物《理论动态》刊登《实践是检验真理的唯一标准》一文。第二天，《光明日报》以特约评论员名义公开发表这篇文章，新华社向全国转发。文章发表后产生强烈反响，引发了关于真理标准问题的大讨论。这场深刻而广泛的马克思主义思想解放运动","options":[{"key":"A","text":"成为正本清源、拨乱反正和改革开放的思想先导"},{"key":"B","text":"重新确立了实事求是的思想路线"},{"key":"C","text":"是解放思想、开辟新时期新道路的宜言书"},{"key":"D","text":"标志着党在指导思想上的拨乱反正胜利完成"}],"answerKey":"A","explanation":"在邓小平和许多老一辈革命家的支持下，关于真理标准问题的大讨论迅速在全党全社会\n展开。这场深刻而广泛的马克思主义思想解放运动，成为正本清源、拨乱反正和改革开放的思\n想先导。A正确。1978年12月13日,邓小平在中央工作会议闭幕会上作了题为《解放思想，实\n事求是，团结一致向前看》的讲话，这个讲话是解放思想、开辟新时期新道路的宣言书，实际上成\n为随后召开的党的十一届三中全会的主题报告，为全会实现具有划时代意义的伟大转折奠定了\n重要基础。C错误。1978年12月召开的党的十一届三中全会,重新确立了实事求是的思想路\n线，确定把全党工作的着重点转移到社会主义现代化建设上来，作出实行改革开放的重大决策，\n实现了党的历史上具有深远意义的伟大转折。B错误。1981年6月，党的十一届六中全会通过\n的《关于建国以来党的若干历史问题的决议》，标志着党在指导思想上的拨乱反正胜利完成。\nD错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-shigang-20","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"1956年，毛泽东在《纪念孙中山先生》一文中指出，纪念伟大的革命先行者孙中山先生，“纪念他在辛亥革命时期，领导人民推翻帝制、建立共和国的丰功伟绩。”辛亥革命","options":[{"key":"A","text":"是资产阶级领导的以反对封建君主专制制度、建立资产阶级共和国为目的的革命"},{"key":"B","text":"实现了中国人民和中华民族自鸦片战争以来的第一次全面觉醒"},{"key":"C","text":"是中国人民为救亡图存、振兴中华而奋起革命的一座里程碑"},{"key":"D","text":"是一次比较完全意义上的资产阶级民主革命"}],"answerKeys":["A","C","D"],"explanation":"A、C、D正确。辛亥革命激发了人民的爱国热情和民族觉醒，打开了禁思想进步的闸\n门。五四运动以全民族的行动激发了追求真理、追求进步的伟大觉醒，它改变了以往只有觉悟\n的革命者而缺少觉醒的人民大众的斗争状况,实现了中国人民和中华民族自鸦片战争以来的第\n一次全面觉醒。B错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-shigang-21","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"1937年8月，中国共产党在陕北洛川召开政治局扩大会议（洛川会议）。会议强调要争取抗战胜利的关键在于使已经发动的抗战成为全面的全民族抗战。会议通过《中国共产党抗日救国十大纲领》，提出必须实行全国军事总动员、全国人民总动员；必须改革政治机构，给人民以充分的抗日民主权利，并适当改善工农大众生活。洛川会议制定的党的全面抗战路线","options":[{"key":"A","text":"把实行全民族抗战与争取人民民主、改善人民生活结合起来"},{"key":"B","text":"把反对外敌人侵与推进社会进步统一起来"},{"key":"C","text":"正确处理了民族矛盾与阶级矛盾的关系"},{"key":"D","text":"确立了建立广泛的抗日民族统一战线的新策略"}],"answerKeys":["A","B","C"],"explanation":"洛川会议是在全面抗战刚刚爆发的历史转折关头召开的一次重要会议。会议制定的党的\n全面抗战路线，把实行全民族抗战与争取人民民主、改善人民生活结合起来，把反对外敌入侵与\n推进社会进步统一起来，正确处理了民族矛盾与阶级矛盾的关系。A、B、C正确。1935年12月，\n中共中央在陕北瓦窑堡召开的政治局扩大会议确立了建立广泛的抗日民族统一战线的新策略。\nD错误。\n9.谷案BCD\n简析中共七大制定了党的政治路线，即“放手发动群众，壮大人民力量，在我党的领导下，打败\n日本侵略者，解放全国人民，建立一个新民主主义的中国”；制定了新民主主义国家在政治、经\n济、文化方面的纲领；把党在长期奋斗中形成的优良作风概括为三大作风，即理论和实践相结合\n的作风、和人民群众紧密地联系在一起的作风、自我批评的作风。B、C、D正确。毛泽东在党的\n七届二中全会上提出了“两个务必”的思想，即“务必使同志们继续地保持谦虚、谨慎、不骄、不躁\n的作风，务必使同志们继续地保持艰苦奋斗的作风”。A错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-shigang-22","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"1945年4月23日至6月11日，中国共产党第七次全国代表大会在延安举行。毛泽东在会上作了题为《论联合政府》的书面报告和《愚公移山》的闭幕词。中共七大制定了“放手发动群众，壮大人民力量，在我党的领导下，打败日本侵略者，解放全国人民，建立一个新民主主义的中国”的政治路线，总结党的建设的历史经验，把党在长期奋斗中形成的优良作风概括为","options":[{"key":"A","text":"艰苦奋斗的作风"},{"key":"B","text":"理论和实践相结合的作风"},{"key":"C","text":"和人民群众紧密地联系在一起的作风"},{"key":"D","text":"自我批评的作风"}],"answerKeys":["A","B","C"],"explanation":"A、B、C正确。新时代公民道德建设的重点任务是筑牢理想信念之基、培育和践行社会主义核心价值观、传承中华传统美德、弘扬民族精神和时代精神。D错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-shigang-23","type":"material","module":"中国近现代史纲要","difficulty":3,"stem":"结合材料回答问题：（1）结合遵义会议前后中国革命事业发生天翻地覆历史巨变的原因，分析“两个确立”对新时代党和国家事业的决定性意义。（2）如何理解“长征的胜利，是方向和道路的胜利”？（3）中国共产党如何在统一战线中“坚持独立自主、团结抗战”，发挥中流磁柱作用？","material":{"title":"材料","paragraphs":["材料 1 我们党在新民主主义革命时期的历史共有28年，这28年以遵义会议为界，正好可以划分为前14年和后14年。前14年，我们党犯了一次右倾、三次“左”倾的错误，中国革命遭受了两次重大挫折，一次是大革命的失败，一次是中央革命根据地第五次反“围剿”的失败,红军被迫进行战略转移；后14年，从遵义会议开始，我们党重新奋起，团结带领人民克服了一个又一个艰险、战胜了一个又一个挑战，先是取得了长征的胜利，度过了最艰难的时期，开创了中国革命新局面，尔后又陆续取得了抗日战争的胜利、解放战争的胜利，推翻帝国主义、封建主义、官僚资本主义三座大山，最终建立中华人民共和国，实现了民族独立、人民解放，开#纪元。在这样的前后对比中，我们可以清晰地看到，遵义会议是一个重要的标识和转折。遵义会议后，党和红军转危为安、化险为夷，中国苹命斗争的局面从被动转向主动，从此中国苹命事业就不断从胜利走向新的更大的胜利。","摘编自《人民日报》（2025年1月7日）","材料2 长征在我们党、国家、军队发展史上具有十分伟大的意义，对中华民族历史进程具有十分深远的影响。一长征是一次理想信念的伟大远征。崇高的理想，坚定的信念，永远是中国共产党人的政治灵魂。一长征是一次检验真理的伟大远征。真理只有在实践中才能得到检验，真理只有在实践中才能得到确立。长征的胜利，使我们党进一步认识到，只有把马克思列宁主义基本原理同中国革命具体实际结合起来，独立自主解决中国革命的重大问题，才能把革命事业引向胜利。这是在血的教训和斗争考验中得出的真理。一长征是一次唤醒民众的伟大远征。红军打胜仗，人民是靠山。一长征是一次开创新局的伟大远征。长征的胜利，是方向和道路的胜利。","摘自习近平《在纪念红军长征胜利80周年大会上的讲话》","材料3 中国人民抗日战争胜利是中国共产党发挥中流砥柱作用的伟大胜利。中国共产党的中流砥柱作用是中国人民抗日战争胜利的关键。习近平总书记指出：“中国共产党高举抗日民族统一战线的旗帜，坚决维护、巩固、发展统一战线，坚持独立自主、团结抗战，维护了团结抗战大局。","摘编自《人民日报》（2025年9月8日）"]},"answerPoints":["上确立了毛泽东同志在党中央和红军的领导地位，开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，开始形成以毛泽东同志为核心的党的第一代中央领导集体，开启了党独立自主解决中国革命实际问题的新阶段。遵义会议前后党的历史表明，核心问题至关紧要。坚强的领导核心和科学的理论指导是关乎党和国家前途命运、党和人民事业成败的根本性问题。","新时代的伟大变革，是在以习近平同志为核心的党中央坚强领导下、在习近平新时代中国特色社会主义思想指引下全党全军全国各族人民团结奋斗取得的。新时代的伟大实践充分证明，“两个确立”是新时代党和国家事业取得历史性成就、发生历史性变革的决定性因素，是党和人民应对一切不确定性的最大确定性、最大底气、最大保证。","(2)长征的过程，不仅是战胜敌人、赢得胜利、实现战略目标的过程，而且是联系实际、创新理论、探索革命道路的过程。第五次反“围剿”失败后，中国革命面临着方向和道路的快择。","长征途中，我们党通过艰苦卓绝的实践探索，成功把解决生存危机同拯救民族危亡联系在一起，把长征的大方向同建立抗日前进阵地联系在一起，实现了国内革命战争向抗日民族战争的转变，为夺取中国人民抗日战争胜利、进而夺取新民主主义革命胜利打下了坚实基础。长征胜利启示我们：只有立足实际、独立自主开辟前进道路，才能不断走向胜利。","(3)中国共产党的中流砥柱作用表现在：第一，在民族危亡的历史关头，中国共产党率先高举武装抗日旗帜。第二，秉持民族大义，倡导、促成并始终坚决维护和巩固发展抗日民族统一战线。第三，坚持全面抗战路线，提出和实施持久战的战略总方针和一整套人民战争的战略战术，开展敌后游击战争，开辟敌后战场，建设巩固的抗日民主根据地，成为坚持抗战的中坚力量。","第四，以自己的政治主张、坚定意志、模范行动，支撑起全民族亡图存的希望。由于国共两党代表不同的阶级利益，参加抗战的目的不尽相同，实行的抗战路线不同，统一战线内部不可避免地存在着矛盾和斗争。全民族抗战伊始，中共中央就提出必须在统一战线中坚持独立自主原则。","为此,共产党必须保持在思想上、政治上和组织上的独立性，必须坚持对人民军队的绝对领导，必须对国民党采取又团结又斗争、以斗争求团结的方针。为了抗日民族统一战线的坚持、扩大和巩固，中国共产党还制定了“发展进步势力、争取中间势力、孤立顽固势力”的策略总方针。"],"explanation":"上确立了毛泽东同志在党中央和红军的领导地位，开始确立以毛泽东同志为主要代表的马克思\n主义正确路线在党中央的领导地位，开始形成以毛泽东同志为核心的党的第一代中央领导集\n体，开启了党独立自主解决中国革命实际问题的新阶段。\n遵义会议前后党的历史表明，核心问题至关紧要。坚强的领导核心和科学的理论指导是关\n乎党和国家前途命运、党和人民事业成败的根本性问题。新时代的伟大变革，是在以习近平同\n志为核心的党中央坚强领导下、在习近平新时代中国特色社会主义思想指引下全党全军全国各\n族人民团结奋斗取得的。新时代的伟大实践充分证明，“两个确立”是新时代党和国家事业取得\n历史性成就、发生历史性变革的决定性因素，是党和人民应对一切不确定性的最大确定性、最大\n底气、最大保证。\n(2)长征的过程，不仅是战胜敌人、赢得胜利、实现战略目标的过程，而且是联系实际、创新\n理论、探索革命道路的过程。第五次反“围剿”失败后，中国革命面临着方向和道路的快择。长\n征途中，我们党通过艰苦卓绝的实践探索，成功把解决生存危机同拯救民族危亡联系在一起，把\n长征的大方向同建立抗日前进阵地联系在一起，实现了国内革命战争向抗日民族战争的转变，\n为夺取中国人民抗日战争胜利、进而夺取新民主主义革命胜利打下了坚实基础。长征胜利启示\n我们：只有立足实际、独立自主开辟前进道路，才能不断走向胜利。\n(3)中国共产党的中流砥柱作用表现在：第一，在民族危亡的历史关头，中国共产党率先高\n举武装抗日旗帜。第二，秉持民族大义，倡导、促成并始终坚决维护和巩固发展抗日民族统一战\n线。第三，坚持全面抗战路线，提出和实施持久战的战略总方针和一整套人民战争的战略战术，\n开展敌后游击战争，开辟敌后战场，建设巩固的抗日民主根据地，成为坚持抗战的中坚力量。第\n四，以自己的政治主张、坚定意志、模范行动，支撑起全民族亡图存的希望。\n由于国共两党代表不同的阶级利益，参加抗战的目的不尽相同，实行的抗战路线不同，统一\n战线内部不可避免地存在着矛盾和斗争。全民族抗战伊始，中共中央就提出必须在统一战线中\n坚持独立自主原则。为此,共产党必须保持在思想上、政治上和组织上的独立性，必须坚持对人\n民军队的绝对领导，必须对国民党采取又团结又斗争、以斗争求团结的方针。为了抗日民族统\n一战线的坚持、扩大和巩固，中国共产党还制定了“发展进步势力、争取中间势力、孤立顽固势\n力”的策略总方针。","tags":["肖四","第3套","材料分析题"]},
  {"id":"q-shigang-24","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"洋务运动是在19世纪60年代初第二次鸦片战争结束后，在清政府镇压太平天国起义与捻军起义的过程中兴起的。维新运动发生于19世纪90年代。维新运动与洋务运动的主要不同点在于","options":[{"key":"A","text":"洋务运动只学习西方技术,维新运动主张学习西方政治制度"},{"key":"B","text":"洋务运动依靠封建统治阶级中的部分成员，维新运动依靠下层群众"},{"key":"C","text":"洋务运动维护封建统治，维新运动否定封建主义"},{"key":"D","text":"洋务运动实现了预期目标，维新运动县花一现"}],"answerKey":"A","explanation":"洋务运动坚持“中学为体，西学为用”，仅引进西方技术而不改变政治制度。维新派突破洋\n务派“中体西用”思想的局限，主张学习西方政治制度，用君主立宪制取代君主专制制度。戊戌\n维新运动虽然未能成功地建立起资本主义的君主立宪制度，其颁布的促进民族资本主义发展的\n若干措施也未能生效，但在政治、经济等领域一定程度上冲击了封建制度。A正确。洋务运动是\n由封建统治阶级中的部分成员如奕近、曾国藩、李鸿章、左宗棠、张之洞等发起的\n为“洋务派”。他们发起洋务运动主要是为了维护封建统治，并不是要使中国朝着独立的资本主\n义方向发展。维新派的局限性突出地表现为不敢否定封建主义。他们在政治上不敢根本否定\n封建君主制度，只是幻想依靠光绪皇帝“以君权雷厉风行”，通过和平、合法的手段，实现自上而\n下的改良，让资产阶级和开明士绅的代表参加政权，逐步实现君主立宪。维新派的活动基本上\n局限于官僚士大夫和知识分子的小圈子。他们不但脱离人民群众，而且惧怕甚至仇视人民群\n众。B、C错误。洋务运动历时30多年，虽然办起了一批企业，建立了海军，却没有使中国富强起\n来。甲午战争一役，洋务派经营多年的北洋海军全军覆没，标志着以“自强”“求富”为目标的洋\n务运动的失败。D错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shigang-25","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1905年8月20日，孙中山和黄兴、宋教仁等人在日本东京成立中国同盟会。同盟会以《民报》为机关报,并确定了革命纲领。同盟会的成立,标志着","options":[{"key":"A","text":"关于革命与改良的辩论以革命派的胜利而告结束"},{"key":"B","text":"孙中山组建的第一个革命团体的诞生"},{"key":"C","text":"中国人民在精神上由被动变为主动，中国革命的面貌焕然一新"},{"key":"D","text":"中国资产阶级民主革命进人了一个新的阶段"}],"answerKey":"D","explanation":"中国同盟会，孙中山被公举为总理，黄兴被任命为执行部庶务，实际主持会内日常工作。同盟会\n以《民报》为机关报,并确定了革命纲领。这是近代中国第一个领导资产阶级革命的全国性政\n党。同盟会的成立,标志着中国资产阶级民主革命进入了一个新的阶段。D正确。关于革命与\n改良的辩论发生在1905年到1907年，在同盟会成立之后，A错误。1894年11月，孙中山在檀香\n山组建了第一个革命团体兴中会,立誓“驱除鞑虏,恢复中国,创立合众政府”。B错误。1921\n年,在中国人民和中华民族的伟大觉醒中,在马克思列宁主义同中国工人运动的紧密结合中，中\n国共产党应运而生。从此，中国人民就有了前进的主心骨，中国人民在精神上就由被动变为主\n动,中国革命的面貌就焕然一新。C错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shigang-26","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1935年12月17日至25日，中国共产党在陕北瓦窑堡召开中共中央政治局扩大会议。会议通过了《中共中央关于目前政治形势与党的任务的决议》。会后，毛泽东根据会议精神，在党的活动分子会议上作了《论反对日本帝国主义的策略》的报告。毛泽东明确指出，党的新策略即广泛的统一战线的出发点是①中国长期缺乏有力的国际援助的基本事实②国际联盟和英美等国政府采取对日姑息、纵容的政策的基本事实③日本帝国主义决定要变全中国为它的殖民地的基本事实④中国革命的现时力量还有严重的弱点的基本事实","options":[{"key":"A","text":"①②"},{"key":"B","text":"③④"},{"key":"C","text":"②③"},{"key":"D","text":"①④"}],"answerKey":"B","explanation":"1935年12月17日至25日，中国共产党在陕北瓦窑堡召开中共中央政治局扩大会议。会\n议通过了《中共中央关于目前政治形势与党的任务的决议》。会后，毛泽东根据会议精神，在党\n的活动分子会议上作了《论反对日本帝国主义的策略》的报告。毛泽东明确指出：“日本帝国主\n义决定要变全中国为它的殖民地,和中国革命的现时力量还有严重的弱点,这两个基本事实就\n是党的新策略即广泛的统一战线的出发点。③④正确。因此,本题选B。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shigang-27","type":"choice","module":"中国近现代史纲要","difficulty":1,"stem":"1945年10月25日，中国政府宣告“恢复对台湾行使主权”，并在台北举行“中国战区台湾省受降仪式”。此前，国际上已经有了一系列具有国际法律效力的文件，从法律上确认台湾是中国领土的一部分。这些具有国际法律效力的文件有①《开罗宣言》②《波茨坦公告》③《日本投降书》④《雅尔塔协定》","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answerKey":"A","explanation":"外交部发言人毛宁2025年11月20日表示，80年前，包括台湾同胞在内的中国军民浴血\n奋战，打败日本侵略者，取得了抗日战争的伟大胜利，台湾回归祖国怀抱。《开罗宣言》《波茨坦\n公告》《日本投降书》等一系列条约文书都明确了中国对台湾的主权。台湾光复是二战胜利成\n果,是战后国际秩序的重要组成部分。①②③正确。因此,本题选A。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shigang-28","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"五四以后的新文化运动发展到了一个新阶段，马克思主义开始逐步在思想文化领域中发挥指导作用，这主要是指中国先进分子在接受马克思主义之后","options":[{"key":"A","text":"没有抛弃而是继承了五四运动的民主和科学的精神并赋予它们新的含义"},{"key":"B","text":"克服了以往启蒙者的弱点，有力推动了反封建的启蒙运动"},{"key":"C","text":"以唯物史观为武器从反对封建思想人手，进而提出必须反对产生封建思想的社会制度"},{"key":"D","text":"依靠进步报刊的传播，把改造国民性置于优先地位"}],"answerKeys":["A","B","C"],"explanation":"中国先进分子在接受马克思主义之后，并没有抛弃而是继承了五四运动的民主和科学的\n精神，并赋予它们新的含义，使它们在更高层次上得到了发扬。马克思主义的传播，并没有中断\n或取消五四运动以前开始的反封建的思想启蒙工作，而是克服了以往启蒙者的弱点，有力推动\n了反封建的启蒙运动。中国的先进分子以唯物史观为武器，从反对封建思想入手，进而提出必\n须反对产生封建思想的社会制度；把反封建思想斗争的立足点，从争取个人的个性解放，扩展到\n争取人民群众的社会解放的高度；把反封建的斗争方式，从少数人进行的思想批判，逐步发展为\n人民群众的革命实践。A、B、C正确。把改造国民性置于优先地位是五四以前的新文化运动的\n主张,D错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-shigang-29","type":"multi","module":"中国近现代史纲要","difficulty":2,"stem":"从传统的战争理论看来，游击战争是个战术问题。但是，在中国人民抗日战争中，游击战被提到战略地位，具有全局性意义。以下说法正确的有","options":[{"key":"A","text":"在战略防御阶段，游击战争担负了抗击日军战略进攻的主要任务"},{"key":"B","text":"游击战争主要是在外线单独作战，而不是在内线配合正规军的战役作战"},{"key":"C","text":"在民族战争条件下，游击战争能够大规模地进行"},{"key":"D","text":"在长期的不断削弱敌人、壮大自已的斗争中，游击军和游击战必将向正规军和运动战发展"}],"answerKeys":["B","C","D"],"explanation":"毛泽东之所以把抗日游击战争提高到战略地位来考察，是因为：在中国这样一个大国中，\n特别是在民族战争条件下，游击战争有充分的活动地盘和极为广大的群众基础，能够大规模地\n进行。抗日游击战争主要不是内线配合正规军的战役作战，而是在外线单独作战，并有自己一\n整套的防御和进攻的战略战术。抗日战争的长期性，又使得在广泛发动游击战争中，要解决创\n建根据地和建立人民政权的战略任务。在长期的不断削弱敌人、壮大自已的斗争中，游击军和\n游击战必将向正规军和运动战发展,形成为最后战胜敌人的强大战斗力量。B、C、D正确。在战\n略防御阶段，从全局看，国民党正面战场的正规战是主要的，敌后游击战是辅助的。日本侵略者\n以国民党军队为主要作战对象。以国民党军队为主体的正面战场担负了抗击日军战略进攻的\n主要任务，组织了淞沪、忻口、徐州、武汉会战等一系列大战役。A错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-shigang-30","type":"material","module":"中国近现代史纲要","difficulty":3,"stem":"结合材料回答问题：（1）联系党的建设“伟大的工程”，说明“延安作风”为什么能够打败“西安作风”。（2）结合“党在长期实践中形成并坚持发扬一整套优良作风”，说明党的作风建设为什么“必须常抓不邂、久久为功”。","material":{"title":"材料","paragraphs":["材料1 全面抗战初期，毛泽东同志指出：“一个政党要引导革命到胜利，必须依靠自己政治路线的正确和组织上的巩固。”为此，他提出了“建设一个全国范围的、广大群众性的、思想上政治上组织上完全巩固的布尔什维克化的中国共产党”的目标，并称之为“伟大的工程”。为了实现这一目标，中国共产党坚持把马克思主义与中国具体实际相结合，在思想建设、组织建设、作风建设等方面取得了丰硕成果。","摘编自《人民日报》（2025年8月25日）","材料2 “用延安作风打败西安作风”一语，出自延安时期毛泽东同志与党内同志的一场经典谈话。1940年秋，延安马列学院特地安排邓力群等四位同志前往杨家岭迎接毛泽东同志来作报告。毛泽东同志得知来意之后摇摇手说“我们是共产党人·就万万不能沾染官你习气··我们要养成一种新的风气，延安作风。我们要用延安作风打败西安作风。”在毛泽东同志的谈话中，“延安作风”是指清正廉洁、密切联系群众、理论联系实际等共产党作风，“西安作风”是指奢侈浮华、贪图享乐、脱离群众等国民党作风。","摘编自《光明日报》（202","习近平强调，当年毛泽东同志等老一辈革命家在延安，住窑洞、吃粗粮、穿布衣，用“延安作风”打败了“西安作风”。全党同志要把老一辈苹命家和共产党人留下的光荣传统和优良作风传承好发扬好，勇于推进党的自我苹命，坚定不移推进全面从严治党，始终保持党的先进性和纯洁性，确保党始终成为中国特色社会主义事业的坚强领导核心。","摘编自《人民日报》（2022年10月28日）","材料3 习近平总书记指出：“我们党团结带领人民取得了革命、建设、改革的伟大成就，很重要的一条就是我们党在长期实践中培育并坚持了一整套光荣传统和优良作风。”党在长期实践中形成并坚持发扬一整套优良作风，有力推动党的事业不断向前发展，这是党在长期实践中取得的历史性成就，更是党百余年奋斗征程所积累的宝贵经验。习近平总书记强调：“必须常抓不邂、久久为功，直至真正化风成俗，以优良党风引领社风民风。要继续纠治享乐主义、奢靡之风，把握作风建设地区性、行业性、阶段性特点，抓住普遍发生、反复出现的问题深化整治，推进作风建设常态化长效化。","摘编自《人民日报》（2025年1月8日）"]},"answerPoints":["设、组织建设，而且十分重视党的作风建设，通过树立良好形象，大大提升了党的凝聚力、号召力和战斗力。延安时期是中国共产党优良作风培育形成的重要历史时期。","在这个时期，毛泽东提出了“党的作风”这一概念，并以身作则，高度重视作风建设，始终保持马克思主义政党的先进性纯洁性，保持革命队伍旺盛的斗志和廉洁的作风，并在总结历史经验的基础上，形成了理论联系实际、密切联系群众、批评和自我批评三大优良作风，最终以“延安作风”打败了“西安作风”。","这也充分说明，党的作风就是党的形象，关系人心向背，关系党的生死存亡。（2)土地革命战争时期，党提出并践行了“三大纪律八项注意”。抗日战争时期，党创造性地以整风的形式，旗帜鲜明地反对主观主义、宗派主义、党八股，加强党的作风建设。在延安，党形成了“三大作风”。","党的七届二中全会提出了“两个务必”，为即将在全国执政的学发出钟，新中国成立以来，党立足于执掌全国政权所提出的党的建设新任务，始终将党的作风建设摆在突出位置。党的十八大以来，以习近平同志为核心的党中央找到了“自我革命”这个跳出历史周期率的第二个答案，从制定和落实中央八项规定开局破题，以踏石留印、抓铁有痕的力度和劲头狠抓党的作风建设。","历史和实践证明，中央八项规定精神与“延安作风”既一脉相承又与时俱进，始终保持党同人民群众的血肉联系，擦亮了作风建设的“金色名片”。作风建设“必须常抓不懈、久久为功”，这是由党的作风建设的重要性决定的。作风建设是党的建设的永恒主题。","同时，作风上的问题具有顽固性、反复性，既要打攻坚战，又要打持久战，必须常抓不懈、久久为功，真正化风成俗，以优良党风引领社风民风。当前，要锲而不舍落实中央八项规定精神，推进作风建设常态化长效化，以优良作风凝心聚力、真抓实干，不断开创事业发展新局面。"],"explanation":"设、组织建设，而且十分重视党的作风建设，通过树立良好形象，大大提升了党的凝聚力、号召力\n和战斗力。延安时期是中国共产党优良作风培育形成的重要历史时期。在这个时期，毛泽东提\n出了“党的作风”这一概念，并以身作则，高度重视作风建设，始终保持马克思主义政党的先进性\n纯洁性，保持革命队伍旺盛的斗志和廉洁的作风，并在总结历史经验的基础上，形成了理论联系\n实际、密切联系群众、批评和自我批评三大优良作风，最终以“延安作风”打败了“西安作风”。这\n也充分说明，党的作风就是党的形象，关系人心向背，关系党的生死存亡。\n（2)土地革命战争时期，党提出并践行了“三大纪律八项注意”。抗日战争时期，党创造性地\n以整风的形式，旗帜鲜明地反对主观主义、宗派主义、党八股，加强党的作风建设。在延安，党形\n成了“三大作风”。党的七届二中全会提出了“两个务必”，为即将在全国执政的学发出钟，新\n中国成立以来，党立足于执掌全国政权所提出的党的建设新任务，始终将党的作风建设摆在突\n出位置。党的十八大以来，以习近平同志为核心的党中央找到了“自我革命”这个跳出历史周期\n率的第二个答案，从制定和落实中央八项规定开局破题，以踏石留印、抓铁有痕的力度和劲头狠\n抓党的作风建设。历史和实践证明，中央八项规定精神与“延安作风”既一脉相承又与时俱进，\n始终保持党同人民群众的血肉联系，擦亮了作风建设的“金色名片”。\n作风建设“必须常抓不懈、久久为功”，这是由党的作风建设的重要性决定的。作风建设是\n党的建设的永恒主题。同时，作风上的问题具有顽固性、反复性，既要打攻坚战，又要打持久战，\n必须常抓不懈、久久为功，真正化风成俗，以优良党风引领社风民风。当前，要锲而不舍落实中\n央八项规定精神，推进作风建设常态化长效化，以优良作风凝心聚力、真抓实干，不断开创事业\n发展新局面。","tags":["肖四","第4套","材料分析题"]},
  {"id":"q-shizheng-1","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年8月31日至9月1日，上海合作组织成员国元首理事会第二十五次会议在天津举行。这次峰会是上海合作组织迄今规模最大的一次峰会，是谋划高质量发展的一次峰会，是指引人类前进方向的一次峰会，是成果最为丰硕的一次峰会。上合组织天津峰会的最大亮点是","options":[{"key":"A","text":"习近平主席提出全球治理倡议"},{"key":"B","text":"落地了“四个安全中心”"},{"key":"C","text":"决定将上合组织观察员国和对话伙伴合并为统一的“上合组织伙伴”"},{"key":"D","text":"做出了成立上合组织开发银行的政治决定"}],"answerKey":"A","explanation":"上合组织天津峰会的最大亮点是习近平主席提出全球治理倡议，A正确。B、C、D也是这\n次会议取得的八大成果的内容，不符合题意。","tags":["肖四","第1套","单选题"]},
  {"id":"q-shizheng-2","type":"multi","module":"形势与政策","difficulty":2,"stem":"2021年一2025年的“十四五”时期，我国发展历程极不寻常、极不平凡。面对错综复杂的国际形势和艰巨繁重的国内改革发展稳定任务，以习近平同志为核心的党中央团结带领全党全国各族人民,迎难而上、砺前行,经受住世纪疫情严重冲击,有效应对一系列重大风险挑战，推动党和国家事业取得新的重大成就。“十四五\"时期我国发展取得的重大成就主要有","options":[{"key":"A","text":"我国经济实力、科技实力、综合国力跃上新台阶"},{"key":"B","text":"人均国内生产总值达到中等发达国家水平"},{"key":"C","text":"中国式现代化迈出新的坚实步伐"},{"key":"D","text":"第二个百年奋斗目标新征程实现良好开局"}],"answerKeys":["A","C","D"],"explanation":"2021年一2025年的“十四五”时期，我国发展历程极不寻常、极不平凡。面对错综复杂的\n国际形势和艰巨繁重的国内改革发展稳定任务，以习近平同志为核心的党中央团结带领全党全\n国各族人民，迎难而上、砥砺前行，经受住世纪疫情严重冲击，有效应对一系列重大风险挑战，推\n动党和国家事业取得新的重大成就。我国经济实力、科技实力、综合国力跃上新台阶，中国式现\n代化迈出新的坚实步伐，第二个百年奋斗目标新征程实现良好开局。A、C、D正确。人均国内生\n产总值达到中等发达国家水平，是2035年我国基本实现社会主义现代化的一个重要标志性指\n标。B错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-shizheng-3","type":"multi","module":"形势与政策","difficulty":2,"stem":"2025年11月21日，中国常驻联合国代表傅聪致函联合国秘书长古特雷斯，就日本首相高市早苗涉华错误言行阐明中国政府立场。傅聪在致函中表示，日本首相高市早苗在国会答辩时公然发表涉台露骨挑言论。这是1945年日本战败以来日方领导人首次在正式场合鼓吹所谓“台湾有事就是日本有事”并与行使集体自卫权相关联，首次在台湾问题上表达试图武装介人的野心，首次对中国发出武力威胁，公然挑战中方核心利益。高市早苗有关言论","options":[{"key":"A","text":"严重违反国际法和国际关系基本准则"},{"key":"B","text":"严重破坏战后国际秩序"},{"key":"C","text":"是对14亿多中国人民和曾遭受日本侵略的亚洲国家人民的公然挑"},{"key":"D","text":"极其错误、极为危险，性质影响极其恶劣答问题。"}],"answerKeys":["A","B","C","D"],"explanation":"市早苗涉华错误言行阐明中国政府立场。傅聪在致函中表示，日本首相高市早苗在国会答辩时\n公然发表涉台露骨挑言论。这是1945年日本战败以来日方领导人首次在正式场合鼓吹所谓\n台湾有事就是日本有事”并与行使集体自卫权相关联，首次在台湾问题上表达试图武装介人的\n野心，首次对中国发出武力威胁，公然挑战中方核心利益。有关言论极其错误、极为危险，性质\n影响极其恶劣。在中方多次严正交涉和强烈抗议后，日方仍不思悔改，拒不撤回错误言论。中\n方对此强烈不满、坚决反对。\n后国际秩序，是对14亿多中国人民和曾遭受日本侵略的亚洲国家人民的公然挑。台湾是中国\n的神圣领土，如何解决台湾问题是中国人自己的事，不容任何外来干涉。如日方胆敢武力介人\n台海局势，将构成侵略行为，中方将坚决行使《联合国宪章》和国际法赋予的自卫权，坚定捍卫国\n家主权和领土完整。作为二战战败国，日方必须深刻反省历史罪责，恪守对于台湾问题做出的\n政治承诺,立即停止挑越线，收回错误言论。该函将作为联合国大会正式文件，向全体会员国\n散发。A、B、C、D全选。","tags":["肖四","第1套","多选题"]},
  {"id":"q-shizheng-4","type":"material","module":"形势与政策","difficulty":3,"stem":"结合材料回答问题：（2）“四大全球倡议为应对世界变局、破解紧迫难题贡献了中国智慧和方案”，这体现了中国怎样的外交理念和世界情怀一、","material":{"title":"材料","paragraphs":["材料 1 针对记者问及全球治理侣议对解决全球性问题和挑战的现实意义，王毅说，今年是世界反法西斯战争胜利和联合国成立80周年。在这个承前启后的特殊历史年份，习近平主席郑重提出全球治理侣议，为加强和完善全球治理进一步贡献中国智慧、提出中国方案。王毅说，全球治理倡议正逢其时。当前，百年变局加速演进，地区动荡频发、经济发展受阻、逆全球化抬头、规则法治缺位,治理赤字不断加剧。在此背景下,构建什么样的全球治理体系、如何改革完善全球治理体系，日益成为国际社会高度关注的重大命题。今年可谓全球治理的“大年”。习近平主席此时提出全球治理倡议，十分及时，十分关键，顺应了各国人民的普遍愿望，符合当今世界的紧迫需求，一经提出就得到与会各国领导人和国际组织的欢迎和支持，也必将得到国际社会的广泛认同。王毅说，全球治理倡议指引方向。习近平主席在讲话中明确了倡议的核心理念，即奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向。这五大理念阐明了改革完善全球治理需要遵循的原则、方法和路径。倡议的这些精神内涵同联合国宪章宗旨和原则一脉相承，旨在坚定支持联合国在国际事务中发挥核心作用，推动各国依托联合国等多边机制，参与全球治理体系改革与建设，使之与时俱进，更有效应对时代挑战。","摘编自《人民日报》（2025年9月2日）","材料2 近期，习近平主席提出全球治理侣议，强调奉行主权平等、遵守国际法治、践行多边主义、侣导以人为本、注重行动导向，为破解全球治理赤字提供了中国方案。全球治理倡议和全球发展倡议、全球安全倡议、全球文明倡议是新时代中国为世界提供的系统性国际公共产品。当前，130多个国家和国际组织参与全球发展倡议的落实机制，全球安全倡议已得到130多个国家和国际地区组织支持，全球文明倡议多次被写入联合国决议及各种双多边文件，全球治理倡议一经提出就得到各国积极响应，近期更是在第八十届联大一般性辩论期间得到多方赞誉和支持。四大全球倡议为应对世界变局、破解紧迫难题贡献了中国智慧和方案，为构建人类命运共同体提供战略引领。","摘编自《人民日报》（2025年10月2日）"]},"answerPoints":["劫痛定思痛、摆脱丛林法则的历史尝试，开启了构建战后国际秩序、追求和平发展的不凡征程。80年来，联合国为维护和平、促进发展、改善民生发挥了不可替代的作用，是当今世界最具普遍性、代表性和权威性的政府间国际组织，是集体安全机制的核心、践行多边主义的核心平台。联合国宪章倡导主权平等、不干涉内政、和平解决国际争端等原则。","在联合国，国家不分大小强弱，都是平等一员，拥有同等的发声机会，能够公平参与国际规则谈判、共享可持续发展成果。奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向，全球治理倡议的五大核心理念阐明了改革完善全球治理需要遵循的原则、方法和路径，为新形势下全球治理变革指明了前进方向。","全球治理倡议的这些精神内涵同联合国宪章宗旨和原则一脉相承，同时旨在增强现行国际体系和国际机制的执行力、有效性，使之更符合变化的形势，更及时有效应对各种全球性挑战，更好服务各国特别是发展中国家利益。（2)四大全球倡议集中体现了中国致力于构建人类命运共同体的外交理念和以天下之利为利的世界情怀。","四大全球倡议，分别从发展、安全、文明、治理四个维度，为破解和平、发展、安全、治理“四大赤字”提供了系统性方案，为变乱交织的世界注人了稳定性和确定性，充分彰显了中国作为负责任大国在国际事务中为人类谋进步、为世界谋大同的历史担当。","四大全球倡议是构建人类命运共同体的战略引领，各有侧重、相辅相成、相得益彰，形成以发展促繁荣、以安全保稳定、以文明增互信、以治理求公正的有机整体，共同为人类命运共同体提供重要依托。"],"explanation":"劫痛定思痛、摆脱丛林法则的历史尝试，开启了构建战后国际秩序、追求和平发展的不凡征程。\n80年来，联合国为维护和平、促进发展、改善民生发挥了不可替代的作用，是当今世界最具普遍\n性、代表性和权威性的政府间国际组织，是集体安全机制的核心、践行多边主义的核心平台。联\n合国宪章倡导主权平等、不干涉内政、和平解决国际争端等原则。在联合国，国家不分大小强\n弱，都是平等一员，拥有同等的发声机会，能够公平参与国际规则谈判、共享可持续发展成果。\n奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向，全球治理倡议\n的五大核心理念阐明了改革完善全球治理需要遵循的原则、方法和路径，为新形势下全球治理\n变革指明了前进方向。全球治理倡议的这些精神内涵同联合国宪章宗旨和原则一脉相承，同时\n旨在增强现行国际体系和国际机制的执行力、有效性，使之更符合变化的形势，更及时有效应对\n各种全球性挑战，更好服务各国特别是发展中国家利益。\n（2)四大全球倡议集中体现了中国致力于构建人类命运共同体的外交理念和以天下之利为\n利的世界情怀。四大全球倡议，分别从发展、安全、文明、治理四个维度，为破解和平、发展、安\n全、治理“四大赤字”提供了系统性方案，为变乱交织的世界注人了稳定性和确定性，充分彰显了\n中国作为负责任大国在国际事务中为人类谋进步、为世界谋大同的历史担当。四大全球倡议是\n构建人类命运共同体的战略引领，各有侧重、相辅相成、相得益彰，形成以发展促繁荣、以安全保\n稳定、以文明增互信、以治理求公正的有机整体，共同为人类命运共同体提供重要依托。","tags":["肖四","第1套","材料分析题"]},
  {"id":"q-shizheng-5","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年8月，习近平率中央代表团出席西藏自治区成立60周年庆祝活动，听取西藏自治区党委和政府工作汇报并发表重要讲话。习近平强调，治藏稳藏兴藏，首先是要","options":[{"key":"A","text":"保持西藏的政治安定、社会稳定、民族团结、宗教和顺"},{"key":"B","text":"因地制宜发展高原特色优势产业，特别是特色农牧业和清洁能源产业"},{"key":"C","text":"加强生态文明建设，守护好“世界屋脊”和“亚洲水塔”"},{"key":"D","text":"认真落实全面从严治党政治责任，努力营造风清气正的政治生态"}],"answerKey":"A","explanation":"习近平强调，治藏稳藏兴藏，首先是要保持西藏的政治安定、社会稳定、民族团结、宗教和\n顺。A正确。B、C、D错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-shizheng-6","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年11月22日,二十国集团(G20)领导人第二十次峰会在南非约翰内斯堡开幕,这是G20领导人峰会首次在非洲大陆举行。峰会顶住美国压力于开幕当日通过《二十国集团领导人约翰内斯堡峰会宜言》，这是G20峰会首次于开幕当日通过联合宣言。宣言的顺利通过表明各国正以实际行动加强协作、支持多边主义。G20约翰内斯堡峰会的主题是","options":[{"key":"A","text":"“建设可持续的明天”"},{"key":"B","text":"“一个地球、一个家园、一个未来”"},{"key":"C","text":"“构建公正的世界和可持续的星球”"},{"key":"D","text":"“团结、平等、可持续”"}],"answerKey":"D","explanation":"为贯彻G20成立初衷,南非将本届峰会的主题设定为“团结、平等、可持续”。D正确。\n“建设可持续的明天”是2025年10月30日至11月1日在韩国举行的亚太经合组织第三十二次\n团领导人第十八次峰会的主题；“构建公正的世界和可持续的星球”是2024年在巴西举行的二\n十国集团领导人第十九次峰会的主题。A、B、C错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-shizheng-7","type":"multi","module":"形势与政策","difficulty":2,"stem":"2025年3月12日，联合国秘书长古特雷斯在联合国总部提出“联合国80周年倡议”，宣布正式启动对包括140个实体的联合国全系统改革计划。改革的主要方面是","options":[{"key":"A","text":"效率和改进"},{"key":"B","text":"扩大安理会常任理事国"},{"key":"C","text":"任务执行情况审查"},{"key":"D","text":"结构和计划调整答问题。"}],"answerKeys":["A","C","D"],"explanation":"2025年是联合国成立80周年，联合国秘书长古特雷斯提出“联合国80周年倡议”，正式\n启动对包括140个实体的联合国全系统进行“效率和改进”“任务执行情况审查”及“结构和计划\n调整”三方面的改革。计划中的改革包括设立共同行政平台、整合行政任务、大幅削减预算、机\n构合并和搬迁、职位裁撤、人员裁减等。A、C、D正确,B错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-shizheng-8","type":"material","module":"形势与政策","difficulty":3,"stem":"结合材料回答问题：（1）如何理解“多边主义、团结合作是解决全球性难题的正确答案”，“我们要重温联合国创立初心”？一、","material":{"title":"材料","paragraphs":["材料1 8月30日下午，国家主席习近平在天津迎宾馆会见来华出席2025年上海合作组织峰会的联合国秘书长古特雷斯。习近平指出，第二次世界大战结束前后，国际社会作出的最重要决定就是成立联合国。今年是世界反法西斯战争胜利和联合国成立80周年。历史启示我们，多边主义、团结合作是解决全球性难题的正确答案。我们要重温联合国创立初心，重申对联合国宪章宗旨和原则的承诺，推动联合国在新形势下重振权威和活力，成为各国协调行动、共同应对挑战的主要平台。中国永远是联合国可以信赖的伙伴。中方愿深化同联合国合作，支持联合国在国际事务中发挥核心作用，共同为维护世界和平、促进发展繁荣挺担当。习近平强调，在世界百年变局中，中国提供了稳定性和确定性。我们将继续以中国新发展为世界提供新机遇，通过构建人类命运共同体、践行三大全球侣议、共建“一带一路”，同各国一道创造更加美好的未来。","摘编自《人民日报》（2025年8月31日）","材料2 观察近期中国与世界交往的高光时刻，一种坚持始终清晰：面对变乱交织的国际局势，中国始终是维护和平与发展的“稳定锚”。成功举办上海合作组织成立以来规模最大的一届峰会，恰逢其时提出全球治理侣议；隆重举行中国人民抗日战争暨世界反法西斯战争胜利80周年纪念活动，携手各方铭记历史、共护和平；在金砖国家合作机制、联合国等多边平台不断推出引领合作共赢的新方案，在联合国气候变化峰会宣布中国新一轮国家自主贡献；举办全球妇女峰会，提出支持全球妇女事业发展的新主张新举措····中国不仅自身坚定走和平发展道路，更持续为世界和平发展注入确定性和正能量。习近平主席早在2014年就郑重指出：“中国走和平发展道路，不是权宜之计，更不是外交辞令，而是从历史、现实、未来的客观判断中得出的结论,是思想自信和实践自觉的有机统一。透视历史、现实与未来，不仅能读懂中国选择和平发展的深层逻辑，也能找到百年变局下国际社会应对共同挑战的正确方向。","摘编自《人民日报》（2025年10月16日）"]},"answerPoints":["机等）超越国界，单一国家无法独自应对，必须通过多边机制协同治理。多边主义与团结合作是应对全球挑战、实现共同发展的必然选择，符合世界各国人民的根本利益。","联合国成立的初心使命是维持国际和平及安全、发展国家间友好关系、促进国际合作以解决全球性问题并保障基本人权与自由，这一宗旨源于二战后国际社会对防止战争、推动合作与公平的集体诉求，并载入《联合国宪章》。这个初心使命直接根植于二战后的全球反思，旨在通过多边合作避免战争重演，并构建更公正的国际秩序。","当前，多边主义、国际法、联合国权威面临挑战，国际治理架构急需改革，重温80年前成立联合国的初心和价值理念正当其时。","中国作为联合国安理会常任理事国，始终坚定站在历史正确一边，坚定维护联合国权威，支持以联合国为核心的国际体系，以国际法为基础的国际秩序，以联合国宪章宗旨和原则为基础的国际关系基本准则，坚持并践行真正的多边主义，成为捍卫多边主义的基石。","坚持走和平发展道路，是我们党根据时代发展潮流和我国根本利益作出的战略执择，是新时代中国外交的基本原则。中国始终倡导合作共嬴，致力于做大发展蛋糕，推动高质量共建“一带一路”，推动落实全球发展倡议，不断以自身发展为世界创造机遇。","中国坚持共同、综合、合作、可持续的安全观，引领各方走对话而不对抗、结伴而不结盟、共赢而非零和的新型安全之路，全球安全倡议被誉为“实现普遍安全的希望所在”。中国坚持平等、互鉴、对话、包容的文明观，提出并带头践行全球文明倡议,推动以文明交流超越文明隔阅，以文明互鉴超越文明冲突，以文明共存超越文明优越，筑牢和平的思想根基。","中国着眼推动构建更加公正合理的全球治理体系，提出全球治理倡议，凝聚奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向的广泛共识，为世界和平发展夯实治理根基。"],"explanation":"机等）超越国界，单一国家无法独自应对，必须通过多边机制协同治理。多边主义与团结合作是\n应对全球挑战、实现共同发展的必然选择，符合世界各国人民的根本利益。\n联合国成立的初心使命是维持国际和平及安全、发展国家间友好关系、促进国际合作以解\n决全球性问题并保障基本人权与自由，这一宗旨源于二战后国际社会对防止战争、推动合作与\n公平的集体诉求，并载入《联合国宪章》。这个初心使命直接根植于二战后的全球反思，旨在通\n过多边合作避免战争重演，并构建更公正的国际秩序。\n当前，多边主义、国际法、联合国权威面临挑战，国际治理架构急需改革，重温80年前成立联\n合国的初心和价值理念正当其时。中国作为联合国安理会常任理事国，始终坚定站在历史正确\n一边，坚定维护联合国权威，支持以联合国为核心的国际体系，以国际法为基础的国际秩序，以\n联合国宪章宗旨和原则为基础的国际关系基本准则，坚持并践行真正的多边主义，成为捍卫多\n边主义的基石。\n（2）坚持走和平发展道路，是我们党根据时代发展潮流和我国根本利益作出的战略执择，是\n新时代中国外交的基本原则。\n中国始终倡导合作共嬴，致力于做大发展蛋糕，推动高质量共建“一带一路”，推动落实全球\n发展倡议，不断以自身发展为世界创造机遇。中国坚持共同、综合、合作、可持续的安全观，引领\n各方走对话而不对抗、结伴而不结盟、共赢而非零和的新型安全之路，全球安全倡议被誉为“实\n现普遍安全的希望所在”。中国坚持平等、互鉴、对话、包容的文明观，提出并带头践行全球文明\n倡议,推动以文明交流超越文明隔阅，以文明互鉴超越文明冲突，以文明共存超越文明优越，筑\n牢和平的思想根基。中国着眼推动构建更加公正合理的全球治理体系，提出全球治理倡议，凝\n聚奉行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向的广泛共识，为世\n界和平发展夯实治理根基。","tags":["肖四","第2套","材料分析题"]},
  {"id":"q-shizheng-9","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年国庆节当天，国家航天局发布了天问二号探测器在轨飞行期间获取的探测器与地球合影图像。画面中,鲜艳的五星红旗、白色的返回舱和远处蓝色的地球同框，被网友激动地形容为“宇宙级合影”。天问二号探测器于2025年5月29日在西昌卫星发射中心由长征三号乙运载火箭成功发射升空，天问二号探测器的成功发射,开启了","options":[{"key":"A","text":"小行星探测与采样返回之旅"},{"key":"B","text":"火星采样返回任务之旅"},{"key":"C","text":"月球背面采样返回之旅"},{"key":"D","text":"太阳探测“三步走”计划"}],"answerKey":"A","explanation":"2025年5月29日，行星探测工程天问二号探测器成功发射，开启了小行星探测与采样返\n回之旅。天问二号主要任务目标是对小行星2016H03进行探测、取样并返回地球，此后再对主\n带彗星311P开展科学探测。A正确。探月计划对应的是“嫦娥家族”。2024年6月25日，嫦娥\n六号返回器回到地面，实现世界首次月球背面采样返回，成功带回1935.3克月球背面样品。C\n错误。“羲和”“夸父”双星逐日，太阳探测“三步走”计划稳步推进。2021年，我国成功发射首颗\n太阳探测科学技术试验卫星“羲和号”，正式迈人空间探日时代。2022年，“夸父一号”开启探日\n之旅，成功发射并发布首批科学图像。这两颗探日卫星各有侧重，将共同提升我国在世界太阳\n物理研究领域的影响力。D错误。面向未来，我国正在实施更宏伟的深空探测任务。嫦娥七号、\n嫦娥八号将在月球南极建设月球科研站，天问三号将实施火星采样返回，天问四号将探访木星\n系。B错误。","tags":["肖四","第3套","单选题"]},
  {"id":"q-shizheng-10","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年4月8日至9日，中央周边工作会议在北京举行。会议指出，我国幅员辽阔、边界线长，周边是实现发展繁荣的重要基础、维护国家安全的重点、运筹外交全局的首要、推动构建人类命运共同体的关键。会议首次提出","options":[{"key":"A","text":"亚洲安全观"},{"key":"B","text":"亚洲安全模式"},{"key":"C","text":"亚洲命运共同体"},{"key":"D","text":"亲诚惠容周边外交理念"}],"answerKey":"B","explanation":"安全是国家生存发展之基。2014年5月，习近平在亚洲相互协作与信任措施会议第四次\n峰会上，倡导共同、综合、合作、可持续的亚洲安全观。2022年4月，习近平在博亚洲论坛年会\n开幕式上发表主旨演讲，郑重提出全球安全倡议。2025年4月召开的中央周边工作会议首次提\n出安危与共、求同存异、对话协商的亚洲安全模式,深刻把握发展与安全的辩证关系，开创了区\n域安全治理的新境界。B正确。A、C、D错误。\n点拨亚洲安全模式是携手周边国家共创美好未来的战略支撑。","tags":["肖四","第3套","单选题"]},
  {"id":"q-shizheng-11","type":"multi","module":"形势与政策","difficulty":2,"stem":"2025年11月25日，神舟二十二号飞船成功对接于空间站天和核心舱前向端口，中国载人航天工程首次应急发射任务取得圆满成功。载人航天，人命关天，我国载人飞船研发团队对安全有着近乎苛刻的要求。为了避免“万一”，研发团队提前预想了很多可能出现的问题并设计了解决方案。据专家介绍，“飞船上大约70万条计算机程序中,30%用来应对正常飞行，70%用于应对可能的故障。没有把握，我们不会让航天员上去。”研发团队预设解决方案来避免“万一”是因为","options":[{"key":"A","text":"科学研究的任务就是从根本上消除偶然性"},{"key":"B","text":"凡事从坏处准备，努力争取最好的结果"},{"key":"C","text":"可能向现实的转化完全取决于主观条件"},{"key":"D","text":"逻辑证明是探索真理、论证真理的重要方式"}],"answerKeys":["B","D"],"explanation":"底线思维是我们在认识世界和改造世界的过程中,根据我们的需要和客观的条件，划清并\n坚守底线，尽力化解风险，避免最坏结果，同时争取实现最大期望值的一种积极的思维。把握底\n线思维，就要“凡事从坏处准备，努力争取最好的结果，这样才能有备无患、遇事不慌，牢牢把握\n主动权”。B正确。所谓逻辑证明，是指运用已知的正确概念和判断，通过一定的推理，从理论\n上确定另一个判断的正确性的方法。逻辑证明是探索真理、论证真理的重要方式，是正确思维\n和表达的必要条件，也是建立科学理论体系的重要途径。D正确。探求必然性是科学研究的主\n要任务，但这绝不意味着“科学是偶然性的敌人”。相反，在科学研究、认识活动和实践活动中，\n要重视偶然性和“机遇”，并从偶然性深入必然性中，抓住机遇、发展自己。A错误。由可能向现\n实转化的过程中，既要注意转化的客观条件性，又要注意发挥人的主观能动性。可能向现实转\n化的条件，包括客观条件和主观条件。在客观条件方面，主要是区分可能与不可能、现实的可能\n与抽象的可能，集中力量去办那些具有现实可能性的事情；在主观条件方面，要充分发挥人的主\n观能动性，积极创造条件，实现可能向现实的转化。C错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-shizheng-12","type":"multi","module":"形势与政策","difficulty":2,"stem":"2025年9月9日，国务院批复同意新建黄岩岛国家级自然保护区。批复指出，有关部门和地方要严格执行《中华人民共和国自然保护区条例》和自然保护地建设管理等规定，严格落实生态环境保护责任，加强组织领导和协调配合，健全管理机构，强化对涉及自然保护区各类违法违规行为的监管执法力度，确保各项管理措施得到落实,不断提高国家级自然保护区建设和管理水平。建立黄岩岛国家级自然保护区","options":[{"key":"A","text":"是中国主权范围内的事"},{"key":"B","text":"符合中国国内法和国际法"},{"key":"C","text":"旨在保护黄岩岛的生态环境,维护黄岩岛自然生态系统多样性、稳定性、持续性"},{"key":"D","text":"充分体现中国作为负责任大国，积极保护生态环境，推动实现可持续发展的使命担当"}],"answerKeys":["A","B","C","D"],"explanation":"22025年9月11日,外交部发言人林剑主持例行记者会时表示,黄岩岛是中国的固有领土，\n建立黄岩岛国家级自然保护区是中方主权范围内的事，旨在保护黄岩岛的生态环境，维护黄岩\n岛自然生态系统多样性、稳定性、持续性,符合中国国内法和国际法,也充分体现中方作为负责\n任大国,积极保护生态环境，推动实现可持续发展的使命担当。A、B、C、D全选。","tags":["肖四","第3套","多选题"]},
  {"id":"q-shizheng-13","type":"multi","module":"形势与政策","difficulty":2,"stem":"当地时间2025年11月1日，习近平在韩国庆州出席亚太经合组织第三十二次领导人非正式会议第二阶段会议，并发表题为《共同开创可持续的美好明天》的重要讲话。习近平指出，亚太各经济体应该加强互利合作，把握新机遇，应对新挑战，共同开创可持续的美好明天。为此，习近平提出的建议是","options":[{"key":"A","text":"强化数智赋能，塑造亚太创新发展新优势"},{"key":"B","text":"坚持绿色低碳，打造亚太可持续发展新范式"},{"key":"C","text":"落实普惠共享，展现亚太包容发展新气象"},{"key":"D","text":"推进医疗合作，应对亚太人口结构新变化答问题。"}],"answerKeys":["A","B","C"],"explanation":"习近平在《共同开创可持续的美好明天》的重要讲话中指出，当前,新一轮科技革命和产业\n变革深入发展,为人类社会开辟了新前景。同时，世界经济增长动能不足，全球发展赤字扩大，\n气候变化、粮食和能源安全等挑战加剧。亚太各经济体应该加强互利合作,把握新机遇，应对新\n挑战，共同开创可持续的美好明天。习近平提出3点建议：一是强化数智赋能，塑造亚太创新发\n展新优势。二是坚持绿色低碳,打造亚太可持续发展新范式。三是落实普惠共享,展现亚太包\n容发展新气象。A、BC正确。2025年,韩国提出应对人口结构变化合作倡议,这有助于促进亚\n太包容发展。中国将加快完善覆盖全人群、全生命周期的人口服务体系，大力发展银发经济，促\n进人口高质量发展。中方将推动落实人工智能助力卫生健康、提升女性数字素养等倡议，让更\n多合作成果惠及亚太地区人民。D错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-shizheng-14","type":"material","module":"形势与政策","difficulty":3,"stem":"结合材料回答问题：（1）为什么说“中国是世界绿色发展的坚定行动派、重要贡献者”？（2）结合构建人类命运共同体理念和行动，说明中国作为“赋能型大国”如何在世界百年变局中“提供了稳定性和确定性”。一、","material":{"title":"材料","paragraphs":["材料1 今年是《巴黎协定》达成10周年。10年来，全球气候治理虽然历经风雨，但绿色低碳发展终成时代潮流。今年也是联合国成立80周年。当前，世界百年变局加速演进，人类社会走到新的十字路口。尽管个别大国热衰于单边主义、保护主义，对国际规则和国际秩序造成严重冲击，但历史总会在曲折中前进。只要我们坚定信心，加强团结合作，就一定能冲破逆流，推动全球气候治理和世界一切进步事业行稳致远。人与自然和谐共生是中国式现代化的鲜明特点。中国是世界绿色发展的坚定行动派、重要贡献者。","摘自习近平《共迎时代挑战携手推进全球气候治理一一在气候和公正转型领导人峰会上的致辞》","材料2 今年是“绿水青山就是金山银山”的“两山”理念提出20年。20年来，“两山”理念引领中国以敢为人先的绿色创新实践，创造了举世瞩目的生态奇迹和发展奇迹；这一理念跨越山海，助力广大发展中国家共同书写全球生态文明建设新篇章。国际社会普遍认为，“两山”理念为兼顾生态保护与经济发展提供了创新理念和实践路径，既造福了中国，也造福了世在非洲，中国发起的“以竹代塑”不仅有效减少塑料污染，也让竹子成为当地民众眼中的“绿色金子”；在太平洋岛国，来自中国的菌草技术培训项目帮助许多当地民众摆脱贫困，防止水土流失….“两山”理念不仅深刻改变中国，也广泛影响世界。这一理念为广大发展中国家谋求自身跨越式发展、实现现代化进程提供了重要借鉴，为全球环境治理提供了新路径、新选择。","摘编自《人民日报》（2025年8月16日）","材料3 8月30日下午，国家主席习近平在天津迎宾馆会见来华出席2025年上海合作组织峰会的联合国秘书长古特雷斯。习近平强调，在世界百年变局中，中国提供了稳定性和确定性。我们将继续以中国新发展为世界提供新机遇，通过构建人类命运共同体、践行三大全球侣议、共建“一带一路”，同各国一道创造更加美好的未来。","摘编自《人民日报》（2025年8月31日）","材料4 当前，单边主义破坏国际秩序，保护主义损害全球经济，导致国际社会对世界和平发展前景的忧虑增加。动荡的世界迫切需要稳定性力量和建设性力量。不久前,有外国学者将中国称为“赋能型大国”。“赋能型大国”生动诠释了中国始终秉持构建人类命运共同体理念，坚持提供国际公共产品，以实际行动维护世界和平、促进共同发展的大国担当。在中国阔步走在以中国式现代化推进民族复兴伟业的进程中，处处展现出“赋能”的特点。中国式现代化以构建人类命运共同体为本质要求，决定了中国始终高举和平、发展、合作、共赢旗帜。澳大利亚昆士兰科技大学客座教授鲍韶山指出，在世界多极化的时代，中国式现代化给出了唯一的确定答案：要做一个赋能者一一通过去中心化的、均衡的全球经济发展来赋能民族复兴和积极和平。","摘编自《人民日报》（2025年2月17日）"]},"answerPoints":["家。近些年来，我国站在对人类文明负责的高度，积极参与国际合作和全球治理，提出共建地球生命共同体，作出碳达峰碳中和的庄严承诺并付诸实施，深人推进应对气候变化、海洋污染治理、生物多样性保护等领域国际合作，承担大国责任，展现大国担当，实现了由参与者到引领者的重大转变。","在全球气候治理的关键时刻，中国宣布新一轮国家自主贡献，为遭遇困境的全球气学回应生态文明世界之问，为世界各国处理发展与保护的关系提供了中国方案，广泛影响(2)构建人类命运共同体，就是要携手世界各国人民共同建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。中国不仅是这一理念的倡导者，更是行动派。","中国坚持真正的多边主义，以共商共建共享赋能全球治理。中国提出人类命运共同体理念和全球发展倡议、全球安全倡议、全球文明倡议，全球治理倡议，为全球治理提供了中国方案。中国是世界经济增长的主要稳定器和动力源。中国通过自身经济的持续健康发展，为全球各国提供了广阔的市场机会、丰富的产品和宝贵的投资机会。","中国主动扩大对外开放，连续缩减外资准入负面清单，高质量举办中国国际进口博览会，主动扩大优质产品与服务进口，以实际行动向世界分享中国市场机遇。当今世界变乱交织，确定性、稳定性成为全球稀缺资源。","今天的中国坚定做“赋能型大国”，坚持做世界和平的建设者、全球发展的贡献者、国际秩序的维护者，积极践行四大全球倡议，推动构建人类命运共同体，将继续以自身发展和对外政策的确定性为全球增添稳定性。（注：关于中国“赋能”的角度有很多，比如开放共享、技术普惠、共建“一带一路”、推进绿色国际合作等。本题答案给出了几个重点角度，其他角度考生可自由发挥）"],"explanation":"家。近些年来，我国站在对人类文明负责的高度，积极参与国际合作和全球治理，提出共建地球\n生命共同体，作出碳达峰碳中和的庄严承诺并付诸实施，深人推进应对气候变化、海洋污染治\n理、生物多样性保护等领域国际合作，承担大国责任，展现大国担当，实现了由参与者到引领者\n的重大转变。在全球气候治理的关键时刻，中国宣布新一轮国家自主贡献，为遭遇困境的全球气\n学回应生态文明世界之问，为世界各国处理发展与保护的关系提供了中国方案，广泛影响\n(2)构建人类命运共同体，就是要携手世界各国人民共同建设持久和平、普遍安全、共同繁\n荣、开放包容、清洁美丽的世界。中国不仅是这一理念的倡导者，更是行动派。\n中国坚持真正的多边主义，以共商共建共享赋能全球治理。中国提出人类命运共同体理念\n和全球发展倡议、全球安全倡议、全球文明倡议，全球治理倡议，为全球治理提供了中国方案。\n中国是世界经济增长的主要稳定器和动力源。中国通过自身经济的持续健康发展，为全球各国\n提供了广阔的市场机会、丰富的产品和宝贵的投资机会。中国主动扩大对外开放，连续缩减外\n资准入负面清单，高质量举办中国国际进口博览会，主动扩大优质产品与服务进口，以实际行动\n向世界分享中国市场机遇。\n当今世界变乱交织，确定性、稳定性成为全球稀缺资源。今天的中国坚定做“赋能型大国”，\n坚持做世界和平的建设者、全球发展的贡献者、国际秩序的维护者，积极践行四大全球倡议，推\n动构建人类命运共同体，将继续以自身发展和对外政策的确定性为全球增添稳定性。\n（注：关于中国“赋能”的角度有很多，比如开放共享、技术普惠、共建“一带一路”、\n推进绿色国际合作等。本题答案给出了几个重点角度，其他角度考生可自由发挥）","tags":["肖四","第3套","材料分析题"]},
  {"id":"q-shizheng-15","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年，是“十四五”规划收官之年，也是“十五五”规划谋篇布局之年。习近平曾经对“十五五”规划编制工作作出重要指示，要求“把顶层设计和问计于民统一起来，加强调研论证，广泛凝聚共识”。“问计于民”在“十五五”规划编制工作中具有重要作用,其哲学依据在于","options":[{"key":"A","text":"人民群众的意愿是检验认识真理性的标准"},{"key":"B","text":"社会发展的客观过程由每一个参与历史活动的个人的主观意志所决定"},{"key":"C","text":"人民群众的实践是正确认识的来源"},{"key":"D","text":"满足人民群众的需求是历史发展的根本动力"}],"answerKey":"C","explanation":"C正确。实践是检验真理的唯一标准，A错误。人们的历史选择活动必须遵循社会发展的客观规律，而且参与历史活动的个人不一定都属于人民群众的范畴，B错误。社会基本矛盾是历史发展的根本动力，D错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shizheng-16","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年11月5日，福建舰人列授旗仪式在海南三亚某军港举行，习近平出席福建舰人列授旗仪式并登舰视察。福建舰是我国第一艘","options":[{"key":"A","text":"核动力航空母舰"},{"key":"B","text":"直升机航空母舰"},{"key":"C","text":"大型两栖作战舰船"},{"key":"D","text":"电磁弹射型航空母舰"}],"answerKey":"D","explanation":"2025.年11月5日，我国第一艘电磁弹射型航空母舰福建舰人列授旗仪式在海南三亚某军\n港举行。习近平出席入列授旗仪式并登舰视察。D正确。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shizheng-17","type":"choice","module":"形势与政策","difficulty":1,"stem":"2025年6月16日至18日，习近平应邀赴哈萨克斯坦出席第二届中国一中亚峰会。这是2025年我国对中亚地区最重大外交行动，务实高效，影响深远。第二届中国一中亚峰会最突出的亮点是","options":[{"key":"A","text":"习近平主席宣布中国一中亚精神”"},{"key":"B","text":"六国元首共同签署“永久睦邻友好合作条约”"},{"key":"C","text":"六国元首共同宣布2025至2026年为“中国中亚合作高质量发展年”"},{"key":"D","text":"六国元首共同签署《第二届中国一中亚峰会阿斯塔纳宣言》"}],"answerKey":"A","explanation":"2025年6月16日至18日，习近平应邀赴哈萨克斯坦出席第二届中国一中亚峰会。这是\n2025年我国对中亚地区最重大外交行动，务实高效，影响深远。本届峰会最突出的亮点是习近\n平主席宣布“中国一中亚精神”。A正确。本届峰会最鲜明的主题是六国元首共同宣布2025至\n2026年为“中国中亚合作高质量发展年”。习近平主席同中亚五国元首见证签署高质量共建\n“一带一路”行动计划，这是中国首次同周边单一区域内所有国家整体签订共建“一带一路”合作\n文件，从战略高度和区域层面统筹推进合作，让中亚作为共建“一带一路”示范区的成色更足，动\n力更强。本届峰会最重大的创举是六国元首共同签署“永久睦邻友好合作条约”，以法律形式将\n世代友好的原则固定下来，这是六国关系史上新的里程碑，功在当代、利在千秋。B、C、D错误。","tags":["肖四","第4套","单选题"]},
  {"id":"q-shizheng-18","type":"multi","module":"形势与政策","difficulty":2,"stem":"第十五届全国运动会（简称“十五运会”）于2025年11月21日落下惟幕。“十五运会”不仅是一场体育盛会，更是粤港澳同心筑梦的生动体现。港澳各界认为，“十五运会”的闭幕不是句号，而是粤港澳大湾区融合发展向前推进的薪新起点。“十五运会”是","options":[{"key":"A","text":"中央支持香港澳门融人国家发展大局、深化粤港澳大湾区融合发展的生动实践"},{"key":"B","text":"粤港澳三地携手同心、演绎融合发展的经典之作"},{"key":"C","text":"“一国两制”实践进人新阶段、港澳履行贡献国家使命的重要体现"},{"key":"D","text":"一座既连通三地基础设施、更促进民心相通的桥梁"}],"answerKeys":["A","B","C","D"],"explanation":"“十五运会”于2025年11月21日落下惟幕。多位港澳各界代表人士表示，“十五运会”的\n闭幕不是句号，而是粤港澳大湾区融合发展向前推进的崭新起点。“十五运会”是中央支持香港\n澳门融入国家发展大局、深化粤港澳大湾区融合发展的生动实践，是粤港澳三地携手同心、演绎\n融合发展的经典之作，也是“一国两制”实践进入新阶段、港澳履行贡献国家使命的重要体现。\n十五运会”由粤港澳三地联合圆满承办，在中国体育史上具有开创性意义。本届全运会就像一\n座桥梁，既连通三地基础设施，更促进民心相通。A、B、C、D全选。","tags":["肖四","第4套","多选题"]},
  {"id":"q-shizheng-19","type":"multi","module":"形势与政策","difficulty":2,"stem":"在巴西贝伦举行的《联合国气候变化框架公约》第三十次缔约方大会（COP30）经过“加时”后于2025年11月22日闭幕。大会达成名为《全球动员团结协作应对气候变化挑战》的政治文件，为《巴黎协定》持续落地提供了具体路径。194个缔约方一致承诺加速行动，展现了各方合作推进绿色低碳转型的决心。中国坚持多边主义，推动大会取得了多项成果，包括","options":[{"key":"A","text":"坚持共同但有区别的责任原则，维护《巴黎协定》的制度安排，特别是国家自主贡献制度"},{"key":"B","text":"气候多边进程中首次纳入了反对单边措施的相关机制"},{"key":"C","text":"建立了公正转型的工作机制"},{"key":"D","text":"与其他发展中国家共同努力，推动发达国家增加对发展中国家适应资金的支持答问题。"}],"answerKeys":["A","B","C","D"],"explanation":"COP30O中国代表团团长、生态环境部副部长李高表示，中国坚持多边主义，推动大会取得\n了多项成果，其中包括坚持共同但有区别的责任原则，维护《巴黎协定》的制度安排，特别是国家\n自主贡献制度；气候多边进程中首次纳入了反对单边措施的相关机制；建立了公正转型的工作\n机制。中国还与其他发展中国家共同努力，推动发达国家增加对发展中国家适应资金的支持，\n为大会取得积极成果作出了重要贡献。A、B、C、D全选。","tags":["肖四","第4套","多选题"]},
  {"id":"q-sixiu-3","type":"choice","module":"思想道德与法治","difficulty":1,"stem":"法律权利是指由一定的社会物质生活条件所制约的行为自由，是法律所允许的权利人为了满足自己的利益而采取的、由其他人的法律义务所保障的法律手段。法律权利区别于其他权利的根本所在是","options":[{"key":"A","text":"受社会物质生活条件的制约"},{"key":"B","text":"由国家强制力保障其实现"},{"key":"C","text":"源于现实需要"},{"key":"D","text":"随着历史的发展变化而变化"}],"answerKey":"B","explanation":"法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性。由国家强制力\n保障其实现,这是法律权利区别于其他权利的根本所在。B正确，A、C、D都不符合题意。","tags":["肖四","第1套","单选题"]},
  {"id":"q-sixiu-4","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"社会主义核心价值观具有超越以往一切社会核心价值观的先进性。社会主义核心价值观","options":[{"key":"A","text":"体现社会主义的本质属性"},{"key":"B","text":"扎根中华优秀传统文化土壤"},{"key":"C","text":"吸纳世界文明有益成果"},{"key":"D","text":"是反映人类社会发展进步的价值理念"}],"answerKeys":["A","B","C","D"],"explanation":"社会主义核心价值观体现了社会主义意识形态的本质要求，体现了社会主义制度在思想\n精神层面的质的规定性，以其先进性、人民性、真实性站在人类道义制高点上，彰显出独特而强\n大的价值观优势。社会主义核心价值观具有超越以往一切社会核心价值观的先进性，它集中体\n现了社会主义的本质属性，扎根于中华优秀传统文化的土壤，吸收借鉴了一切人类优秀文化的\n先进价值，是反映人类社会发展进步的价值理念。A、B、C、D全选。","tags":["肖四","第1套","多选题"]},
  {"id":"q-sixiu-5","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"习近平总书记强调：“改革和法治如鸟之两翼、车之两轮。”改革的“破”和“变”，与法治的“立”和“稳”，只有相辅相成才能相得益彰。耕好改革“试验田”，需要把在法治轨道上推进改革和在改革进程中完善法治有机结合起来，发挥好立法引导、推动、规范、保障改革的“稳定器”作用。为此,要做到","options":[{"key":"A","text":"立法主动适应改革需要，确保改革于法有据"},{"key":"B","text":"实践证明行之有效的举措和经验，应及时上升为法律法规"},{"key":"C","text":"对不适应改革要求的现行法律法规，能修改的则及时修改，宜废止的则及时废止"},{"key":"D","text":"改革创新要大胆试，大胆闯，相关立法活动不受法定程序限制"}],"answerKeys":["A","B","C"],"explanation":"耕好改革“试验田”，需要把在法治轨道上推进改革和在改革进程中完善法治有机结合起\n来，发挥好立法引导、推动、规范、保障改革的“稳定器”作用。立法主动适应改革需要，确保改革\n于法有据，改革创新大胆试、大胆闯、自主改就更有底气。实践证明行之有效的举措和经验，也\n应及时上升为法律法规。耕好改革“试验田”，立法工作除了要做好“加法”，还要做好“减法”。\n对不适应改革要求的现行法律法规，能修改的则及时修改，宜废止的则及时废止。防止不合时\n宜的法规条款束缚改革步伐、迟滞改革进程，有助于增强改革决心、排除改革阻力、巩固改革成\n果。A、B、C正确。我国立法贯彻公正、公平、公开原则，坚持科学立法、民主立法、依法立法，表\n达人民的共同意志和诉求。立法活动必须遵循法定程序。就全国人民代表大会的立法程序而\n言，大体包括法律案的提出、法律案的审议、法律案的表决和法律的公布四个环节。D错误。","tags":["肖四","第1套","多选题"]},
  {"id":"q-sixiu-6","type":"material","module":"思想道德与法治","difficulty":3,"stem":"结合材料回答问题：（1）如何理解“对于青年人而言，他们寻找英烈、致敬英烈的过程，实际上也是一次精神层面的自我洗礼”？（2）新时代青年如何“把个人奋斗同国家前途命运紧紧联系在一起，跑好历史的接力棒，在推进中国式现代化的宽广舞台上绽放绚丽的青春光彩”？（或：最具创新动力的青年，如何在大有可为的时代大有作为？）","material":{"title":"材料","paragraphs":["材料 1 要结合党史宣传教育，讲好老一辈无产阶级革命家的故事，教育引导广大千部群众特别是青少年传承红色基因、廣续红色血脉，永远听党话、跟党走。","摘编习近平2025年11月7日在广东考察时的讲话","材料2 不久前，山东济南历城革命烈士陵园内，73·个曾被标注为“无名”的墓碑，终于刻上了烈士的姓名。无名烈士得以有名，背后是山东第一医科大学“提灯者”英烈回乡团队志愿者的不懈努力。从打开棺到整理遗骸,从提取DNA到比对数据，从开办讲座到制作短视频…这群平均年龄28岁的志愿者，用自己的专业和热情，让英雄有名，让岁月有声。据统计，我国登记在册的196万余名革命烈士中，仅有55.9万名有明确安葬地。这些烈士都曾是一个个鲜活的生命，他们也有儿女情长，也有悲欢离合。他们以坚定的信仰信念、炽烈的家国情怀，书写了一幅幅激越沉雄的历史画卷。为烈士确认身份、找到亲人，让他们从“无名”到“有名”、从“有名”到“留名”，既是对英烈的崇高致敬，也是对其亲属最好的慰藉。对于青年人而言，他们寻找英烈、致敬英烈的过程，实际上也是一次精神层面的自我洗礼。","摘编自《人民日报》（2025年5月6日）","材料3 “人工智能是年轻的事业，也是年轻人的事业。”4月29日，习近平总书记在上海考察时勉励年轻一代，“要怀爱国之心、立报国之志、增强国之能，把个人奋斗同国家前途命运紧紧联系在一起，跑好历史的接力棒，在推进中国式现代化的宽广舞台上绽放绚丽的青春光彩”。人工智能成为发展的关键变量，新一轮科技革命和产业变革给出了历史性机遇。向来得风气之先、善于把握时代机遇的青年人，大有可为，当大有作为。青年是常为新的，最具创新热情，最具创新动力。纵观文明长河，“自古英雄出少年”，是人类社会的经验总结也是深切期许。没有谁比青年更愿意、更善于创新创造。平均年龄不到30岁的青年突击队，自主研发的“天枢”大模型，已成为化工领域“创新风向标”；平均年龄28岁的中国航信“技术极客”，研发的“千”大模型，让航班预测准确率提升40%，智能客服响应速度提高3倍，每年为行业节省超亿元成本。从基础研究到应用转化，创新力十足的青年，正在挑大梁、担重任。这份奋发有为、做先锋的精气神，正化为源源不断的朝气锐气，展现在时代进步发展的方方面面。","摘编自《在大有可为的时代大有作为》（《人民日报》2025年4月30日）"]},"answerPoints":["文明的积累，更需要精神文明的升华。传承红色基因、续红色血脉，缅怀英烈事迹、传承英烈精神，都是对世界观、人生观、价值观的洗礼，会转化成爱国情、强国志、报国行的内生动力。青年时期是价值观养成的关键阶段，青年人用自已的方式走近英雄、礼赞英雄，是唤醒人生意义的自我升华。新时代是奋斗者的时代，是呼唤英雄也创造英雄的时代。","英雄辈出，党和人民事业就会兴旺发达、长盛不衰。身处关键时期，青年应当沿着英雄的足迹，英勇向前，永远听党话、跟党走，勇担民族复兴的时代大任。","(2)把个人奋斗同国家前途命运紧紧联系在一起，实质上就是坚持个人理想与社会理想的有机结合，坚持个人奋斗目标与国家、民族的奋斗目标相统一，把个人理想融入社会理想之中，在为实现社会理想而奋斗的过程中实现个人理想。第一，怀爱国之心。爱国，是人世间最深层、最持久的情感，是一个人的立德之源、立功之本。","爱国主义是中华民族的民族心、民族魂，对于每一个中国人来说，爱国是本分，也是职责，是心之所系、情之所归。第二，立报国之志。以国家富强为念，以人民幸福为盼，忠心爱国、矢志报国，把个人小我融人国家大我，在为国尽责、为民服务中实现个人价值、展现人生风采。第三，增强国之能。爱国不能停留在口号上。","要顺应时代发展新要求，学习新知识、掌握新技能、练就真本领。青年时期是创新创造的宝贵时期，新时代青年要发扬勇攀高峰、敢为人先的创新精神，树立敢于突破陈规、大胆探索未知、勇于创新创造的思想观念，不断增强创新意识，夯实创新本领，在创新创造中不断积累经验、取得成果、演绎精彩。"],"explanation":"文明的积累，更需要精神文明的升华。传承红色基因、续红色血脉，缅怀英烈事迹、传承英烈\n精神，都是对世界观、人生观、价值观的洗礼，会转化成爱国情、强国志、报国行的内生动力。青\n年时期是价值观养成的关键阶段，青年人用自已的方式走近英雄、礼赞英雄，是唤醒人生意义的\n自我升华。新时代是奋斗者的时代，是呼唤英雄也创造英雄的时代。英雄辈出，党和人民事业\n就会兴旺发达、长盛不衰。身处关键时期，青年应当沿着英雄的足迹，英勇向前，永远听党话、跟\n党走，勇担民族复兴的时代大任。\n(2)把个人奋斗同国家前途命运紧紧联系在一起，实质上就是坚持个人理想与社会理想的\n有机结合，坚持个人奋斗目标与国家、民族的奋斗目标相统一，把个人理想融入社会理想之中，\n在为实现社会理想而奋斗的过程中实现个人理想。\n第一，怀爱国之心。爱国，是人世间最深层、最持久的情感，是一个人的立德之源、立功之\n本。爱国主义是中华民族的民族心、民族魂，对于每一个中国人来说，爱国是本分，也是职责，是\n心之所系、情之所归。\n第二，立报国之志。以国家富强为念，以人民幸福为盼，忠心爱国、矢志报国，把个人小我融\n人国家大我，在为国尽责、为民服务中实现个人价值、展现人生风采。\n第三，增强国之能。爱国不能停留在口号上。要顺应时代发展新要求，学习新知识、掌握新\n技能、练就真本领。\n青年时期是创新创造的宝贵时期，新时代青年要发扬勇攀高峰、敢为人先的创新精神，树立\n敢于突破陈规、大胆探索未知、勇于创新创造的思想观念，不断增强创新意识，夯实创新本领，在\n创新创造中不断积累经验、取得成果、演绎精彩。","tags":["肖四","第1套","材料分析题"]},
  {"id":"q-sixiu-7","type":"choice","module":"思想道德与法治","difficulty":1,"stem":"法治思维是指以法治价值和法治精神为导向，运用法律原则、法律规则、法律方法思考和处理问题的思维模式。法治思维以法律原则和法律规则为依据来指导人们的社会行为，这是在强调，法治思维是一种","options":[{"key":"A","text":"正当性思维"},{"key":"B","text":"规范思维"},{"key":"C","text":"逻辑思维"},{"key":"D","text":"底线思维"}],"answerKey":"B","explanation":"法治思维包含以下几层含义：（1)法治思维以法治价值和法治精神为指导，蕴含着公正、平\n等、民主、人权等法治理念,是一种正当性思维；(2)法治思维以法律原则和法律规则为依据来指\n导人们的社会行为，是一种规范思维；（3)法治思维以法律手段与法律方法为依托分析问题、处\n理问题、解决纠纷,是一种逻辑思维；（4)法治思维是一种符合规律、尊重事实的科学思维。因\n此,法治思维是一种融法律的价值属性和工具理性于一体的特殊的高级法律意识。B正确，A、\nC、D错误。","tags":["肖四","第2套","单选题"]},
  {"id":"q-sixiu-8","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"“维护国家法治统一”是习近平法治思想的原创性概念、标识性概念，是习近平法治思想的重要理论创新成果。市场经济是法治经济，要用法治来规范政府和市场的边界。完善维护国家法治统一制度机制，维护国家法治统一，有利于","options":[{"key":"A","text":"消除区域市场分割和地方保护"},{"key":"B","text":"保障全国统一大市场建设"},{"key":"C","text":"加快构建高水平社会主义市场经济体制"},{"key":"D","text":"夯实高质量发展制度根基"}],"answerKeys":["A","B","C","D"],"explanation":"市场经济是法治经济，要用法治来规范政府和市场的边界。完善维护国家法治统一制度\n机制，维护国家法治统一，对于消除区域市场分割和地方保护，保障全国统一大市场建设，加快\n构建高水平社会主义市场经济体制，加快构建新发展格局，夯实高质量发展制度根基具有重要\n意义。A、B、C、D全选。","tags":["肖四","第2套","多选题"]},
  {"id":"q-sixiu-9","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"2024年9月29日，习近平在国家勋章和国家荣誉称号颁授仪式上的讲话中强调，要胸怀强国之志，以国家富强为念，以人民幸福为盼，忠心爱国、矢志报国，把个人小我融人国家大我，在为国尽责、为民服务中实现个人价值、展现人生风采。在整个理想体系中，社会理想是最根本、最重要的，而个人理想则从属于社会理想。这是因为","options":[{"key":"A","text":"个人理想的确立要以社会理想为导向"},{"key":"B","text":"个人理想的实现依赖于社会理想的指引"},{"key":"C","text":"从根本上说个人理想是由社会理想规定的"},{"key":"D","text":"社会理想是个人理想的登加"}],"answerKeys":["A","B","C"],"explanation":"而要顺应社会发展的客观规律和趋势要求；个人理想的实现不仅仅是个人奋斗的事情，而是\n要担当时代赋予的社会责任和历史使命。从根本上说，个人理想是由社会理想规定的。个人理\n想的确立要以社会理想为导向，个人理想的实现依赖于社会理想的指引。A、B、C正确。社会理\n想是个人理想的汇聚和升华，不是叠加，D错误。","tags":["肖四","第2套","多选题"]},
  {"id":"q-sixiu-10","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"平等是社会主义法律的基本属性，是社会主义法治的基本要求。坚持法律面前人人平等,有利于","options":[{"key":"A","text":"增强人民群众的主人翁意识和责任感"},{"key":"B","text":"预防特权思想和各种潜规则的侵蚀"},{"key":"C","text":"贯彻执行“以事实为根据，以法律为准绳”的司法原则"},{"key":"D","text":"维护法律权威、健全社会主义法治，确保实现全面依法治国的总目标"}],"answerKeys":["A","B","C","D"],"explanation":"平等是社会主义法律的基本属性，是社会主义法治的基本要求。坚持法律面前人人平等，\n对于坚持走中国特色社会主义法治道路具有十分重要的意义。（1)它可以充分显示中国特色社\n会主义制度的优越性，使人民在依法治国中的主体地位得到尊重和保障，从而有利于增强人民\n群众的主人翁意识和责任感。（2）它鲜明地反对法外特权、法外开恩，对掌握公权力的人形成制\n约，从而有利于预防特权思想和各种潜规则的侵蚀。（3)它鲜明地反对法律适）\n有利于贯彻执行“以事实为根据，以法律为准绳”的司法原则。（4)它要求人人都严格依法办事，\n既充分享有法律规定的各项权利，又切实履行法律规定的各项义务，有利于维护法律权威、健全\n社会主义法治，确保实现全面依法治国的总目标。A、B、C、D全选。","tags":["肖四","第2套","多选题"]},
  {"id":"q-sixiu-11","type":"material","module":"思想道德与法治","difficulty":3,"stem":"结合材料回答问题：（1）为什么说“传承和弘扬伟大抗战精神，不仅是中国日新月异的重要密码，更是在新征程上创造新的历史伟业的力量源泉”？（2）为什么要“大力弘扬劳模精神、劳动精神、工匠精神”？","material":{"title":"材料","paragraphs":["材料1 历史承载过去，也启迪未来。新时代新征程，全国各族人民要在中国共产党坚强领导下，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻新时代中国特色社会主义思想，坚定不移走中国特色社会主义道路，传承和弘扬伟大抗战精神，踏厉奋发、勇毅前行，为以中国式现代化全面推进强国建设、民族复兴伟业而团结奋斗！","摘自习近平《在纪念中国人民抗日战争暨世界反法西斯战争胜利80周年大会上的讲话》","材料2 今天，神州大地欣欣向荣。当盛大阅兵仪式气势如虹，当雄壮的国歌旋律响起，当抗战老兵感慨“看到国家这么强大，当年的苦没白吃”……人们真切感受到，传承和弘扬伟大抗战精神，不仅是中国日新月异的重要密码，更是在新征程上创造新的历史伟业的力量源泉。","摘编自《人民日报》（2025年9月5日）","材料3 要深入践行社会主义核心价值观，大力弘扬劳模精神、劳动精神、工匠精神。工人阶级和广大劳动群众在长期奋斗中铸就的劳模精神、劳动精神、工匠精神，是社会主义核心价值观的生动体现。要大力弘扬劳动最光荣、劳动最崇高、劳动最伟大、劳动最美丽的社会风尚，营造尊重劳动、尊重知识、尊重人才、尊重创造的良好氛围，激励全体人民通过辛勤劳动、诚实劳动、创造性劳动实现对美好生活的向往。","摘自习近平《在庆祝中华全国总工会成立100周年暨全国劳动模范","和先进工作者表彰大会上的讲话》"]},"answerPoints":["族在生死存亡关头用鲜血和生命铸就的精神丰碑，是中国精神的重要组成部分。这一精神继承和发扬了以爱国主义为核心的民族精神，是激励中国人民战胜一切艰难险阻的强大精神动力。第二，伟大抗战精神是中国发展进步的重要精神密码。","在中国共产党的领导下，中国人民凭借伟大抗战精神等革命精神所凝聚的奋斗伟力，取得了革命、建设、改革的辉煌成就，推动国家面貌发生了日新月异的历史性变化。第三，伟大抗战精神是新征程上创造历史伟业的强大力量源泉。实现中华民族伟大复兴，既需要强大的实力保障，也需要强大的精神支撑。","伟大抗战精神彰显着中华民族骨子里的性格、血脉里的基因，是强国建设、民族复兴的强劲动力。我们必须把弘扬伟大抗战精神体现在以中国式现代化全面推进强国建设、民族复兴伟业的各领域、全过程。伟大抗战精神，既是历史的，见证了我们过去抗战的胜利；也是现实的，作为“密码”驱动了我们的发展；","更是未来的，作为“力量源泉”必将支撑我们在新征程上克服一切艰难险阻，最终实现中华民族的伟大复兴。伟大抗战精神将永远激励中国人民克服一切艰难险阻、为实现中华民族伟大复兴而奋斗。(2)劳动是一切幸福的源泉。在职业生活中，必须牢固树立“劳动最光荣、劳动最崇高、劳动最伟大、劳动最美丽”的观念，通过劳动创造更加美好的生活。","只要踏实劳动、勤勉工作，在平凡岗位上也能干出不平凡的业绩。爱岗敬业是职业生活中的基本道德规范之一。爱岗敬业体现的是从业者热爱工作岗位、对工作极端负责、敬重自已所从事职业的道德操守，是从业者对工作勤奋努力、恪尽职守的行为表现。劳模精神、劳动精神、工匠精神是社会主义核心价值观的生动体现，是全党全国各族人民昂扬奋进的强大精神动力。","我们要弘扬劳模精神，形成榜样力量，激励人们以职业精神、专业精神争创一流、争做模范，在平凡的岗位上做出不平凡的成绩；弘扬劳动精神，汇聚广泛力量，激励人们在各自岗位上发光发热，依靠勤劳双手和劳动创造扎实推进中国式现代化；弘扬工匠精神，培育时代新人，激励人们勤学苦练，不断提高技术技能水平，为中国式现代化创造更加坚实的物质基础。"],"explanation":"族在生死存亡关头用鲜血和生命铸就的精神丰碑，是中国精神的重要组成部分。这一精神继承\n和发扬了以爱国主义为核心的民族精神，是激励中国人民战胜一切艰难险阻的强大精神动力。\n第二，伟大抗战精神是中国发展进步的重要精神密码。在中国共产党的领导下，中国人民\n凭借伟大抗战精神等革命精神所凝聚的奋斗伟力，取得了革命、建设、改革的辉煌成就，推动国\n家面貌发生了日新月异的历史性变化。\n第三，伟大抗战精神是新征程上创造历史伟业的强大力量源泉。实现中华民族伟大复兴，\n既需要强大的实力保障，也需要强大的精神支撑。伟大抗战精神彰显着中华民族骨子里的性\n格、血脉里的基因，是强国建设、民族复兴的强劲动力。我们必须把弘扬伟大抗战精神体现在以\n中国式现代化全面推进强国建设、民族复兴伟业的各领域、全过程。\n伟大抗战精神，既是历史的，见证了我们过去抗战的胜利；也是现实的，作为“密码”驱动了\n我们的发展；更是未来的，作为“力量源泉”必将支撑我们在新征程上克服一切艰难险阻，最终实\n现中华民族的伟大复兴。伟大抗战精神将永远激励中国人民克服一切艰难险阻、为实现中华民\n族伟大复兴而奋斗。\n(2)劳动是一切幸福的源泉。在职业生活中，必须牢固树立“劳动最光荣、劳动最崇高、劳动\n最伟大、劳动最美丽”的观念，通过劳动创造更加美好的生活。只要踏实劳动、勤勉工作，在平凡\n岗位上也能干出不平凡的业绩。\n爱岗敬业是职业生活中的基本道德规范之一。爱岗敬业体现的是从业者热爱工作岗位、对\n工作极端负责、敬重自已所从事职业的道德操守，是从业者对工作勤奋努力、恪尽职守的行为\n表现。\n劳模精神、劳动精神、工匠精神是社会主义核心价值观的生动体现，是全党全国各族人民昂\n扬奋进的强大精神动力。我们要弘扬劳模精神，形成榜样力量，激励人们以职业精神、专业精神\n争创一流、争做模范，在平凡的岗位上做出不平凡的成绩；弘扬劳动精神，汇聚广泛力量，激励人\n们在各自岗位上发光发热，依靠勤劳双手和劳动创造扎实推进中国式现代化；弘扬工匠精神，培\n育时代新人，激励人们勤学苦练，不断提高技术技能水平，为中国式现代化创造更加坚实的物质\n基础。","tags":["肖四","第2套","材料分析题"]},
  {"id":"q-sixiu-12","type":"choice","module":"思想道德与法治","difficulty":1,"stem":"《中华人民共和国国家公园法》是我国首部关于国家公园的专门立法。其颁布实施，标志着以国家公园为主体的自然保护地体系建设进人了法治化、规范化的新阶段，对于推进美丽中国建设、实现人与自然和谐共生的现代化具有重大而深远的意义。国家公园建设管理的首要任务是","options":[{"key":"A","text":"生态系统的原真性、完整性保护"},{"key":"B","text":"解决保护空间碎片化和孤岛化问题"},{"key":"C","text":"组织开展形式多样的自然教育活动"},{"key":"D","text":"健全国家公园生态保护补偿机制"}],"answerKey":"A","explanation":"国家公园守护着我国自然生态系统中最重要，自然景观最独特、自然遗产最精华、生物多样性\n最富集的部分。生态系统的原真性、完整性保护是国家公园建设管理的首要任务。A正确。","tags":["肖四","第3套","单选题"]},
  {"id":"q-sixiu-13","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"“怒发冲冠，凭栏处、潇潇雨歇。”抗金名将岳飞留给我们的，除了气吞山河的壮烈，莫须冤死的悲戚，还有一段精忠报国的热血家训。习近平曾多次讲过岳母刺字的故事，强调家风是社会风气的重要组成部分，父母应引导孩子成为对国家和人民有用的人。之所以要注重家教、家风，是因为","options":[{"key":"A","text":"家庭是人生的第一个课堂,父母是孩子的第一任老师"},{"key":"B","text":"良好的家风，对家庭成员的个人修养产生着重要的作用"},{"key":"C","text":"良好的家风,对整个社会道德风尚的形成产生着重要的影响"},{"key":"D","text":"家教是新时代公民道德建设的重点任务"}],"answerKeys":["A","B","C"],"explanation":"A、B、C正确。新时代公民道德建设的重点任务是筑牢理想信念之基、培育和践行社会主\n义核心价值观、传承中华传统美德、弘扬民族精神和时代精神。D错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-sixiu-14","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"我国宪法法律规定了公民享有的一系列权利，主要包括政治权利、宗教信仰自由、人身权利、财产权利、社会经济权利及文化教育权利等。社会经济权利主要包括","options":[{"key":"A","text":"劳动权和休息权"},{"key":"B","text":"私有财产权"},{"key":"C","text":"社会保障权"},{"key":"D","text":"物质帮助权"}],"answerKeys":["A","C","D"],"explanation":"社会经济权利，是指公民要求国家根据社会经济的发展状况，积极采取措施干预社会经济\n生活，加强社会建设，提供社会服务，以促进公民的自由和幸福，保障公民过上健康而有尊严的\n生活的权利。社会经济权利主要包括以下几方面内容：一是劳动权；二是休息权；三是社会保障\n权;四是物质帮助权。A、C、D正确。财产权主要包括以下几方面内容：一是私有财产权，即公民\n个人所有的以财产利益为内容,直接体现财产利益的民事权利；二是继承权,是指继承人依法取\n得被继承人遗产的资格。B错误。","tags":["肖四","第3套","多选题"]},
  {"id":"q-sixiu-15","type":"material","module":"思想道德与法治","difficulty":3,"stem":"结合材料回答问题：（1）结合年轻人响应党的号召到西部边班地区教书育人，对社会发挥了积极作用，自身也得到历练和成长，说明应当怎样认识人生价值？（2）新时代青年应当如何选择职业和工作岗位，为中国式现代化建设贡献青春力量？","material":{"title":"材料","paragraphs":["你们响应党的号召到西部边疆地区教书育人，在促进当地教育事业发展、促进民族团结进步、促进兴边富民和稳边固边中发挥了积极作用，自身也得到历练和成长。这些年，越来越多年轻人选择到西部、到乡村、到基层志愿服务，无私奉献，展现了新时代中国青年昂扬向上的精神风貌和强国有我的责任担当。希望广大青年坚定理想信念，厚植家国情怀，练就过硬本领，发扬奋斗精神，到祖国和人民最需要的地方发光发热，为中国式现代化建设贡献青春力量。","摘自习近平《给新疆阿图什市哈拉峻乡谢依特小学成边支教西部计划","志愿者服务队全体队员的回信》（2025年5月2日）"]},"answerPoints":["值，是个体的人生活动对自已的生存和发展所具有的价值。人生的社会价值，是个体的实践活动对社会、他人所具有的价值。人生.的自我价值和社会价值，既相互区别，又密切联系、相互依存。一方面，人生的自我价值是个体生存和发展的必要条件，人生的自我价值的实现是个体为社会创造更大价值的前提。","另一方面，人生的社会价值是社会存在和发展的重要条件，人生社会价值的实现是个体自我完善、全面发展的保障。年轻人响应党的号召到西部边珊地区教书育人，对社会发挥了积极作用，自身也得到历练和成长，正体现了个人价值与社会价值的密切联系、相互依存。(2）首先，要树立崇高的职业理想。职业活动不仅是人们谋生的手段，也是人们奉献社会、完善自身的必要条件。","其次，要服从社会发展的需要。在考虑个人兴趣和意愿的同时，也要充分考虑社会的需要和现实的可能性，把自已对职业的期望与社会的需要、现实的可能结合起来。最后，要牢固树立幸福生活是靠劳动创造的观念。热爱劳动、勤勉工作，无论从事什么劳动，都要干一行、爱一行、钻一行,脚踏实地,在实践中一步步成长起来。","新时代青年应当坚定理想信念，厚植家国情怀，练就过硬本领，发扬奋斗精神，到祖国和人民最需要的地方发光发热，为中国式现代化建设贡献青春力量。"],"explanation":"值，是个体的人生活动对自已的生存和发展所具有的价值。人生的社会价值，是个体的实践活\n动对社会、他人所具有的价值。人生.的自我价值和社会价值，既相互区别，又密切联系、相互依\n存。一方面，人生的自我价值是个体生存和发展的必要条件，人生的自我价值的实现是个体为\n社会创造更大价值的前提。另一方面，人生的社会价值是社会存在和发展的重要条件，人生社\n会价值的实现是个体自我完善、全面发展的保障。年轻人响应党的号召到西部边珊地区教书育\n人，对社会发挥了积极作用，自身也得到历练和成长，正体现了个人价值与社会价值的密切联\n系、相互依存。\n(2）首先，要树立崇高的职业理想。职业活动不仅是人们谋生的手段，也是人们奉献社会、\n完善自身的必要条件。其次，要服从社会发展的需要。在考虑个人兴趣和意愿的同时，也要充\n分考虑社会的需要和现实的可能性，把自已对职业的期望与社会的需要、现实的可能结合起来。\n最后，要牢固树立幸福生活是靠劳动创造的观念。热爱劳动、勤勉工作，无论从事什么劳动，都\n要干一行、爱一行、钻一行,脚踏实地,在实践中一步步成长起来。\n新时代青年应当坚定理想信念，厚植家国情怀，练就过硬本领，发扬奋斗精神，到祖国和人\n民最需要的地方发光发热，为中国式现代化建设贡献青春力量。","tags":["肖四","第3套","材料分析题"]},
  {"id":"q-sixiu-16","type":"choice","module":"思想道德与法治","difficulty":1,"stem":"习近平曾指出,要懂得“100-1=0”的道理。一个错案的负面影响，足以摧毁九十九个公平裁判积累起来的良好形象。执法司法中万分之一的失误，对当事人就是百分之百的伤害。这说明了公正司法的重要性。公正司法是","options":[{"key":"A","text":"法治社会的基础工程"},{"key":"B","text":"法治的龙头环节"},{"key":"C","text":"维护社会公平正义的最后一道防线"},{"key":"D","text":"维护社会公平正义的决定因素"}],"answerKey":"C","explanation":"公正是法治的生命线，是司法活动最高的价值追求。公正司法是维护社会公平正义的最\n后一道防线。C正确。法律的权威源自人民的内心拥护和真诚信仰，全民守法是法治社会的基\n础工程。A错误。法律是治国之重器,立法是法治的龙头环节。B错误。D不符合题意。","tags":["肖四","第4套","单选题"]},
  {"id":"q-sixiu-17","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"道德功能的发挥和实现所产生的社会影响及实际效果，就是道德的作用。道德","options":[{"key":"A","text":"是维系社会稳定、促进国家发展的重要因素"},{"key":"B","text":"是激励人们改造客观世界和主观世界的一种精神力量"},{"key":"C","text":"在本质上是知行合一的"},{"key":"D","text":"对社会的发展和人的素质的提高总是起着积极的推动作用"}],"answerKeys":["A","B","C"],"explanation":"道德作为维系社会稳定、促进国家发展的重要因素，对巩固特定社会的经济基础和上层建\n筑具有不可替代的重要作用。同时，道德作为激励人们改造客观世界和主观世界的一种精神力\n量，也是提高人的精神境界、促进人的自我完善、推动人的全面发展的内在动力。道德是一种以\n指导人的行为为目的、以形成人的正确行为方式为内容的精神,在本质上是知行合一的。A、B、C\n正确。只有反映先进生产力发展要求和进步阶级利益的道德，才会对社会的发展和人的素质的\n提高产生积极的推动作用，否则，就不利于甚至阻碍社会的发展和人的素质的提高。","tags":["肖四","第4套","多选题"]},
  {"id":"q-sixiu-18","type":"multi","module":"思想道德与法治","difficulty":2,"stem":"马克思说：“没有无义务的权利，也没有无权利的义务。”法律权利与法律义务的关系，就像一枚硬币的两面，不可分割，相互依存。以下说法正确的有","options":[{"key":"A","text":"法律权利的实现必须以相应法律义务的履行为条件"},{"key":"B","text":"法律义务的设定和履行必须以法律权利的行使为根据"},{"key":"C","text":"一个行为不可以同时是权利行为和义务行为"},{"key":"D","text":"每个人既是享受法律权利的主体，又是承担法律义务的主体"}],"answerKeys":["A","B","D"],"explanation":"法律权利与法律义务就像一枚硬币的两面，不可分割，相互依存。在社会生活中，每个人\n既是享受法律权利的主体，又是承担法律义务的主体。在法治国家，不存在只享受权利的主体，\n也不存在只承担义务的主体。法律权利的实现必须以相应法律义务的履行为条件；法律义务的\n设定和履行也必须以法律权利的行使为根据。离开了法律权利，法律义务就失去了履行的价值\n和动力；离开了法律义务，法律权利也形同虚设。A、B、D正确。有些法律权利和法律义务具有\n复合性的关系，即一个行为可以同时是权利行为和义务行为，如劳动的权利和义务、接受义务教\n育的权利和义务等。C错误。","tags":["肖四","第4套","多选题"]},
  {"id":"q-sixiu-19","type":"material","module":"思想道德与法治","difficulty":3,"stem":"结合材料回答问题：（1）为什么说“商业热情不能扰乱公共秋秩序”，旅拍业的勃发展必须建立在“对行业规范的避守之上”？（2）评选·“最美家庭”，大力弘扬爱国爱家、相亲相爱、向上向善、共建共享的社会主义家庭文明新风尚，对全社会弘扬和践行社会主义核心价值观有何重要意义？","material":{"title":"材料","paragraphs":["材料 1 从大理苍洱大道的湖光山色，到重庆洪崖洞的璀璨夜景，从敦煌“飞天”的丝路风情，到古城西安的盛唐气象，在许多热门景区，旅拍已成为旅行体验的“必选项”。这种新型旅游消费形态，不仅成为连接游客与城市文化的纽带，而且成为展现地方特色民俗的重要窗口。伴随着“旅拍热”持续升温，一些乱象也悄然滋生。一些游客为追求“出片效果”，不顾车流在马路中央驻足、穿梭，增添了安全隐患；还有商家把利益凌驾于规则之上，强行拉客、占道拍摄、价格欺诈；社交平台上，部分商家为博服球，随意混搭不同朝代服饰，导致审美畸形等现象·诸多乱象让旅拍服务从“增色项”变成了“添堵项”，也不可避免地对地方文旅品牌产生消极影响。对美的追求不能突破安全红线，商业热情不能扰乱公共秩序，旅拍业的蓬勃发展，必须建立在对游客权益的维护、对行业规范的遵守之上。唯有服务透明度与客户体验需求双重驱动，推动旅拍服务走向标准化、规范化，在竞争市场中建立差异化优势，方能推动旅拍业态实现从量到质的迭代升级。","摘编自《光明日报》","材料2 为深入学习贯彻习近平总书记关于注重家庭家教家风建设的重要论述，大力弘扬爱国爱家、相亲相爱、向上向善、共建共享的社会主义家庭文明新风尚，中央宣传部、全国妇联向全社会发布2025年“最美家庭”。史瑞娟、黄丽丽、白根保、秦庭群、刘发英、徐乃超、南杰次仁、吴淑明、黄义、姚克礼等10户家庭光荣入选2025年“最美家庭”。这些家庭厚植家国情怀、弘扬传统美德、传承优良家风，有的无私奉献带动村民发展冰雪经济，有的矢志农业科研守护大国粮仓，有的弘扬优秀传统文化传播文明新风，有的播撒爱心托举学子成长成才，有的扎根祖国边睡守护一方他们重言传、重身教，教知识、育品德，让美德在家庭中生根、在亲情中升华，引导家庭成员特别是下一代热爱党、热爱祖国、热爱人民、热爱中华民族，在为家庭谋幸福、为他人送温暖、为社会作贡献的过程中捉高了精神境界，成就了人生梦想。广大群众纷纷表示，家是最小国，国是千万家，家庭的命运同国家和民族的前途命运紧密相连，要以“最美家庭”为榜样，自觉发扬光大中华民族传统美德，建设好家庭、涵养好家教、传承好家风，把人生理想、家庭幸福融入强国建设、民族复兴的伟业之中，做新时代的追梦人。","摘编自新华网（2025年5月15日）"]},"answerPoints":["社会成员生活质量的基本保障，更是社会文明的重要标志。为了维护公共利益、公共秩序、社会和谐稳定，人们在社会交往和公共生活中都应遵守社会公德。遵纪守法是全体公民都必须遵循的基本行为准则，是维护公共生活秩序的重要条件，每个社会成员既要遵守国家颁布的有关法律、法规，也要遵守特定公共场所和单位的有关纪律规定。","(2)家庭是社会的基本细胞，家风是社会风气的重要组成部分。良好的家风，对家庭成员的个人修养产生着重要的作用，也对整个社会道德风尚的形成产生着重要的影响。当无数家庭的美好风尚汇聚在一起，便会成为推动整个社会向上向善、维护和谐稳定的深沉力量。","“最美家庭”厚植家国情怀、弘扬传统美德、传承优良家风，与社会主义核心价值观是息息相通的，是涵养社会主义核心价值观的深厚土壤。这些家庭，重言传、重身教，教知识、育品德，让美德在家庭中生根、在亲情中升华，引导家庭成员特别是下一代热爱党、热爱祖国、热爱人民、热爱中华民族，正是社会主义核心价值观的具体体现。","评选“最美家庭”，大力弘扬社会主义家庭文明新风尚，有利于鼓励更多的人向“最美家庭”学习，用社会主义核心价值观影响更多的人，发挥社会主义核心价值观强大的凝聚力、向心力的作用，进一步增进社会团结和谐的最大公约数。"],"explanation":"社会成员生活质量的基本保障，更是社会文明的重要标志。为了维护公共利益、公共秩序、社会\n和谐稳定，人们在社会交往和公共生活中都应遵守社会公德。遵纪守法是全体公民都必须遵循\n的基本行为准则，是维护公共生活秩序的重要条件，每个社会成员既要遵守国家颁布的有关法\n律、法规，也要遵守特定公共场所和单位的有关纪律规定。\n(2)家庭是社会的基本细胞，家风是社会风气的重要组成部分。良好的家风，对家庭成员的\n个人修养产生着重要的作用，也对整个社会道德风尚的形成产生着重要的影响。当无数家庭的\n美好风尚汇聚在一起，便会成为推动整个社会向上向善、维护和谐稳定的深沉力量。\n“最美家庭”厚植家国情怀、弘扬传统美德、传承优良家风，与社会主义核心价值观是息息相\n通的，是涵养社会主义核心价值观的深厚土壤。这些家庭，重言传、重身教，教知识、育品德，让\n美德在家庭中生根、在亲情中升华，引导家庭成员特别是下一代热爱党、热爱祖国、热爱人民、热\n爱中华民族，正是社会主义核心价值观的具体体现。评选“最美家庭”，大力弘扬社会主义家庭\n文明新风尚，有利于鼓励更多的人向“最美家庭”学习，用社会主义核心价值观影响更多的人，发\n挥社会主义核心价值观强大的凝聚力、向心力的作用，进一步增进社会团结和谐的最大公约数。","tags":["肖四","第4套","材料分析题"]}
]

